          </EnterpriseLayout>
        </UserGuard>
      </Route>
      <Route path="/enterprise/esims">
        <UserGuard>
          <EnterpriseLayout>
            <EnterpriseESIMs />
          </EnterpriseLayout>
        </UserGuard>
      </Route>
    </>
  );
}

function renderUserRoutes() {
  return (
    <>
      Account Routes with AccountLayout
      <Route path="/account">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <Profile />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/account/esims">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <MyESIMs />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/account/referrals">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <Referrals />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/account/orders">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <MyOrders />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/account/support">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <AccountSupport />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/account/kyc">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <KYCSubmission />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/my-orders">
        <Redirect to="/account/orders" />
      </Route>
      <Route path="/my-esims">
        <Redirect to="/account/esims" />
      </Route>
      <Route path="/profile">
        <Redirect to="/account" />
      </Route>
      {/* <Route path="/account/kyc">
        <UserGuard>
          <KYCSubmission />
        </UserGuard>
      </Route> */}
      <Route path="/kyc">
        <UserGuard>
          <Redirect to="/account/kyc" />
        </UserGuard>
      </Route>
      <Route path="/notifications">
        <UserGuard>
          <Notifications />
        </UserGuard>
      </Route>
      <Route path="/compare">
        <UserGuard>
          <Compare />
        </UserGuard>
      </Route>
      <Route path="/referrals">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <Referrals />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
      <Route path="/support">
        <UserGuard>
          <LayoutWrapper layout={'public'}>
            <AccountLayout>
              <AccountSupport />
            </AccountLayout>
          </LayoutWrapper>
        </UserGuard>
      </Route>
    </>
  );
}

function Router() {
  const { data: settingsResponse } = useQuery<SettingsState>({
    queryKey: ['/api/public/settings'],
  });

  const dispatch = useAppDispatch();
  useEffect(() => {
    if (
      settingsResponse &&
      typeof settingsResponse === 'object' &&
      !Array.isArray(settingsResponse)
    ) {
      dispatch(setSettings(settingsResponse));
    }
  }, [settingsResponse, dispatch]);

  const faviconUrl =
    settingsResponse?.favicon && `${window.location.origin}${settingsResponse.favicon}`;

  // console.log(faviconUrl, 'check $$$$$$$$$$$$$$$$$$$');

  return (
    <>
      {/*DYNAMIC FAVICON */}
      <Helmet>
        {faviconUrl && (
          <link
            rel="icon"
            type="image/png"
            href={`${faviconUrl}?v=${settingsResponse?.updated_at || Date.now()}`}
          />
        )}
      </Helmet>
      <ScrollToTop />

      <Switch>
        {renderPublicRoutes()}
        {renderEnterpriseRoutes()}
        {/* {renderUserRoutes()} */}
        <Route path="/account/:rest*">
          <UserGuard>
            <LayoutWrapper layout="public">
              <AccountShell />
            </LayoutWrapper>
          </UserGuard>
        </Route>
        {renderAuthRoutes()}
        {/* {renderAdminRoutes()}
      <Route component={NotFound} /> */}
        {/* admin login */}
        <Route path="/admin/login">
          <AdminLogin />
        </Route>

        {/* ✅ ADMIN (AccountShell pattern) */}
        <Route path="/admin/:rest*">
          <AdminGuard>
            <AdminShell />
          </AdminGuard>
        </Route>

        <Route component={NotFound} />
      </Switch>
    </>
  );
}

function LoadingFallback() {
  return (
    <div className="flex items-center justify-center min-h-screen">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
    </div>
  );
}

function App() {
  return (
    <HelmetProvider>
      <QueryClientProvider client={queryClient}>
        {/* ✅ Redux Provider - Add here */}
        <Provider store={store}>
          <PersistGate loading={<LoadingFallback />} persistor={persistor}>
            {/* ✅ SINGLE ThemeProvider - Fixed duplicate */}
            <ThemeProvider>
