          const matchesSearch =
            searchQuery === '' ||
            endpoint.path.toLowerCase().includes(searchQuery.toLowerCase()) ||
            endpoint.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            endpoint.description.toLowerCase().includes(searchQuery.toLowerCase());
