import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { formatDistanceToNow } from 'date-fns';
import { SiteHeader } from '@/components/layout/SiteHeader';
import { SiteFooter } from '@/components/layout/SiteFooter';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Bell, Check, Filter, ChevronLeft, ChevronRight } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { Helmet } from 'react-helmet-async';
import { useTranslation } from '@/contexts/TranslationContext';

interface Notification {
  id: string;
  userId: string;
  type: string;
  title: string;
  message: string;
  read: boolean;
  metadata: Record<string, any> | null;
  createdAt: string;
}

export default function Notifications() {
  const { toast } = useToast();
  const { t } = useTranslation();
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const { data, isLoading } = useQuery({
    queryKey: ['/api/notifications', 'v2'],
    queryFn: async () => {
      const res = await apiRequest('GET', '/api/notifications');
      return res.json();
    },
    select: (res: any) => ({
      notifications: res?.data?.notifications ?? [],
      unreadCount: res?.data?.unreadCount ?? 0,
    }),
  });

  const notifications = data?.notifications ?? [];
  const unreadCount = data?.unreadCount ?? 0;

  // Filter notifications based on selected filters
  const filteredNotifications = notifications.filter((notification) => {
    if (typeFilter !== 'all' && notification.type !== typeFilter) return false;
    if (statusFilter === 'unread' && notification.read) return false;
    if (statusFilter === 'read' && !notification.read) return false;
    return true;
  });

  // Paginate filtered results
  const totalPages = Math.ceil(filteredNotifications.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedNotifications = filteredNotifications.slice(startIndex, endIndex);

  // Reset to page 1 when filters change
  const handleFilterChange = (filterType: 'status' | 'type', value: string) => {
    if (filterType === 'status') {
      setStatusFilter(value);
    } else {
      setTypeFilter(value);
    }
    setCurrentPage(1);
  };

  const handleMarkAsRead = async (notificationId: string) => {
    try {
      await apiRequest('PATCH', `/api/notifications/${notificationId}/read`, {});
      await queryClient.invalidateQueries({ queryKey: ['/api/notifications'] });
    } catch (error) {
      toast({
        title: t('common.error', 'Error'),
        description: t('notifications.markAsReadFailed', 'Failed to mark notification as read'),
        variant: 'destructive',
      });
    }
  };

  const handleMarkAllAsRead = async () => {
    try {
      await apiRequest('PATCH', '/api/notifications/read-all', {});
      await queryClient.invalidateQueries({ queryKey: ['/api/notifications'] });
      toast({
        title: t('common.success', 'Success'),
        description: t('notifications.allMarkedAsRead', 'All notifications marked as read'),
      });
    } catch (error) {
      toast({
        title: t('common.error', 'Error'),
        description: t(
          'notifications.markAllAsReadFailed',
          'Failed to mark all notifications as read',
        ),
        variant: 'destructive',
      });
    }
  };

  const getNotificationTypeColor = (type: string) => {
    switch (type) {
      case 'welcome':
        return 'bg-primary/10 text-primary';
      case 'purchase':
      case 'installation':
        return 'bg-green-500/10 text-green-700 dark:text-green-400';
      case 'topup':
        return 'bg-teal-500/10 text-teal-700 dark:text-teal-400';
      case 'expiring':
      case 'expired':
        return 'bg-orange-500/10 text-orange-700 dark:text-orange-400';
      case 'ticket_reply':
        return 'bg-teal-500/10 text-teal-700 dark:text-teal-400';
      default:
        return 'bg-muted text-muted-foreground';
    }
  };

  return (
    <>
      <Helmet>
        <title>Notifications | eSIM Global</title>
        <meta
          name="description"
          content="View all your notifications and stay updated on your eSIM orders, top-ups, and support tickets."
        />
      </Helmet>

      <div className="min-h-screen flex flex-col  ">
        {/* <SiteHeader /> */}
        <main className="flex-1 bg-background ">
          <div className="container mx-auto px-4 py-8 max-w-4xl pt-[100px] md:pt-[150px]">
            <div className="space-y-4 mb-6">
              <div className="flex items-center justify-between">
                <div>
                  <h1
                    className="text-3xl font-semibold mb-2 text-foreground"
                    data-testid="text-page-title"
                  >
                    {t('notifications.title', 'Notifications')}
                  </h1>
                  <p className="text-muted-foreground" data-testid="text-page-description">
                    {t(
                      'notifications.description',
                      'Stay updated on your eSIM orders, top-ups, and support tickets',
                    )}
                  </p>
                </div>
                {unreadCount > 0 && (
                  <Button onClick={handleMarkAllAsRead} data-testid="button-mark-all-read-page">
                    <Check className="h-4 w-4 mr-2" />
                    {t('notifications.markAllAsRead', 'Mark all as read')}
                  </Button>
                )}
              </div>

              <div className="flex flex-wrap gap-4 items-center">
                <div className="flex items-center gap-2">
                  <Filter className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm font-medium text-foreground">
                    {t('notifications.filters', 'Filters:')}
                  </span>
                </div>
                <Select
                  value={statusFilter}
                  onValueChange={(value) => handleFilterChange('status', value)}
                >
                  <SelectTrigger
                    className="w-40 text-foreground"
                    data-testid="select-status-filter"
                  >
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">
                      {t('notifications.allStatus', 'All Status')}
                    </SelectItem>
                    <SelectItem value="unread">
                      {t('notifications.unreadOnly', 'Unread Only')}
                    </SelectItem>
                    <SelectItem value="read">{t('notifications.readOnly', 'Read Only')}</SelectItem>
                  </SelectContent>
                </Select>
                <Select
                  value={typeFilter}
                  onValueChange={(value) => handleFilterChange('type', value)}
                >
                  <SelectTrigger className="w-48 text-foreground" data-testid="select-type-filter">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">{t('notifications.allTypes', 'All Types')}</SelectItem>
                    <SelectItem value="welcome">
                      {t('notifications.type.welcome', 'Welcome')}
                    </SelectItem>
                    <SelectItem value="purchase">
                      {t('notifications.type.purchase', 'Purchase')}
                    </SelectItem>
                    <SelectItem value="installation">
                      {t('notifications.type.installation', 'Installation')}
                    </SelectItem>
                    <SelectItem value="topup">{t('notifications.type.topup', 'Top-up')}</SelectItem>
                    <SelectItem value="expiring">
                      {t('notifications.type.expiring', 'Expiring')}
                    </SelectItem>
                    <SelectItem value="ticket_reply">
                      {t('notifications.type.ticketReply', 'Ticket Reply')}
                    </SelectItem>
                    <SelectItem value="custom">
                      {t('notifications.type.custom', 'Custom')}
                    </SelectItem>
                  </SelectContent>
                </Select>
                {(typeFilter !== 'all' || statusFilter !== 'all') && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setTypeFilter('all');
                      setStatusFilter('all');
                      setCurrentPage(1);
                    }}
                    data-testid="button-clear-filters"
                  >
                    {t('notifications.clearFilters', 'Clear filters')}
                  </Button>
                )}
              </div>
            </div>

            {isLoading ? (
              <div className="text-center py-12">
                <p className="text-muted-foreground">
                  {t('notifications.loading', 'Loading notifications...')}
                </p>
              </div>
            ) : notifications.length === 0 ? (
              <Card className="p-12">
                <div className="text-center">
                  <Bell className="h-16 w-16 mx-auto mb-4 text-muted-foreground" />
                  <h3 className="text-xl font-semibold mb-2" data-testid="text-no-notifications">
                    {t('notifications.noNotifications', 'No notifications yet')}
                  </h3>
                  <p className="text-muted-foreground">
                    {t(
                      'notifications.noNotificationsDesc',
                      "You'll see notifications here when there's activity on your account",
                    )}
                  </p>
                </div>
              </Card>
            ) : filteredNotifications.length === 0 ? (
              <Card className="p-12">
                <div className="text-center">
                  <Filter className="h-16 w-16 mx-auto mb-4 text-muted-foreground" />
                  <h3 className="text-xl font-semibold mb-2" data-testid="text-no-match-filters">
                    {t('notifications.noMatch', 'No notifications match your filters')}
                  </h3>
                  <p className="text-muted-foreground mb-4" data-testid="text-filter-help">
                    {t(
                      'notifications.tryAdjusting',
                      'Try adjusting your filters to see more results',
                    )}
                  </p>
                  <Button
                    variant="outline"
                    onClick={() => {
                      setTypeFilter('all');
                      setStatusFilter('all');
                      setCurrentPage(1);
                    }}
                    data-testid="button-clear-all-filters"
                  >
                    {t('notifications.clearAllFilters', 'Clear all filters')}
                  </Button>
                </div>
              </Card>
            ) : (
              <>
                <div className="space-y-3">
                  {paginatedNotifications.map((notification) => (
                    <Card
                      key={notification.id}
                      className={`p-4 hover-elevate transition-all ${
                        !notification.read ? 'bg-accent/10' : ''
                      }`}
                      data-testid={`notification-card-${notification.id}`}
                    >
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-2">
                            <h3
                              className={`text-base font-medium ${
                                !notification.read ? 'font-semibold' : ''
                              }`}
                              data-testid={`notification-title-${notification.id}`}
                            >
                              {notification.title}
                            </h3>
                            <Badge
                              variant="secondary"
                              className={getNotificationTypeColor(notification.type)}
                              data-testid={`notification-type-${notification.id}`}
                            >
                              {notification.type}
                            </Badge>
                            {!notification.read && (
                              <div
                                className="h-2 w-2 rounded-full bg-primary flex-shrink-0"
                                data-testid={`notification-unread-indicator-${notification.id}`}
                              />
                            )}
                          </div>
                          <p
                            className="text-sm text-muted-foreground mb-3"
                            data-testid={`notification-message-${notification.id}`}
                          >
                            {notification.message}
                          </p>
                          <p
                            className="text-xs text-muted-foreground"
                            data-testid={`notification-time-${notification.id}`}
                          >
                            {formatDistanceToNow(new Date(notification.createdAt), {
                              addSuffix: true,
                            })}
                          </p>
                        </div>
                        {!notification.read && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleMarkAsRead(notification.id)}
                            data-testid={`button-mark-read-${notification.id}`}
                          >
                            {t('notifications.markAsRead', 'Mark as read')}
                          </Button>
                        )}
                      </div>
                    </Card>
                  ))}
                </div>

                {totalPages > 1 && (
                  <div className="flex items-center justify-between mt-6 pt-6 border-t">
                    <p className="text-sm text-muted-foreground">
                      {t(
                        'notifications.showing',
                        'Showing {{start}}-{{end}} of {{total}} notifications',
                        {
                          start: startIndex + 1,
                          end: Math.min(endIndex, filteredNotifications.length),
                          total: filteredNotifications.length,
                        },
                      )}
                    </p>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                        disabled={currentPage === 1}
                        data-testid="button-prev-page"
                      >
                        <ChevronLeft className="h-4 w-4 mr-1" />
                        {t('notifications.previous', 'Previous')}
                      </Button>
                      <span className="text-sm font-medium">
                        {t('notifications.pageOf', 'Page {{current}} of {{total}}', {
                          current: currentPage,
                          total: totalPages,
                        })}
                      </span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                        disabled={currentPage === totalPages}
                        data-testid="button-next-page"
                      >
                        {t('notifications.next', 'Next')}
                        <ChevronRight className="h-4 w-4 ml-1" />
                      </Button>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </main>
        {/* <SiteFooter /> */}
      </div>
    </>
  );
}

client/src/pages/admin/PagesManagement.t.content:
import { useState, useEffect } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import {
  Plus,
  Trash2,
  Edit2,
  FileText,
  Loader2,
  Eye,
  EyeOff,
  Bold,
  Italic,
  List,
  ListOrdered,
} from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { useToast } from '@/hooks/use-toast';
import { apiRequest, queryClient } from '@/lib/queryClient';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';

/* ✅ TipTap */
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Link from '@tiptap/extension-link';
import Image from '@tiptap/extension-image';

interface Page {
  id: string;
  slug: string;
  title: string;
  content: string;
  metaTitle?: string | null;
  metaDescription?: string | null;
  isPublished: boolean;
  createdAt: string;
  updatedAt: string;
}

export default function PageManagement() {
  const { toast } = useToast();

  const [showAddDialog, setShowAddDialog] = useState(false);
  const [editingPage, setEditingPage] = useState<Page | null>(null);

  const [formData, setFormData] = useState({
    slug: '',
    title: '',
    content: '',
    metaTitle: '',
    metaDescription: '',
    isPublished: false,
  });

  /* ================= TipTap Editor ================= */
  const editor = useEditor({
    extensions: [
      StarterKit,
      Link.configure({ openOnClick: false }),
      Image,
    ],
    content: '',
    onUpdate: ({ editor }) => {
      setFormData((prev) => ({
        ...prev,
        content: editor.getHTML(),
      }));
    },
  });

  useEffect(() => {
    if (!showAddDialog && !editingPage) {
      editor?.commands.clearContent();
    }
  }, [showAddDialog, editingPage]);

  /* ---------------- FETCH PAGES ---------------- */
  const { data, isLoading } = useQuery({
    queryKey: ['/api/pages'],
    queryFn: async () => {
      const res = await apiRequest('GET', '/api/pages');
      return res.json();
    },
  });

  const pages = data?.data || [];

  /* ---------------- MUTATIONS ---------------- */
  const addPageMutation = useMutation({
    mutationFn: async (payload: typeof formData) => {
      const res = await fetch('/api/pages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error('Failed to create page');
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/pages'] });
      resetForm();
      setShowAddDialog(false);
      toast({ title: 'Success', description: 'Page created successfully' });
    },
  });

  const updatePageMutation = useMutation({
    mutationFn: async ({ id, payload }: { id: string; payload: typeof formData }) => {
      const res = await fetch(`/api/pages/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error('Failed to update page');
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/pages'] });
      resetForm();
      setEditingPage(null);
      toast({ title: 'Success', description: 'Page updated successfully' });
    },
  });

  const deletePageMutation = useMutation({
    mutationFn: async (id: string) => apiRequest('DELETE', `/api/pages/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/pages'] });
      toast({ title: 'Deleted', description: 'Page deleted successfully' });
    },
  });

  const togglePublishMutation = useMutation({
    mutationFn: async ({ id, isPublished }: { id: string; isPublished: boolean }) => {
      const res = await fetch(`/api/pages/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isPublished }),
      });
      if (!res.ok) throw new Error('Failed to update status');
      return res.json();
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['/api/pages'] }),
  });

  /* ---------------- HELPERS ---------------- */
  const resetForm = () => {
    setFormData({
      slug: '',
      title: '',
      content: '',
      metaTitle: '',
      metaDescription: '',
      isPublished: false,
    });
  };

  const generateSlug = (title: string) =>
    title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

  const openEditDialog = (page: Page) => {
    setEditingPage(page);
    setFormData({
      slug: page.slug,
      title: page.title,
      content: page.content,
      metaTitle: page.metaTitle || '',
      metaDescription: page.metaDescription || '',
      isPublished: page.isPublished,
    });

    setTimeout(() => {
      editor?.commands.setContent(page.content || '');
    }, 0);
  };

  /* ================= UI ================= */
  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Page Management</h1>
          <p className="text-muted-foreground">Manage static CMS pages</p>
        </div>
        <Button
          onClick={() => {
            resetForm();
            setShowAddDialog(true);
          }}
        >
          <Plus className="h-4 w-4 mr-2" />
          Add Page
        </Button>
      </div>

      {/* TABLE */}
      <Card>
        <CardHeader>
          <CardTitle className="flex gap-2 items-center">
            <FileText className="h-5 w-5" /> Pages
          </CardTitle>
          <CardDescription>All static pages</CardDescription>
        </CardHeader>

        <CardContent>
          {isLoading ? (
            <div className="flex justify-center py-10">
              <Loader2 className="h-6 w-6 animate-spin" />
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Title</TableHead>
                  <TableHead>Slug</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Updated</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {pages.map((page: Page) => (
                  <TableRow key={page.id}>
                    <TableCell>{page.title}</TableCell>
                    <TableCell>/{page.slug}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={page.isPublished}
                          onCheckedChange={(checked) =>
                            togglePublishMutation.mutate({
                              id: page.id,
                              isPublished: checked,
                            })
                          }
                        />
                        <Badge variant={page.isPublished ? 'default' : 'secondary'}>
                          {page.isPublished ? (
                            <>
                              <Eye className="h-3 w-3 mr-1" /> Published
                            </>
                          ) : (
                            <>
                              <EyeOff className="h-3 w-3 mr-1" /> Draft
                            </>
                          )}
                        </Badge>
                      </div>
                    </TableCell>
                    <TableCell>
                      {new Date(page.updatedAt).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button variant="ghost" size="icon" onClick={() => openEditDialog(page)}>
                        <Edit2 className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => deletePageMutation.mutate(page.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* ADD / EDIT DIALOG */}
      <Dialog
        open={showAddDialog || !!editingPage}
        onOpenChange={() => {
          setShowAddDialog(false);
          setEditingPage(null);
          resetForm();
          editor?.commands.clearContent();
        }}
      >
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingPage ? 'Edit Page' : 'Add Page'}</DialogTitle>
            <DialogDescription>Manage page content & SEO</DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Label>Page Title *</Label>
              <Input
                value={formData.title}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    title: e.target.value,
                    slug: generateSlug(e.target.value),
                  })
                }
              />
            </div>

            <div>
              <Label>URL Slug *</Label>
              <Input
                value={formData.slug}
                onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
              />
            </div>

            {/* TipTap Editor */}
            <div>
              <Label>Page Content *</Label>

              <div className="border rounded-md">
                {/* Toolbar */}
                <div className="flex gap-2 border-b p-2 bg-muted">
                  <Button size="icon" variant="ghost" onClick={() => editor?.chain().focus().toggleBold().run()}>
                    <Bold className="h-4 w-4" />
                  </Button>
                  <Button size="icon" variant="ghost" onClick={() => editor?.chain().focus().toggleItalic().run()}>
                    <Italic className="h-4 w-4" />
                  </Button>
                  <Button size="icon" variant="ghost" onClick={() => editor?.chain().focus().toggleBulletList().run()}>
                    <List className="h-4 w-4" />
                  </Button>
                  <Button size="icon" variant="ghost" onClick={() => editor?.chain().focus().toggleOrderedList().run()}>
                    <ListOrdered className="h-4 w-4" />
                  </Button>
                </div>

                <EditorContent
                  editor={editor}
                  className="min-h-[300px] p-3 prose max-w-none"
                />
              </div>
            </div>

            <div>
              <Label>Meta Title</Label>
              <Input
                value={formData.metaTitle}
                onChange={(e) => setFormData({ ...formData, metaTitle: e.target.value })}
              />
            </div>

            <div>
              <Label>Meta Description</Label>
              <textarea
                className="w-full border rounded-md p-2 text-sm"
                rows={3}
                value={formData.metaDescription}
                onChange={(e) =>
                  setFormData({ ...formData, metaDescription: e.target.value })
                }
              />
            </div>

            <div className="flex items-center gap-3">
              <Switch
                checked={formData.isPublished}
                onCheckedChange={(checked) => setFormData({ ...formData, isPublished: checked })}
              />
              <Label>Publish immediately</Label>
            </div>
          </div>

          <DialogFooter>
            <Button
              onClick={() =>
                editingPage
                  ? updatePageMutation.mutate({
                      id: editingPage.id,
                      payload: formData,
                    })
                  : addPageMutation.mutate(formData)
              }
            >
              {editingPage ? 'Update Page' : 'Create Page'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

