interface OTPRequest {
  email: string;
}

interface OTPVerify {
  email: string;
  otp: string;
}

interface AuthResponse {
  success: boolean;
  message: string;
  user?: {
    id: string;
    email: string;
    name?: string;
  };
}

export function useRequestOTP() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: OTPRequest): Promise<AuthResponse> => {
      const res = await apiRequest("POST", "/api/auth/send-otp", data);
      return res.json();
    },
  });
}

export function useVerifyOTP() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: OTPVerify): Promise<AuthResponse> => {
      const res = await apiRequest("POST", "/api/auth/verify-otp", data);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/me"] });
    },
  });
}

export function useLogout() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (): Promise<void> => {
      await apiRequest("POST", "/api/auth/logout", {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/me"] });
      queryClient.invalidateQueries({ queryKey: ["/api/orders"] });
      queryClient.invalidateQueries({ queryKey: ["/api/my-esims"] });
    },
  });
}

