import { Link } from 'wouter';
import { Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { useQuery } from '@tanstack/react-query';
import { useCurrency } from '@/contexts/CurrencyContext';
import { convertPrice, getCurrencySymbol } from '@/lib/currency';
import { PlanCommonCard } from '@/components/PlanCommonCard';
import { Card, CardContent } from '@/components/ui/card';
import { CompletePackageType, PlanCommonCardProps } from '@/types/types';

export function CompleteEsims() {
  const { currency, currencies } = useCurrency();
  const currencySymbol = getCurrencySymbol(currency, currencies);

  const { data: packages = [], isLoading } = useQuery<CompletePackageType[]>({
    queryKey: ['/api/packages/complete'],
  });

  const completePackages = packages.slice(0, 4);

  console.log('completePackages', completePackages);

  const calculatePerDay = (price: string, days: number) => {
    const priceNum = parseFloat(price);
    const convertedPrice = convertPrice(priceNum, 'USD', currency, currencies);
    return convertedPrice / days;
  };

  const transformPackageToCardProps = (pkg: CompletePackageType): PlanCommonCardProps => {
    const convertedPrice = convertPrice(parseFloat(pkg.retailPrice), 'USD', currency, currencies);

    return {
      id: pkg.id,
      title: pkg.title,
      countryCode: pkg.destination?.countryCode,
      countryName: pkg.destination?.name || 'Global',
      dataAmount: pkg.dataAmount,
      validity: pkg.validity,
      price: convertedPrice.toFixed(2),
      pricePerDay: calculatePerDay(pkg.retailPrice, pkg.validity).toFixed(2),
      currencySymbol,
      voiceMinutes: pkg.voiceMinutes,
      smsCount: pkg.smsCount,
      destinationSlug: pkg.destination?.slug,
      isComplete: true,
    };
  };

  const SkeletonCard = () => (
    <Card className="border-border/50 overflow-hidden">
      <CardContent className="p-0">
        <div className="p-5">
          <div className="h-6 w-32 bg-muted animate-pulse rounded mb-4" />
          <div className="flex gap-6 mb-4">
            <div className="h-10 w-16 bg-muted animate-pulse rounded" />
            <div className="h-10 w-16 bg-muted animate-pulse rounded" />
            <div className="h-10 w-16 bg-muted animate-pulse rounded" />
          </div>
          <div className="h-8 w-24 bg-muted animate-pulse rounded mb-2" />
          <div className="h-4 w-20 bg-muted animate-pulse rounded mb-4" />
          <div className="space-y-2 mb-4">
            <div className="h-4 w-32 bg-muted animate-pulse rounded" />
            <div className="h-4 w-28 bg-muted animate-pulse rounded" />
          </div>
          <div className="h-10 w-full bg-muted animate-pulse rounded mb-2" />
          <div className="h-10 w-full bg-muted animate-pulse rounded" />
        </div>
      </CardContent>
    </Card>
  );

  if (!isLoading && completePackages.length === 0) {
    return null;
  }

  return (
    <section className="py-16 md:py-24 bg-gradient-to-b from-violet-50 to-white dark:from-violet-950/30 dark:to-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-10">
          <Badge className="mb-4 bg-gradient-to-r from-primary to-primary-dark text-white px-4 py-1.5 rounded-full">
            <Sparkles className="h-3.5 w-3.5 mr-1.5" />
            All-in-One Plans
          </Badge>

          <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
            Data + Voice + SMS
          </h2>

          <p className="text-muted-foreground mb-6">
            Complete connectivity with data, voice calls, and text messaging included
          </p>

          <Link href="/destinations">
            <Button className="bg-primary-gradient hover:bg-slate-800 dark:bg-slate-100 dark:hover:bg-slate-200 dark:text-slate-900 text-white rounded-full px-6">
              View All Complete Plans
            </Button>
          </Link>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {isLoading ? (
            <>
              <SkeletonCard />
              <SkeletonCard />
              <SkeletonCard />
              <SkeletonCard />
            </>
          ) : (
            completePackages.map((pkg) => (
              <PlanCommonCard key={pkg.id} {...transformPackageToCardProps(pkg)} />
            ))
          )}
        </div>
      </div>
    </section>
  );
}

client/src/pages/enterprise/EnterpriseES.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Helmet } from "react-helmet-async";
import { Smartphone, Send, Download, Plus, X } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";

export default function EnterpriseESIMs() {
  const { toast } = useToast();
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);
  const [employeeEmails, setEmployeeEmails] = useState<string[]>([""]);
  const [isDistributeDialogOpen, setIsDistributeDialogOpen] = useState(false);

  const { data: orders, isLoading } = useQuery({
    queryKey: ["/api/enterprise/orders"],
  });

  const completedOrders = orders?.filter((o: any) => o.status === "completed") || [];

  const distributeMutation = useMutation({
    mutationFn: ({ orderId, emails }: { orderId: string; emails: string[] }) =>
      apiRequest("POST", `/api/enterprise/orders/${orderId}/distribute`, { employeeEmails: emails }),
    onSuccess: (data: any) => {
      toast({
        title: "Distribution Completed",
        description: `${data.totalSent} eSIMs sent successfully, ${data.totalFailed} failed.`,
      });
      setIsDistributeDialogOpen(false);
      setEmployeeEmails([""]);
    },
    onError: (error: any) => {
      toast({
        title: "Distribution Failed",
        description: error.message || "Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleAddEmail = () => {
    setEmployeeEmails([...employeeEmails, ""]);
  };

  const handleRemoveEmail = (index: number) => {
    setEmployeeEmails(employeeEmails.filter((_, i) => i !== index));
  };

  const handleEmailChange = (index: number, value: string) => {
    const newEmails = [...employeeEmails];
    newEmails[index] = value;
    setEmployeeEmails(newEmails);
  };

  const handleDistribute = () => {
    if (!selectedOrderId) return;
    const validEmails = employeeEmails.filter(email => email.trim() && email.includes("@"));
    if (validEmails.length === 0) {
      toast({
        title: "No Valid Emails",
        description: "Please enter at least one valid email address.",
        variant: "destructive",
      });
      return;
    }
    distributeMutation.mutate({ orderId: selectedOrderId, emails: validEmails });
  };

  const handleExport = (orderId: string) => {
    window.open(`/api/enterprise/orders/${orderId}/export`, '_blank');
  };

  if (isLoading) {
    return (
      <div className="p-6 space-y-6">
        <Skeleton className="h-12 w-64" />
        <Skeleton className="h-96" />
      </div>
    );
  }

  return (
    <>
      <Helmet>
        <title>eSIMs | Enterprise Portal</title>
      </Helmet>

      <div className="p-6 space-y-6">
        <div className="flex items-center gap-3">
          <Smartphone className="h-8 w-8 text-primary" />
          <div>
            <h1 className="text-3xl font-bold">eSIM Distribution</h1>
            <p className="text-muted-foreground">Distribute eSIMs to your employees</p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Completed Orders</CardTitle>
            <CardDescription>Orders ready for distribution</CardDescription>
          </CardHeader>
          <CardContent>
            {completedOrders.length > 0 ? (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Order ID</TableHead>
                    <TableHead>Package</TableHead>
                    <TableHead>Quantity</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {completedOrders.map((order: any) => (
                    <TableRow key={order.id}>
                      <TableCell className="font-mono text-xs">{order.id.slice(0, 8)}...</TableCell>
                      <TableCell>
                        {order.quote?.package?.dataAmount} - {order.quote?.package?.validity}
                      </TableCell>
                      <TableCell>{order.quote?.quantity || 0} eSIMs</TableCell>
                      <TableCell>
                        <Badge>{order.status}</Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-2">
                          <Dialog open={isDistributeDialogOpen && selectedOrderId === order.id} onOpenChange={(open) => {
                            setIsDistributeDialogOpen(open);
                            if (open) setSelectedOrderId(order.id);
                            else {
                              setSelectedOrderId(null);
                              setEmployeeEmails([""]);
                            }
                          }}>
                            <DialogTrigger asChild>
                              <Button
                                size="sm"
                                variant="default"
                                data-testid={`button-distribute-${order.id}`}
                              >
                                <Send className="h-4 w-4 mr-1" />
                                Distribute
                              </Button>
                            </DialogTrigger>
                            <DialogContent className="max-w-lg">
                              <DialogHeader>
                                <DialogTitle>Distribute eSIMs to Employees</DialogTitle>
                                <DialogDescription>
                                  Enter employee email addresses to send eSIM activation details
                                </DialogDescription>
                              </DialogHeader>

                              <div className="space-y-4">
                                <div className="space-y-2">
                                  {employeeEmails.map((email, index) => (
                                    <div key={index} className="flex gap-2">
                                      <Input
                                        type="email"
                                        placeholder="employee@company.com"
                                        value={email}
                                        onChange={(e) => handleEmailChange(index, e.target.value)}
                                        data-testid={`input-employee-email-${index}`}
                                      />
                                      {employeeEmails.length > 1 && (
                                        <Button
                                          type="button"
                                          variant="outline"
                                          size="icon"
                                          onClick={() => handleRemoveEmail(index)}
                                        >
                                          <X className="h-4 w-4" />
                                        </Button>
                                      )}
                                    </div>
                                  ))}
                                </div>

                                <Button
                                  type="button"
                                  variant="outline"
                                  onClick={handleAddEmail}
                                  className="w-full"
                                  data-testid="button-add-email"
                                >
                                  <Plus className="h-4 w-4 mr-2" />
                                  Add Another Email
                                </Button>

                                <div className="flex gap-2">
                                  <Button
                                    onClick={handleDistribute}
                                    disabled={distributeMutation.isPending}
                                    className="flex-1"
                                    data-testid="button-send-emails"
                                  >
                                    <Send className="h-4 w-4 mr-2" />
                                    {distributeMutation.isPending ? "Sending..." : "Send Emails"}
                                  </Button>
                                </div>
                              </div>
                            </DialogContent>
                          </Dialog>

                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleExport(order.id)}
                            data-testid={`button-export-csv-${order.id}`}
                          >
                            <Download className="h-4 w-4 mr-1" />
                            Export CSV
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            ) : (
              <div className="text-center py-12">
                <Smartphone className="h-12 w-12 mx-auto text-muted-foreground/50 mb-4" />
                <p className="text-muted-foreground">
                  No completed orders yet. Accept quotes to create orders.
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </>
  );
}

