import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { voucherSchema, VoucherFormData } from "./types";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Save } from "lucide-react";

export default function VoucherForm({
  initialData,
  onSubmit,
}: {
  initialData?: VoucherFormData;
  onSubmit: (data: any) => void;
}) {
  const form = useForm<VoucherFormData>({
    resolver: zodResolver(voucherSchema),
    defaultValues: {
      code: "",
      type: "",
      value: "",
      minPurchaseAmount: "",
      maxUses: "",
      validFrom: "",
      validUntil: "",
      description: "",
      status: "active",
    },
  });

  // 🔥 FIX: Normalize edit data
  useEffect(() => {
    if (initialData) {
      form.reset(
        {
          ...initialData,
          maxUses:
            initialData.maxUses === null
              ? ""
              : String(initialData.maxUses),
          validFrom: initialData.validFrom?.slice(0, 10),
          validUntil: initialData.validUntil?.slice(0, 10),
        },
        {
          keepErrors: false,
          keepDirty: false,
        }
      );
    }
  }, [initialData]);

 const handleSave = (data: VoucherFormData) => {
  const payload = {
    ...data,
    minPurchaseAmount: data.minPurchaseAmount || "0",
    maxUses: data.maxUses === "" ? null : Number(data.maxUses),

    // ✅ SEND DATE OBJECTS (NOT STRING)
    validFrom: new Date(data.validFrom),
    validUntil: new Date(data.validUntil),

    description: data.description || null,
  };

  onSubmit(payload);
};


  return (
    <form onSubmit={form.handleSubmit(handleSave)} className="space-y-6">
      <div>
        <Label>Voucher Code</Label>
        <Input {...form.register("code")} />
      </div>

      <div>
        <Label>Type</Label>
        <Input {...form.register("type")} />
      </div>

      <div>
        <Label>Value</Label>
        <Input {...form.register("value")} />
      </div>

      <div>
        <Label>Min Purchase Amount</Label>
        <Input {...form.register("minPurchaseAmount")} />
      </div>

      <div>
        <Label>Max Uses</Label>
        <Input {...form.register("maxUses")} type="number" />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label>Valid From</Label>
          <Input {...form.register("validFrom")} type="date" />
        </div>
        <div>
          <Label>Valid Until</Label>
          <Input {...form.register("validUntil")} type="date" />
        </div>
      </div>

      <div>
        <Label>Description</Label>
        <Input {...form.register("description")} />
      </div>

      <div>
        <Label>Status</Label>
        <Select
          value={form.watch("status")}
          onValueChange={(v) =>
            form.setValue("status", v as any, { shouldFocus: false })
          }
        >
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="active">Active</SelectItem>
            <SelectItem value="inactive">Inactive</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <Button type="submit" className="w-full">
        <Save className="h-4 w-4 mr-2" />
        Save Voucher
      </Button>
    </form>
  );
}

client/src/pages/admin/AdminLogin.tsx.content:
import { useState } from 'react';
import { useLocation } from 'wouter';
import { Helmet } from 'react-helmet-async';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import { Globe, Lock } from 'lucide-react';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { useTranslation } from '@/contexts/TranslationContext';

export default function AdminLogin() {
  const { t } = useTranslation();
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const res = await apiRequest('POST', '/api/admin/login', {
        email,
        password,
      });

      const response: any = await res.json();

      const admin = response?.data?.admin;

      if (!admin) {
        throw new Error('Invalid login response');
      }

      toast({
        title: t('admin.login.loginSuccessTitle', 'Login Successful'),
        description: t('admin.login.loginSuccessDesc', 'Welcome back, {{name}}!').replace(
          '{{name}}',
          admin.name,
        ),
      });

      // refresh admin auth state
      await queryClient.invalidateQueries({ queryKey: ['/api/admin/me'] });

      setLocation('/admin/dashboard');
    } catch (error: any) {
      toast({
        variant: 'destructive',
        title: t('admin.login.loginFailedTitle', 'Login Failed'),
        description: error.message || t('admin.login.loginFailedDesc', 'Invalid email or password'),
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleLoginOLD = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const res = await apiRequest('POST', '/api/admin/login', {
        email,
        password,
      });
      const response: any = await res.json();

      toast({
        title: t('admin.login.loginSuccessTitle', 'Login Successful'),
        description: t('admin.login.loginSuccessDesc', 'Welcome back, {{name}}!').replace(
          '{{name}}',
          response.admin.name,
        ),
      });

      // Invalidate admin auth cache so AdminGuard gets fresh data
      await queryClient.invalidateQueries({ queryKey: ['/api/admin/me'] });

      setLocation('/admin/dashboard');
    } catch (error: any) {
      toast({
        variant: 'destructive',
        title: t('admin.login.loginFailedTitle', 'Login Failed'),
        description: error.message || t('admin.login.loginFailedDesc', 'Invalid email or password'),
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <Helmet>
        <title>{String(t('admin.login.pageTitle', 'Admin Login - eSIM Marketplace'))}</title>
      </Helmet>

      <Card className="w-full max-w-md">
        <CardHeader className="space-y-1">
          <div className="flex items-center justify-center mb-4">
            <div className="flex items-center gap-2">
              <Globe className="h-8 w-8 text-primary" />
              <Lock className="h-6 w-6 text-primary" />
            </div>
          </div>
          <CardTitle className="text-2xl text-center" data-testid="text-admin-login-title">
            {t('admin.login.title', 'Admin Login')}
          </CardTitle>
          <CardDescription className="text-center">
            {t('admin.login.description', 'Enter your credentials to access the admin panel')}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">{t('admin.login.emailLabel', 'Email')}</Label>
              <Input
                id="email"
                type="email"
                placeholder={t('admin.login.emailPlaceholder', 'admin@example.com')}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                disabled={isLoading}
                data-testid="input-admin-email"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">{t('admin.login.passwordLabel', 'Password')}</Label>
              <Input
                id="password"
                type="password"
                placeholder={t('admin.login.passwordPlaceholder', 'Enter your password')}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                disabled={isLoading}
                data-testid="input-admin-password"
              />
            </div>
            <Button
              type="submit"
              className="w-full bg-primary-gradient"
              disabled={isLoading}
              data-testid="button-admin-login"
            >
              {isLoading
                ? t('admin.login.loggingIn', 'Logging in...')
                : t('admin.login.loginButton', 'Login')}
            </Button>
          </form>

          <div className="mt-6 p-4 bg-muted rounded-md">
            <p className="text-sm text-muted-foreground text-center">
              {t('admin.login.testCredentialsTitle', 'Default credentials for testing:')}
            </p>
            <div className="mt-2 space-y-1 text-sm font-mono text-center">
              <p>
