    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* ============================================
     ✨ PREMIUM EFFECTS - Using primary colors
     =========================================== */

  .shadow-premium {
    box-shadow: 0 20px 40px -12px color-mix(in srgb, var(--primary-hex) 25%, transparent);
  }

  .dark .shadow-premium {
    box-shadow: 0 20px 40px -12px color-mix(in srgb, var(--primary-hex) 30%, transparent);
  }

  .glass {
    background: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }

  .dark .glass {
    background: rgba(0, 0, 0, 0.2);
  }

  .card-lift {
    transition:
      transform 0.2s ease,
      box-shadow 0.2s ease;
  }

  .card-lift:hover {
    transform: translateY(-4px);
  }

  .phone-shadow {
    box-shadow:
      0 50px 100px -20px rgba(0, 0, 0, 0.25),
      0 30px 60px -30px rgba(0, 0, 0, 0.15),
      inset 0 0 0 1px rgba(255, 255, 255, 0.1);
  }

  .dark .phone-shadow {
    box-shadow:
      0 50px 100px -20px rgba(0, 0, 0, 0.5),
      0 30px 60px -30px rgba(0, 0, 0, 0.35),
      inset 0 0 0 1px rgba(255, 255, 255, 0.05);
  }

  @keyframes marquee {
    0% {
      transform: translateX(0%);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  .animate-marquee {
    animation: marquee 30s linear infinite;
  }

  @keyframes scroll-ticker {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  .animate-scroll-ticker {
    animation: scroll-ticker 25s linear infinite;
  }

  .animate-scroll-ticker:hover {
    animation-play-state: paused;
  }

  @keyframes draw-arrow {
    0% {
      stroke-dashoffset: 100;
      opacity: 0;
    }
    50% {
      opacity: 1;
    }
    100% {
      stroke-dashoffset: 0;
      opacity: 1;
    }
  }

  .animate-draw-arrow {
    stroke-dasharray: 100;
    animation: draw-arrow 1.5s ease-out forwards;
    animation-delay: 0.5s;
  }

  @keyframes fadeInUp {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-fade-in-up {
    animation: fadeInUp 0.5s ease forwards;
  }

  @keyframes pulse-glow {
    0%,
    100% {
      box-shadow: 0 0 20px color-mix(in srgb, var(--primary-hex) 40%, transparent);
    }
    50% {
      box-shadow: 0 0 30px color-mix(in srgb, var(--primary-second-hex) 60%, transparent);
    }
  }

  .animate-pulse-glow {
    animation: pulse-glow 2s ease-in-out infinite;
  }

  @keyframes spin-slow {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }

  .animate-spin-slow {
    animation: spin-slow 20s linear infinite;
  }

  /* ============================================
     🎨 ELEVATION SYSTEM
     =========================================== */

  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: '';
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: -1;
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  .border.toggle-elevate::before {
    inset: -1px;
  }

  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: '';
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: 999;
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after {
    inset: -1px;
  }

  /* ============================================
     📐 CUSTOM CONTAINER
     =========================================== */

  .containers {
    width: 100%;
    margin-left: auto;
    margin-right: auto;
    padding-left: 1rem;
    padding-right: 1rem;
  }

  @media (min-width: 640px) {
    .containers {
      max-width: 620px;
      padding-left: 1.5rem;
      padding-right: 1.5rem;
    }
  }

  @media (min-width: 768px) {
    .containers {
      max-width: 740px;
      padding-left: 2rem;
      padding-right: 2rem;
    }
  }

  @media (min-width: 1024px) {
    .containers {
      max-width: 980px;
    }
  }

  @media (min-width: 1280px) {
    .containers {
      max-width: 1180px;
    }
  }

  @media (min-width: 1536px) {
    .containers {
      max-width: 1350px;
    }
  }

  /* ============================================
     🧹 MISC UTILITIES
     =========================================== */

  input[type='search']::-webkit-search-cancel-button {
    @apply hidden;
  }

  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* ColorPicker.css */
  .color-picker-container {
    max-width: 600px;
    margin: 2rem auto;
    padding: 2rem;
    background: white;
    border-radius: 16px;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
    font-family: 'Inter', sans-serif;
  }

  .color-picker-header {
    text-align: center;
    margin-bottom: 2rem;
  }

  .theme-title {
    font-size: 2rem;
    font-weight: 700;
    background: linear-gradient(135deg, #bfff0b, #9dd707);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin: 0;
  }

  .color-pickers-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
  }

  .color-picker-item {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .color-label {
    font-weight: 600;
    font-size: 0.875rem;
    color: #374151;
    text-transform: capitalize;
  }

  .color-preview-wrapper {
    position: relative;
  }

  .color-preview {
    width: 100%;
    height: 3rem;
    border-radius: 12px;
    border: 2px solid #e5e7eb;
    cursor: pointer;
    transition: all 0.2s ease;
    position: relative;
    overflow: hidden;
  }

  .color-preview:hover {
    border-color: #bfff0b;
    transform: translateY(-2px);
    box-shadow: 0 10px 20px rgba(191, 255, 11, 0.3);
  }

  .color-input {
    font-family: 'SF Mono', monospace;
    font-size: 0.75rem;
    padding: 0.5rem;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    background: #f9fafb;
    color: #111827;
  }

  .color-input:focus {
    outline: none;
    border-color: #bfff0b;
    box-shadow: 0 0 0 3px rgba(191, 255, 11, 0.1);
  }

  .picker-overlay {
    position: absolute;
    top: -10px;
    left: 0;
    right: 0;
    z-index: 1000;
  }

  .picker-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 999;
  }

  .action-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    justify-content: center;
    margin-bottom: 1.5rem;
  }

  .btn-primary,
  .btn-secondary,
  .btn-danger {
    padding: 0.75rem 1.5rem;
    border-radius: 12px;
    font-weight: 600;
    font-size: 0.875rem;
    cursor: pointer;
    border: none;
    transition: all 0.2s ease;
    flex: 1;
    min-width: 140px;
  }

  .bg-primary-gradient-hover:hover {
    background: var(--hero-gradient-hover);
  }

  .btn-primary {
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    color: #000;
    box-shadow: 0 4px 14px rgba(191, 255, 11, 0.4);
  }

  .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(191, 255, 11, 0.6);
  }

  .btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 2px solid #e5e7eb;
  }

  .btn-secondary:hover {
    background: #e5e7eb;
    border-color: #bfff0b;
  }

  .btn-danger {
    background: #ef4444;
    color: white;
  }

  .btn-danger:hover {
    background: #dc2626;
    transform: translateY(-2px);
  }

  .preview-info {
    text-align: center;
    color: #6b7280;
    font-size: 0.875rem;
  }

  /* Dark mode support */
  @media (prefers-color-scheme: dark) {
    .color-picker-container {
      background: #1f2937;
      color: white;
    }

    .color-label {
      color: #d1d5db;
    }
  }
}

