import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { RefreshCw, Search, Server, Package, Globe, MapPin, Info } from "lucide-react";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";

interface Provider {
  id: string;
  name: string;
  slug: string;
  enabled: boolean;
  lastSyncAt: string | null;
}

interface TopupPackage {
  id: string;
  title: string;
  dataAmount: string;
  validity: number;
  price: string;
  currency: string;
  type: string;
  operator: string | null;
  operatorImage: string | null;
  destinationName: string | null;
  regionName: string | null;
  active: boolean;
  provider: string;
  providerName: string;
  createdAt: string;
  parentPackageId: string | null;
  parentOperator: string | null;
  hasParentPackage: boolean;
}

interface TopupsResponse {
  success: boolean;
  data: TopupPackage[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
  stats: {
    airalo: number;
    esimAccess: number;
    esimGo: number;
    maya: number;
    total: number;
  };
}

// Format data amount for display - handles eSIM Go's "-1" for unlimited
function formatDataAmount(dataAmount: string): string {
  if (!dataAmount) return "-";

  // eSIM Go uses "-1" or "-1MB" to mean unlimited
  if (dataAmount === "-1" || dataAmount === "-1MB" || dataAmount === "-1 MB") {
    return "Unlimited";
  }

  // Already formatted as "Unlimited"
  if (dataAmount.toLowerCase() === "unlimited") {
    return "Unlimited";
  }

  // Return as-is for normal data amounts (e.g., "1GB", "500MB")
  return dataAmount;
}

export default function MasterTopups() {
  const { toast } = useToast();
  const [searchInput, setSearchInput] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [providerFilter, setProviderFilter] = useState<string>("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [syncingProviderId, setSyncingProviderId] = useState<string | null>(null);
  const itemsPerPage = 50;

  // Debounce search - wait 300ms after user stops typing
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchInput);
      setCurrentPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchInput]);

  const { data: providers, isLoading: loadingProviders } = useQuery<{
    success: boolean;
    data: Provider[];
  }>({
    queryKey: ["/api/admin/providers"],
    queryFn: async () => {
      const res = await fetch('/api/admin/providers', { credentials: 'include' });
      if (!res.ok) throw new Error('Failed to fetch providers');
      return res.json();
    },
  });

  const { data: topupsData, isLoading: loadingTopups } = useQuery<TopupsResponse>({
    queryKey: ["/api/admin/master-topups", { provider: providerFilter, search: debouncedSearch, page: currentPage }],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (providerFilter !== 'all') params.append('provider', providerFilter);
      if (debouncedSearch) params.append('search', debouncedSearch);
      params.append('page', String(currentPage));
      const url = `/api/admin/master-topups?${params.toString()}`;
      const res = await fetch(url, { credentials: 'include' });
      if (!res.ok) throw new Error('Failed to fetch topups');
      return res.json();
    },
  });

  const syncMutation = useMutation({
    mutationFn: async (providerId: string) => {
      setSyncingProviderId(providerId);
      const response = await apiRequest(
        "POST",
        `/api/admin/providers/${providerId}/sync-topups`
      );
      return response.json();
    },
    onSuccess: (data: any) => {
      setSyncingProviderId(null);
      if (data.success) {
        toast({
          title: "Topup Sync Complete",
          description: `Synced ${data.topupsSynced || 0} topups, updated ${data.topupsUpdated || 0}.`,
        });
        queryClient.invalidateQueries({ queryKey: ["/api/admin/master-topups"] });
        queryClient.invalidateQueries({ queryKey: ["/api/admin/providers"] });
      } else {
        toast({
          title: "Topup Sync Failed",
          description: data.errorMessage || data.message || "Unknown error occurred",
          variant: "destructive",
        });
      }
    },
    onError: (error: any) => {
      setSyncingProviderId(null);
      toast({
        title: "Sync Failed",
        description: error.message || "Failed to trigger topup sync",
        variant: "destructive",
      });
    },
  });

  const enabledProviders = providers?.data?.filter((p) => p.enabled) || [];
  const topups = topupsData?.data || [];
  const stats = topupsData?.stats || { airalo: 0, esimAccess: 0, esimGo: 0, maya: 0, total: 0 };
  const pagination = topupsData?.pagination || { page: 1, limit: 50, total: 0, totalPages: 0 };

  const getProviderBadgeColor = (provider: string) => {
    switch (provider) {
      case 'airalo':
        return 'bg-teal-100 text-teal-800 dark:bg-teal-900 dark:text-teal-200';
      case 'esim-access':
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
      case 'esim-go':
        return 'bg-teal-100 text-teal-800 dark:bg-teal-900 dark:text-teal-200';
      case 'maya':
        return 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-950 dark:text-gray-200';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
            <RefreshCw className="h-6 w-6" />
            Topup Packages
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">
            Manage topup packages for reloading existing eSIMs
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500">
              Total Topup Packages
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total.toLocaleString()}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500 flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-teal-500" />
              Airalo Topups
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.airalo.toLocaleString()}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500 flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-green-500" />
              eSIM Access Topups
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Badge variant="secondary" className="bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200">
              On-demand
            </Badge>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500 flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-teal-500" />
              eSIM Go Topups
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{(stats.esimGo || 0).toLocaleString()}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500 flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-orange-500" />
              Maya Mobile Topups
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{(stats.maya || 0).toLocaleString()}</div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Topup Sync Status</CardTitle>
          <p className="text-sm text-slate-500 mt-1">
            Sync topup packages from all providers. Topups are also auto-synced after base package sync.
          </p>
        </CardHeader>
        <CardContent>
          {loadingProviders ? (
            <div className="flex items-center justify-center py-8">
              <RefreshCw className="h-6 w-6 animate-spin text-slate-400" />
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              {/* Airalo sync card - always visible */}
              <div
                className="flex items-center justify-between p-4 rounded-lg border border-slate-200 dark:border-slate-700"
                data-testid="card-sync-airalo"
              >
                <div className="flex items-center gap-3">
                  <Server className="h-5 w-5 text-teal-500" />
                  <div>
                    <p className="font-medium">Airalo Topups</p>
                    <p className="text-xs text-slate-500">
                      Last sync:{" "}
                      {providers?.data?.find(p => p.slug === 'airalo')?.lastSyncAt
                        ? new Date(providers.data.find(p => p.slug === 'airalo')!.lastSyncAt!).toLocaleString()
                        : "Never"}
                    </p>
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    const airalo = providers?.data?.find(p => p.slug === 'airalo');
                    if (airalo) syncMutation.mutate(airalo.id);
                  }}
                  disabled={syncMutation.isPending || !providers?.data?.find(p => p.slug === 'airalo')}
                  data-testid="button-sync-topups-airalo"
                >
                  <RefreshCw
                    className={`h-4 w-4 ${syncingProviderId === providers?.data?.find(p => p.slug === 'airalo')?.id ? "animate-spin" : ""}`}
                  />
                  <span className="ml-2">Sync</span>
                </Button>
              </div>

              {/* eSIM Access card - On-demand only (no bulk sync API available) */}
              <div
                className="flex items-center justify-between p-4 rounded-lg border border-slate-200 dark:border-slate-700"
                data-testid="card-sync-esim-access"
              >
                <div className="flex items-center gap-3">
                  <Server className="h-5 w-5 text-green-500" />
                  <div>
                    <span className="font-medium flex items-center gap-2">
                      eSIM Access Topups
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Info className="h-4 w-4 text-slate-400 cursor-help" />
                        </TooltipTrigger>
                        <TooltipContent>
                          <span className="max-w-xs">eSIM Access API requires a specific package to query topups. Topup packages are fetched on-demand when a user requests them for their eSIM.</span>
                        </TooltipContent>
                      </Tooltip>
                    </span>
                    <p className="text-xs text-slate-500">
                      Fetched when users request topups
                    </p>
                  </div>
                </div>
                <Badge variant="secondary" className="bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200">
                  On-demand
                </Badge>
              </div>

              {/* eSIM Go sync card */}
              <div
                className="flex items-center justify-between p-4 rounded-lg border border-slate-200 dark:border-slate-700"
                data-testid="card-sync-esim-go"
              >
                <div className="flex items-center gap-3">
                  <Server className="h-5 w-5 text-teal-500" />
                  <div>
                    <span className="font-medium flex items-center gap-2">
                      eSIM Go Topups
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Info className="h-4 w-4 text-slate-400 cursor-help" />
                        </TooltipTrigger>
                        <TooltipContent>
                          <span className="max-w-xs">Topups are fetched from base packages with canTopup=true. Auto-synced after base package sync.</span>
                        </TooltipContent>
                      </Tooltip>
                    </span>
                    <p className="text-xs text-slate-500">
                      Last sync:{" "}
                      {providers?.data?.find(p => p.slug === 'esim-go')?.lastSyncAt
                        ? new Date(providers.data.find(p => p.slug === 'esim-go')!.lastSyncAt!).toLocaleString()
                        : "Never"}
                    </p>
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    const esimGo = providers?.data?.find(p => p.slug === 'esim-go');
                    if (esimGo) syncMutation.mutate(esimGo.id);
                  }}
                  disabled={syncMutation.isPending || !providers?.data?.find(p => p.slug === 'esim-go')}
                  data-testid="button-sync-topups-esim-go"
                >
                  <RefreshCw
                    className={`h-4 w-4 ${syncingProviderId === providers?.data?.find(p => p.slug === 'esim-go')?.id ? "animate-spin" : ""}`}
                  />
                  <span className="ml-2">Sync</span>
                </Button>
              </div>

              {/* Maya sync card */}
              <div
                className="flex items-center justify-between p-4 rounded-lg border border-slate-200 dark:border-slate-700"
                data-testid="card-sync-maya"
              >
                <div className="flex items-center gap-3">
                  <Server className="h-5 w-5 text-orange-500" />
                  <div>
                    <p className="font-medium">Maya Mobile Topups</p>
                    <p className="text-xs text-slate-500">
                      Last sync:{" "}
                      {providers?.data?.find(p => p.slug === 'maya')?.lastSyncAt
                        ? new Date(providers.data.find(p => p.slug === 'maya')!.lastSyncAt!).toLocaleString()
                        : "Never"}
                    </p>
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    const maya = providers?.data?.find(p => p.slug === 'maya');
                    if (maya) syncMutation.mutate(maya.id);
                  }}
                  disabled={syncMutation.isPending || !providers?.data?.find(p => p.slug === 'maya')}
                  data-testid="button-sync-topups-maya"
                >
                  <RefreshCw
                    className={`h-4 w-4 ${syncingProviderId === providers?.data?.find(p => p.slug === 'maya')?.id ? "animate-spin" : ""}`}
                  />
                  <span className="ml-2">Sync</span>
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <CardTitle>All Topup Packages</CardTitle>
            <div className="flex flex-col sm:flex-row gap-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <Input
                  placeholder="Search topups..."
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  className="pl-9 w-full sm:w-[200px]"
                  data-testid="input-search-topups"
                />
              </div>
              <Select value={providerFilter} onValueChange={(v) => { setProviderFilter(v); setCurrentPage(1); }}>
                <SelectTrigger className="w-full sm:w-[150px]" data-testid="select-provider">
                  <SelectValue placeholder="All Providers" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Providers</SelectItem>
                  <SelectItem value="airalo">Airalo</SelectItem>
                  <SelectItem value="esim-access">eSIM Access</SelectItem>
                  <SelectItem value="esim-go">eSIM Go</SelectItem>
                  <SelectItem value="maya">Maya Mobile</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {loadingTopups ? (
            <div className="flex items-center justify-center py-8">
              <RefreshCw className="h-6 w-6 animate-spin text-slate-400" />
            </div>
          ) : topups.length === 0 ? (
            <div className="text-center py-8 text-slate-500">
              <Package className="h-12 w-12 mx-auto mb-4 text-slate-300" />
              <p>No topup packages found.</p>
              <p className="text-sm mt-2">
                {debouncedSearch ? "Try a different search term." : "Trigger a sync to fetch topup packages."}
              </p>
            </div>
          ) : (
            <>
              <div className="rounded-md border overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Title</TableHead>
                      <TableHead>Provider</TableHead>
                      <TableHead>Destination</TableHead>
                      <TableHead>Data</TableHead>
                      <TableHead>Validity</TableHead>
                      <TableHead>Price</TableHead>
                      <TableHead>Linked</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {topups.map((topup) => (
                      <TableRow key={`${topup.provider}-${topup.id}`}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            {topup.operatorImage && (
                              <img 
                                src={topup.operatorImage} 
                                alt={topup.operator || ""} 
                                className="w-8 h-8 rounded object-cover"
                              />
                            )}
                            <div>
                              <p className="font-medium text-sm">{topup.title}</p>
                              {topup.operator && (
                                <p className="text-xs text-slate-500">{topup.operator}</p>
                              )}
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge className={getProviderBadgeColor(topup.provider)} variant="secondary">
                            {topup.providerName}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 text-sm">
                            {topup.regionName ? (
                              <>
                                <Globe className="h-3 w-3 text-slate-400" />
                                {topup.regionName}
                              </>
                            ) : topup.destinationName ? (
                              <>
                                <MapPin className="h-3 w-3 text-slate-400" />
                                {topup.destinationName}
                              </>
                            ) : (
                              <span className="text-slate-400">-</span>
                            )}
                          </div>
                        </TableCell>
                        <TableCell>
                          <span className="font-medium">{formatDataAmount(topup.dataAmount)}</span>
                        </TableCell>
                        <TableCell>
                          {topup.validity} days
                        </TableCell>
                        <TableCell>
                          <span className="font-medium">
                            ${parseFloat(topup.price).toFixed(2)}
                          </span>
                          <span className="text-xs text-slate-500 ml-1">{topup.currency}</span>
                        </TableCell>
                        <TableCell>
                          {topup.hasParentPackage ? (
                            <Badge variant="default" className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
                              Linked
                            </Badge>
                          ) : (
                            <Badge variant="secondary" className="bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400">
                              Unlinked
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          <Badge variant={topup.active ? "default" : "secondary"}>
                            {topup.active ? "Active" : "Inactive"}
                          </Badge>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {/* Pagination */}
              {pagination.totalPages > 1 && (
                <div className="flex items-center justify-between mt-4">
                  <p className="text-sm text-slate-500">
                    Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, pagination.total)} of {pagination.total} packages
                  </p>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                      disabled={currentPage === 1}
                      data-testid="button-prev-page"
                    >
                      Previous
                    </Button>
                    <span className="text-sm">
                      Page {currentPage} of {pagination.totalPages}
                    </span>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setCurrentPage((p) => Math.min(pagination.totalPages, p + 1))}
                      disabled={currentPage === pagination.totalPages}
                      data-testid="button-next-page"
                    >
                      Next
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

server/seed-currencies.ts.content:
import { db } from "./db";
import { currencyRates } from "@shared/schema";

const defaultCurrencies = [
  { code: "USD", name: "US Dollar", symbol: "$", conversionRate: "1.000000", isDefault: true },
  { code: "EUR", name: "Euro", symbol: "€", conversionRate: "0.920000" },
  { code: "GBP", name: "British Pound", symbol: "£", conversionRate: "0.790000" },
  { code: "CAD", name: "Canadian Dollar", symbol: "C$", conversionRate: "1.360000" },
  { code: "AUD", name: "Australian Dollar", symbol: "A$", conversionRate: "1.520000" },
  { code: "JPY", name: "Japanese Yen", symbol: "¥", conversionRate: "149.500000" },
  { code: "CNY", name: "Chinese Yuan", symbol: "¥", conversionRate: "7.240000" },
  { code: "INR", name: "Indian Rupee", symbol: "₹", conversionRate: "83.120000" },
  { code: "BRL", name: "Brazilian Real", symbol: "R$", conversionRate: "4.980000" },
  { code: "MXN", name: "Mexican Peso", symbol: "$", conversionRate: "17.050000" },
];

async function seedCurrencies() {
  console.log("Seeding default currencies...");

  for (const currency of defaultCurrencies) {
    try {
      await db.insert(currencyRates).values(currency).onConflictDoNothing();
      console.log(`✓ Added ${currency.code} - ${currency.name}`);
    } catch (error) {
      console.log(`× Skipped ${currency.code} (already exists)`);
    }
  }

  console.log("Currency seeding complete!");
  process.exit(0);
}

seedCurrencies().catch((error) => {
  console.error("Error seeding currencies:", error);
  process.exit(1);
});

client/src/components/sections/Destinati.content:
import { useState } from 'react';
import { Link } from 'wouter';
import { ArrowRight, Globe, MapPin, Plane } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card, CardContent } from '@/components/ui/card';
import { useQuery } from '@tanstack/react-query';
import ReactCountryFlag from 'react-country-flag';
import { useCurrency } from '@/contexts/CurrencyContext';
import { convertPrice, getCurrencySymbol } from '@/lib/currency';
import { useTranslation } from '@/contexts/TranslationContext';

interface Destination {
  id: string;
  name: string;
  slug: string;
  countryCode: string;
  minPrice?: string;
  currency?: string;
}

interface Region {
  id: string;
  name: string;
  slug: string;
  countries?: string[];
  image?: string;
  minPrice?: string;
  currency?: string;
}

interface GlobalPackage {
  id: string;
  title: string;
  dataAmount: string;
  validity: number;
  retailPrice: string;
  slug: string;
}

const regionIcons: Record<string, string> = {
  europe: 'EU',
  asia: 'AS',
  'north-america': 'NA',
  'south-america': 'SA',
  africa: 'AF',
  oceania: 'OC',
  'australia-and-oceania': 'AU',
  'middle-east': 'ME',
  'middle-east-and-north-africa': 'AE',
  caribbean: 'JM',
  'central-asia': 'KZ',
  'greater-china': 'CN',
  'usa-and-canada': 'US',
  gcc: 'SA',
  balkans: 'RS',
};

const popularCountryCodes = [
  'US',
  'GB',
  'JP',
  'DE',
  'FR',
  'IT',
  'ES',
  'AU',
  'CA',
  'TH',
  'AE',
  'KR',
];

export function DestinationsTabs() {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState('countries');
  const { currency, currencies } = useCurrency();
  const currencySymbol = getCurrencySymbol(currency, currencies);

  const { data: allDestinations = [], isLoading: loadingDestinations } = useQuery<Destination[]>({
    queryKey: ['/api/destinations/with-pricing'],
  });

  const { data: allRegions = [], isLoading: loadingRegions } = useQuery<Region[]>({
    queryKey: ['/api/regions/with-pricing'],
  });

  const { data: allGlobalPackages = [], isLoading: loadingGlobal } = useQuery<GlobalPackage[]>({
    queryKey: ['/api/packages/global'],
  });

  const popularDestinations = allDestinations
    .filter((d) => popularCountryCodes.includes(d.countryCode))
    .slice(0, 12);
  const destinations =
    popularDestinations.length > 0 ? popularDestinations : allDestinations.slice(0, 12);

  const regions = allRegions.filter((r) => r.name?.toLowerCase() !== 'global').slice(0, 12);

  const globalPackages = allGlobalPackages.slice(0, 6);

  const SkeletonCards = () => (
    <>
      {Array.from({ length: 6 }).map((_, i) => (
        <Card key={i} className="border-border/50 h-full">
          <CardContent className="p-4 flex flex-col items-center text-center">
            <div className="h-14 w-14 rounded-full bg-muted animate-pulse mb-3" />
            <div className="h-4 w-20 bg-muted animate-pulse rounded mb-2" />
            <div className="h-3 w-16 bg-muted animate-pulse rounded" />
          </CardContent>
        </Card>
      ))}
    </>
  );

  return (
    <section className="py-16 md:py-24 bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8">
          <h2 className="text-2xl md:text-3xl font-bold text-foreground">
            {t('website.home.destinations.title', 'Where are you traveling next?')}
          </h2>
          <Link href="/destinations">
            <Button variant="ghost" className="text-primary hover:text-secondary gap-1 p-0 h-auto">
              {t('website.home.destinations.seeAll', 'See all 200+ destinations')}
              <ArrowRight className="h-4 w-4" />
            </Button>
          </Link>
        </div>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList
            className="
    mb-8

    bg-muted/50
    rounded-full
    max-w-full

    flex
    gap-1
    overflow-x-auto
    overflow-y-hidden
    whitespace-nowrap
    scrollbar-hide
    px-2 py-2

    /* LARGE DEVICES */
    md:overflow-visible
    md:w-fit
    md:px-1
  "
          >
            <div className="flex gap-1 min-w-max">
              <TabsTrigger
                value="countries"
                className="rounded-full px-3 sm:px-4 md:px-6 py-1.5 sm:py-2 text-xs sm:text-sm md:text-base whitespace-nowrap data-[state=active]:bg-gradient-to-r from-primary to-primary-dark data-[state=active]:text-white flex items-center"
                data-testid="tab-countries"
              >
                <MapPin className="h-3 w-3 sm:h-4 sm:w-4 mr-1 sm:mr-2" />
                <span className="text-xs sm:text-sm">
                  {t('website.home.destinations.tabs.countries', 'Countries')}
                </span>
              </TabsTrigger>
              <TabsTrigger
                value="regional"
                className="rounded-full px-3 sm:px-4 md:px-6 py-1.5 sm:py-2 text-xs sm:text-sm md:text-base whitespace-nowrap data-[state=active]:bg-gradient-to-r from-primary to-primary-dark data-[state=active]:text-white flex items-center"
                data-testid="tab-regional"
              >
                <Plane className="h-3 w-3 sm:h-4 sm:w-4 mr-1 sm:mr-2" />
                <span className="text-xs sm:text-sm">
                  {t('website.home.destinations.tabs.regional', 'Regional eSIMs')}
                </span>
              </TabsTrigger>
              <TabsTrigger
                value="global"
                className="rounded-full px-3 sm:px-4 md:px-6 py-1.5 sm:py-2 text-xs sm:text-sm md:text-base whitespace-nowrap data-[state=active]:bg-gradient-to-r from-primary to-primary-dark data-[state=active]:text-white flex items-center"
                data-testid="tab-global"
              >
                <Globe className="h-3 w-3 sm:h-4 sm:w-4 mr-1 sm:mr-2" />
                <span className="text-xs sm:text-sm">
                  {t('website.home.destinations.tabs.global', 'Global eSIMs')}
                </span>
              </TabsTrigger>
            </div>
          </TabsList>

          <TabsContent value="countries" className="mt-0">
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
              {loadingDestinations ? (
                <SkeletonCards />
              ) : destinations.length > 0 ? (
                destinations.map((destination) => (
                  <Link key={destination.id} href={`/destination/${destination.slug}`}>
                    <Card className="hover-elevate active-elevate-2 cursor-pointer border-border/50 h-full group">
                      <CardContent className="p-4 flex flex-col items-center text-center">
                        <div className="h-14 w-14 rounded-full overflow-hidden mb-3 flex items-center justify-center bg-gradient-to-br from-teal-100 to-teal-50 dark:from-violet-950 dark:to-teal-900 shadow-sm group-hover:shadow-md transition-shadow">
                          <ReactCountryFlag
                            countryCode={destination.countryCode}
                            svg
                            style={{
                              width: '40px',
                              height: '40px',
                              objectFit: 'cover',
                              borderRadius: '50%',
                            }}
                          />
                        </div>
                        <h3 className="font-medium text-sm text-foreground mb-1 line-clamp-1">
                          {destination.name}
                        </h3>
                        {destination.minPrice && (
                          <p className="text-xs text-primary font-semibold">
                            {t('website.home.destinations.from', 'From')} {currencySymbol}
                            {convertPrice(
                              parseFloat(destination.minPrice),
                              'USD',
                              currency,
                              currencies,
                            ).toFixed(2)}
                          </p>
                        )}
                      </CardContent>
                    </Card>
                  </Link>
                ))
              ) : (
                <SkeletonCards />
              )}
            </div>
          </TabsContent>

          <TabsContent value="regional" className="mt-0">
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
              {loadingRegions ? (
                <SkeletonCards />
              ) : regions.length > 0 ? (
                regions.map((region) => {
                  const iconCode = regionIcons[region.slug] || 'EU';
                  const countryCount = region.countries?.length || 0;

                  return (
                    <Link key={region.id} href={`/region/${region.slug}`}>
                      <Card className="hover-elevate active-elevate-2 cursor-pointer border-border/50 h-full group">
                        <CardContent className="p-4 flex flex-col items-center text-center">
                          <div className="h-14 w-14 rounded-full overflow-hidden mb-3 flex items-center justify-center bg-gradient-to-br from-amber-100 to-amber-50 dark:from-amber-950 dark:to-amber-900 shadow-sm group-hover:shadow-md transition-shadow">
                            <ReactCountryFlag
                              countryCode={iconCode}
                              svg
                              style={{
                                width: '40px',
                                height: '40px',
                                objectFit: 'cover',
                                borderRadius: '50%',
                              }}
                            />
                          </div>
                          <h3 className="font-medium text-sm text-foreground mb-1 line-clamp-2">
                            {region.name}
                          </h3>
                          {countryCount > 0 && (
                            <p className="text-xs text-muted-foreground mb-1">
                              {countryCount} {t('website.home.destinations.countries', 'countries')}
                            </p>
                          )}
                          {region.minPrice && (
                            <p className="text-xs text-orange-500 font-semibold">
                              {t('website.home.destinations.from', 'From')} {currencySymbol}
                              {convertPrice(
                                parseFloat(region.minPrice),
                                'USD',
                                currency,
                                currencies,
                              ).toFixed(2)}
                            </p>
                          )}
                        </CardContent>
                      </Card>
                    </Link>
                  );
                })
              ) : (
                <SkeletonCards />
              )}
            </div>
          </TabsContent>

          <TabsContent value="global" className="mt-0">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {loadingGlobal ? (
                <>
                  {Array.from({ length: 4 }).map((_, i) => (
                    <Card key={i} className="border-border/50">
                      <CardContent className="p-4 flex items-center gap-4">
                        <div className="h-12 w-12 rounded-full bg-muted animate-pulse" />
                        <div className="flex-1">
                          <div className="h-4 w-32 bg-muted animate-pulse rounded mb-2" />
                          <div className="h-3 w-20 bg-muted animate-pulse rounded" />
                        </div>
                        <div className="h-5 w-16 bg-muted animate-pulse rounded" />
                      </CardContent>
                    </Card>
                  ))}
                </>
              ) : globalPackages.length > 0 ? (
                globalPackages.map((pkg) => (
                  <Link key={pkg.id} href="/global">
                    <Card className="hover-elevate active-elevate-2 cursor-pointer border-border/50 h-full group bg-muted/30">
                      <CardContent className="p-4 flex items-center gap-4">
                        <div className="h-12 w-12 rounded-full flex items-center justify-center bg-slate-100 dark:bg-slate-800 flex-shrink-0">
                          <Globe className="h-6 w-6 text-slate-500 dark:text-slate-400" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-medium text-sm text-foreground">
                            {t('website.home.destinations.global', 'Global')} ({pkg.dataAmount})
                          </h3>
                          <p className="text-xs text-muted-foreground">
                            {pkg.validity}{' '}
                            {t('website.home.destinations.daysValidity', 'days validity')}
                          </p>
                        </div>
                        <div className="text-right flex-shrink-0">
                          <span className="font-semibold text-foreground">
                            {currencySymbol}
                            {convertPrice(
                              parseFloat(pkg.retailPrice),
                              'USD',
                              currency,
                              currencies,
                            ).toFixed(2)}
                          </span>
                          <span className="text-xs text-muted-foreground ml-1">{currency}</span>
                        </div>
                      </CardContent>
                    </Card>
                  </Link>
                ))
              ) : (
                <div className="col-span-full text-center py-8">
                  <Globe className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <p className="text-muted-foreground">
                    {t(
                      'website.home.destinations.globalComingSoon',
                      'Global eSIM packages coming soon!',
                    )}
                  </p>
                  <Link href="/destinations">
                    <Button variant="ghost" className="text-orange-500 mt-2">
                      {t('website.home.destinations.browseAll', 'Browse all destinations')}
                    </Button>
                  </Link>
                </div>
              )}
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </section>
  );
}

server/services/packages/auto-package-se.content:
import { storage } from "../../storage";
import { db } from "../../db";
import { unifiedPackages } from "@shared/schema";
import { eq, and } from "drizzle-orm";
import { packageNormalizer, NormalizedPackageData } from "./package-normalizer";

/**
 * Auto Package Selection Service
 * Automatically enables/disables packages based on package_selection_mode setting
 */
export class AutoPackageSelectionService {
  /**
   * Run auto package selection based on current settings
   * If mode is 'auto': enable best_price packages, fallback to preferred provider
   * If mode is 'manual': respect manual overrides, admin controls everything
   */
  async runAutoSelection(): Promise<{
    mode: string;
    packagesEnabled: number;
    packagesDisabled: number;
    errors: string[];
  }> {
    console.log("🤖 Running auto package selection...");
    const startTime = Date.now();
    const errors: string[] = [];
    let packagesEnabled = 0;
    let packagesDisabled = 0;

    try {
      // Get package selection mode setting
      const modeSetting = await storage.getSettingByKey("package_selection_mode");
      const mode = modeSetting?.value || "auto";

      console.log(`   Mode: ${mode}`);

      if (mode === "manual") {
        console.log("   ⏭️  Manual mode - skipping auto selection");
        return { mode, packagesEnabled: 0, packagesDisabled: 0, errors: [] };
      }

      // Auto mode: enable best_price packages
      if (mode === "auto") {
        // Get all packages
        const allPackages = await db.query.unifiedPackages.findMany();

        for (const pkg of allPackages) {
          // Skip if manual override is set (admin manually controlled this package)
          if (pkg.manualOverride) {
            continue;
          }

          // Enable if best price, disable otherwise
          const shouldBeEnabled = pkg.isBestPrice;

          if (shouldBeEnabled !== pkg.isEnabled) {
            await db.update(unifiedPackages)
              .set({ isEnabled: shouldBeEnabled })
              .where(eq(unifiedPackages.id, pkg.id));

            if (shouldBeEnabled) {
              packagesEnabled++;
            } else {
              packagesDisabled++;
            }
          }
        }

        // Handle cases where no best_price package exists (fallback to preferred provider)
        await this.handlePreferredProviderFallback();
      }

      const duration = ((Date.now() - startTime) / 1000).toFixed(2);
      console.log(`✅ Auto package selection complete in ${duration}s`);
      console.log(`   ✅ Enabled: ${packagesEnabled} packages`);
      console.log(`   ❌ Disabled: ${packagesDisabled} packages`);

      return {
        mode,
        packagesEnabled,
        packagesDisabled,
        errors,
      };

    } catch (error: any) {
      console.error("❌ Auto package selection failed:", error.message);
      errors.push(error.message);
      return { mode: "unknown", packagesEnabled: 0, packagesDisabled: 0, errors };
    }
  }

  /**
   * Handle preferred provider fallback
   * If no best_price package exists for a destination/region+data+validity combo,
   * enable packages from the preferred provider
   */
  private async handlePreferredProviderFallback(): Promise<void> {
    try {
      // Get preferred provider
      const preferredProviderIdSetting = await storage.getSettingByKey("preferred_provider_id");

      if (!preferredProviderIdSetting?.value) {
        console.log("   ⚠️  No preferred provider set for fallback");
        return;
      }

      const preferredProviderId = preferredProviderIdSetting.value;
      const preferredProvider = await storage.getProviderById(preferredProviderId);

      if (!preferredProvider) {
        console.log("   ⚠️  Preferred provider not found");
        return;
      }

      console.log(`   🔄 Checking preferred provider fallback (${preferredProvider.name})...`);

      // Get all packages grouped by normalized comparison keys
      const allPackages = await db.query.unifiedPackages.findMany();

      // Group packages using normalized comparison keys
      const groups = new Map<string, typeof allPackages>();
      for (const pkg of allPackages) {
        const normalized: NormalizedPackageData = {
          dataMb: pkg.dataMb,
          validityDays: pkg.validityDays,
          voiceMinutes: pkg.voiceMinutes || 0,
          smsCount: pkg.smsCount || 0,
        };

        const key = packageNormalizer.createComparisonKey(
          pkg.destinationId,
          pkg.regionId,
          normalized
        );

        if (!groups.has(key)) {
          groups.set(key, []);
        }
        groups.get(key)!.push(pkg);
      }

      // Check each group for best_price packages
      let fallbackCount = 0;
      for (const [key, group] of Array.from(groups.entries())) {
        const hasBestPrice = group.some(pkg => pkg.isBestPrice);
        const hasEnabledPackage = group.some(pkg => pkg.isEnabled);

        // If no best_price package exists and no enabled package, enable preferred provider's package
        if (!hasBestPrice && !hasEnabledPackage) {
          const preferredProviderPackage = group.find(pkg => pkg.providerId === preferredProviderId);

          if (preferredProviderPackage && !preferredProviderPackage.manualOverride) {
            await db.update(unifiedPackages)
              .set({ isEnabled: true })
              .where(eq(unifiedPackages.id, preferredProviderPackage.id));

            fallbackCount++;
          }
        }
      }

      if (fallbackCount > 0) {
        console.log(`   ✅ Enabled ${fallbackCount} packages from preferred provider (fallback)`);
      }

    } catch (error: any) {
      console.error("   ❌ Preferred provider fallback failed:", error.message);
    }
  }

  /**
   * Toggle manual override for a specific package
   * When manual override is set, auto selection will skip this package
   */
  async setManualOverride(packageId: string, isEnabled: boolean): Promise<void> {
    await db.update(unifiedPackages)
      .set({
        manualOverride: true,
        isEnabled,
      })
      .where(eq(unifiedPackages.id, packageId));

    console.log(`✅ Manual override set for package ${packageId}: ${isEnabled ? 'enabled' : 'disabled'}`);
  }

  /**
   * Clear manual override for a specific package
   * Package will be managed by auto selection again
   */
  async clearManualOverride(packageId: string): Promise<void> {
    await db.update(unifiedPackages)
      .set({
        manualOverride: false,
      })
      .where(eq(unifiedPackages.id, packageId));

    // Re-run auto selection for this package
    const pkg = await db.query.unifiedPackages.findFirst({
      where: eq(unifiedPackages.id, packageId),
    });

    if (pkg) {
      const modeSetting = await storage.getSettingByKey("package_selection_mode");
      const mode = modeSetting?.value || "auto";

      if (mode === "auto") {
        // In auto mode, enable if best price
        await db.update(unifiedPackages)
          .set({ isEnabled: pkg.isBestPrice })
          .where(eq(unifiedPackages.id, packageId));
      }
    }

    console.log(`✅ Manual override cleared for package ${packageId}`);
  }

  /**
   * Get package selection statistics
   */
  async getStatistics(): Promise<{
    mode: string;
    totalPackages: number;
    enabledPackages: number;
    disabledPackages: number;
    manualOverrides: number;
    bestPricePackages: number;
  }> {
    const modeSetting = await storage.getSettingByKey("package_selection_mode");
    const mode = modeSetting?.value || "auto";

    const allPackages = await db.query.unifiedPackages.findMany();

    return {
      mode,
      totalPackages: allPackages.length,
      enabledPackages: allPackages.filter(p => p.isEnabled).length,
      disabledPackages: allPackages.filter(p => !p.isEnabled).length,
      manualOverrides: allPackages.filter(p => p.manualOverride).length,
      bestPricePackages: allPackages.filter(p => p.isBestPrice).length,
    };
  }
}

// Export singleton instance
export const autoPackageSelectionService = new AutoPackageSelectionService();

