                        {/* PAYMENT GATEWAY SELECTION */}
                        {/* {gateways.length > 0 && (
                          <>
                            <h3 className="font-semibold text-foreground">Select Payment Method</h3>
                            {gateways.map((gateway) => (
                              <Button
                                key={gateway.id}
