server/services/airalo/orders.ts.content:
"use strict";

import { airaloAPI } from "./airalo-sdk";
import type {
  ProviderOrderRequest,
  ProviderOrderResponse,
  ProviderOrderStatus,
  ProviderTopupPackage,
  ProviderTopupRequest,
  ProviderTopupResponse,
  ProviderRefundRequest,
  ProviderRefundResponse,
  ProviderCancelRequest,
  ProviderCancelResponse,
} from "../../providers/provider-interface";
import { db } from "server/db";
import { orders } from "@shared/schema";
import { eq } from "drizzle-orm";

export async function createAiraloOrder(request: ProviderOrderRequest): Promise<ProviderOrderResponse> {
  try {
    const useAsync = (request.quantity || 1) > 5;

    let response;
    if (useAsync) {
      response = await airaloAPI.submitOrderAsync(request.packageId, request.quantity || 1);
    } else {
      response = await airaloAPI.submitOrder(request.packageId, request.quantity || 1);
    }

    if (response.data && response.data.id) {
      const order = response.data;

      if (order.sims && order.sims.length > 0) {
        const sim = order.sims[0];

        return {
          success: true,
          providerOrderId: String(order.id),
          requestId: String(order.id),
          status: 'completed',
          iccid: sim.iccid,
          qrCode: sim.qrcode,
          smdpAddress: sim.lpa || '',
          activationCode: sim.matching_id || sim.manual_activation_code || '',
        };
      }

      return {
        success: true,
        providerOrderId: String(order.id),
        requestId: String(order.id),
        status: 'processing',
        processingTime: useAsync ? 10 : 5,
      };
    }

    throw new Error('Order response did not contain order data');
  } catch (error) {
    return {
      success: false,
      status: 'failed',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

export async function getAiraloOrderStatus(providerOrderId: string): Promise<ProviderOrderStatus> {
  try {
    const orderDB = await db.query.orders.findFirst({
      where: eq(orders.providerOrderId, providerOrderId),
    });

    const response = await airaloAPI.getSimDetails(orderDB?.iccid);

    console.log("response", JSON.stringify(response, null, 2));
    const order = response?.data;


    if (order) {
      return {
        providerOrderId: String(order.id),
        status: order.iccid ? "completed" : "processing",
        iccid: order.iccid,
        qrCode: order.qrcode,
        qrCodeUrl: order.qrcode_url,
        directAppleUrl: order.direct_apple_installation_url,
        apnValue: order.apn_value,
        apnType: order.apn_type,
        isRoaming: order.is_roaming,
        smdpAddress: order.lpa || "",
        activationCode: order.matching_id || "",
      };
    }

    return {
      providerOrderId,
      status: "failed",
      errorMessage: "Order not found",
    };
  } catch (error) {
    return {
      providerOrderId,
      status: "failed",
      errorMessage: error instanceof Error ? error.message : "Unknown error",
    };
  }
}



export async function getAiraloEsim(providerOrderId: string): Promise<ProviderOrderStatus> {
  try {
    const response = await airaloAPI.getSimDetails(providerOrderId);

    if (response.data) {
      const order = response.data;
      const status = order.sims && order.sims.length > 0 ? 'completed' : 'processing';
      const sim = order.sims?.[0];

      return {
        providerOrderId: String(order.id),
        status,
        iccid: sim?.iccid,
        qrCode: sim?.qrcode,
        smdpAddress: sim?.lpa || '',
        activationCode: sim?.matching_id || sim?.manual_activation_code || '',
      };
    }

    return {
      providerOrderId,
      status: 'failed',
      errorMessage: 'Order not found',
    };
  } catch (error) {
    return {
      providerOrderId,
      status: 'failed',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

export async function getAiraloTopupPackages(iccidOrPackageId: string): Promise<ProviderTopupPackage[]> {
  try {
    const isIccid = /^\d{19,20}$/.test(iccidOrPackageId);

    if (isIccid) {
      const simResponse = await airaloAPI.getSimDetails(iccidOrPackageId);

      if (simResponse.data && simResponse.data.package && simResponse.data.package.topup_packages) {
        return simResponse.data.package.topup_packages.map((pkg: any) => ({
          providerPackageId: String(pkg.id),
          title: pkg.title,
          dataAmount: pkg.data,
          validity: pkg.validity,
          wholesalePrice: parseFloat(pkg.price),
          currency: pkg.currency_code,
        }));
      }
    } else {
      const packageResponse = await airaloAPI.getPackage(iccidOrPackageId);

      if (packageResponse.data && packageResponse.data.topup_packages) {
        return packageResponse.data.topup_packages.map((pkg: any) => ({
          providerPackageId: String(pkg.id),
          title: pkg.title,
          dataAmount: pkg.data,
          validity: pkg.validity,
          wholesalePrice: parseFloat(pkg.price),
          currency: pkg.currency_code,
        }));
      }
    }

    return [];
  } catch (error) {
    return [];
  }
}

export async function purchaseAiraloTopup(request: ProviderTopupRequest): Promise<ProviderTopupResponse> {
  try {
    const response = await airaloAPI.submitTopup(request.iccid, request.packageId);

    if (response.data && response.data.id) {
      return {
        success: true,
        providerTopupId: String(response.data.id),
        requestId: String(response.data.id),
        status: 'completed',
      };
    }

    throw new Error('Topup response did not contain order data');
  } catch (error) {
    return {
      success: false,
      status: 'failed',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

export async function requestAiraloRefund(request: ProviderRefundRequest): Promise<ProviderRefundResponse> {
  try {
    console.log("request", JSON.stringify(request, null, 2));
    const airaloReason = request.reason === "SERVICE_ISSUES" ? "SERVICE_ISSUES" : "OTHERS";

    const response = await airaloAPI.requestRefund({
      iccids: [request.iccid],
      reason: airaloReason,
      notes: request.notes || (airaloReason === "OTHERS" ? "Customer requested refund" : undefined),
      email: request.email,
    });

    console.log("response", JSON.stringify(response, null, 2));

    if (response.meta && response.meta.message) {
      const isApproved = response.meta.message.toLowerCase().includes("success") ||
        response.meta.message.toLowerCase().includes("approved");

      return {
        success: true,
        approved: isApproved,
        refundId: response.data?.refund_id,
        status: isApproved ? "approved" : "pending",
        message: response.meta.message,
      };
    }

    return {
      success: true,
      approved: false,
      status: "pending",
      message: "Refund request submitted for review",
    };
  } catch (error) {
    return {
      success: false,
      approved: false,
      status: "rejected",
      errorMessage: error instanceof Error ? error.message : "Refund request failed",
    };
  }
}

export async function cancelAiraloFutureOrders(requestIds: string[]): Promise<ProviderCancelResponse> {
  try {
    console.log("requestIds", JSON.stringify(requestIds, null, 2));
    const response = await airaloAPI.cancelFutureOrders(requestIds);

    if (response.meta && response.meta.message) {
      return {
        success: true,
        status: "cancelled",
        message: response.meta.message,
      };
    }

    return {
      success: true,
      status: "cancelled",
      message: "Future orders cancelled successfully",
    };
  } catch (error) {
    return {
      success: false,
      status: "failed",
      errorMessage: error instanceof Error ? error.message : "Cancel request failed",
    };
  }
}

server/services/maya/topups.ts.content:
"use strict";

import { getMayaProducts, getMayaEsim, changeMayaEsim, getMayaEsimPlans } from "./api-client";
import { formatDataAmount } from "./types";
import type {
  ProviderTopupPackage,
  ProviderTopupRequest,
  ProviderTopupResponse,
} from "../../providers/provider-interface";
import type { MayaProductsResponse, MayaGetEsimResponse, MayaChangeEsimResponse, MayaGetPlansResponse } from "./types";

export async function getMayaTopupPackages(
  iccidOrProductUid: string,
  apiKey: string,
  apiSecret: string
): Promise<ProviderTopupPackage[]> {
  try {
    const esimResponse = await getMayaEsim(
      iccidOrProductUid,
      apiKey,
      apiSecret
    ) as MayaGetEsimResponse;

    if (!esimResponse.esim) {
      console.warn("[Maya] eSIM not found, attempting to get products for country");
      return [];
    }

    const esim = esimResponse.esim;

    const plansResponse = await getMayaEsimPlans(
      iccidOrProductUid,
      apiKey,
      apiSecret
    ) as MayaGetPlansResponse;

    if (!plansResponse.plans || plansResponse.plans.length === 0) {
      return [];
    }

    const activePlan = plansResponse.plans.find(p => p.status === "active");
    if (!activePlan) {
      return [];
    }

    const productsResponse = await getMayaProducts(
      apiKey,
      apiSecret
    ) as MayaProductsResponse;

    if (!productsResponse.products) {
      return [];
    }

    const topupPackages: ProviderTopupPackage[] = productsResponse.products.map(product => ({
      providerPackageId: product.uid,
      title: product.name,
      dataAmount: formatDataAmount(product.data_quota_mb),
      validity: product.validity_days,
      wholesalePrice: parseFloat(product.wholesale_price_usd) || 0,
      currency: "USD",
    }));

    return topupPackages;
  } catch (error) {
    console.error("[Maya] Get topup packages failed:", error);
    return [];
  }
}

export async function purchaseMayaTopup(
  request: ProviderTopupRequest,
  apiKey: string,
  apiSecret: string
): Promise<ProviderTopupResponse> {
  try {
    if (!request.iccid) {
      return {
        success: false,
        status: "failed",
        errorMessage: "ICCID is required for Maya topup",
      };
    }

    const response = await changeMayaEsim(
      request.iccid,
      "add_package",
      apiKey,
      apiSecret,
      request.packageId
    ) as MayaChangeEsimResponse;

    if (response.result !== 1 && response.result !== 0) {
      return {
        success: false,
        status: "failed",
        errorMessage: response.message || "Failed to add package to eSIM",
      };
    }

    const newPlan = response.esim?.plans?.find(p => 
      p.product_uid === request.packageId && p.status === "active"
    );

    return {
      success: true,
      providerTopupId: newPlan?.id || response.request_id,
      requestId: response.request_id,
      status: "completed",
    };
  } catch (error) {
    console.error("[Maya] Purchase topup failed:", error);
    return {
      success: false,
      status: "failed",
      errorMessage: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

export async function suspendMayaEsim(
  esimId: string,
  apiKey: string,
  apiSecret: string
): Promise<{ success: boolean; message?: string; error?: string }> {
  try {
    const response = await changeMayaEsim(
      esimId,
      "suspend",
      apiKey,
      apiSecret
    ) as MayaChangeEsimResponse;

    return {
      success: true,
      message: response.message || "eSIM suspended successfully",
    };
  } catch (error) {
    console.error("[Maya] Suspend eSIM failed:", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

export async function reactivateMayaEsim(
  esimId: string,
  apiKey: string,
  apiSecret: string
): Promise<{ success: boolean; message?: string; error?: string }> {
  try {
    const response = await changeMayaEsim(
      esimId,
      "reactivate",
      apiKey,
      apiSecret
    ) as MayaChangeEsimResponse;

    return {
      success: true,
      message: response.message || "eSIM reactivated successfully",
    };
  } catch (error) {
    console.error("[Maya] Reactivate eSIM failed:", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

client/src/components/admin/tabs/SMTPSet.content:
import React, { useState, useEffect, useMemo } from "react";
import {
  Save,
  Mail,
  Loader2,
  AlertCircle,
  CheckCircle,
  Info,
  Shield,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { useTranslation } from "@/contexts/TranslationContext";

import { useToast } from "@/hooks/use-toast";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";

export function SMTPSettings() {
  const { t } = useTranslation();
  const { toast } = useToast();

  // Internal state management
  const [smtpHost, setSmtpHost] = useState("");
  const [smtpPort, setSmtpPort] = useState("");
  const [smtpUser, setSmtpUser] = useState("");
  const [smtpPass, setSmtpPass] = useState("");
  const [smtpFromEmail, setSmtpFromEmail] = useState("");

  // Fetch settings from API
  const { data: settingsResponse } = useQuery({
    queryKey: ["/api/admin/settings"],
  });

  // Transform settings array to object
  const settings = useMemo(() => {
    if (!settingsResponse) return {};

    return settingsResponse.reduce((acc: Record<string, string>, setting: any) => {
      acc[setting.key] = setting.value;
      return acc;
    }, {});
  }, [settingsResponse]);

  console.log('settings', settings);

  // Load settings into state
  useEffect(() => {
    if (settings && Object.keys(settings).length > 0) {
      setSmtpHost(settings.smtp_host || "");
      setSmtpPort(settings.smtp_port || "");
      setSmtpUser(settings.smtp_user || "");
      setSmtpPass(settings.smtp_pass || "");
      setSmtpFromEmail(settings.smtp_from_email || "");
    }
  }, [settings]);

  // Update setting mutation
  const updateSettingMutation = useMutation({
    mutationFn: async ({
      key,
      value,
      category,
    }: {
      key: string;
      value: string;
      category: string;
    }) => {
      return await apiRequest("PUT", `/api/admin/settings/${key}`, {
        value,
        category,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
      toast({
        title: t("admin.settings.success", "Success"),
        description: t(
          "admin.settings.settingsUpdatedSuccess",
          "Settings updated successfully"
        ),
      });
    },
    onError: (error: any) => {
      toast({
        title: t("admin.settings.error", "Error"),
        description:
          error.message ||
          t(
            "admin.settings.failedToUpdateSettings",
            "Failed to update settings"
          ),
        variant: "destructive",
      });
    },
  });

  // Save single setting
  const saveSetting = async (
    key: string,
    value: string,
    category: string = "smtp"
  ) => {
    await updateSettingMutation.mutateAsync({ key, value, category });
  };

  // Handle SMTP settings save
  const handleSaveSmtp = async () => {
    await saveSetting("smtp_host", smtpHost, "smtp");
    await saveSetting("smtp_port", smtpPort, "smtp");
    await saveSetting("smtp_user", smtpUser, "smtp");
    await saveSetting("smtp_pass", smtpPass, "smtp");
    await saveSetting("smtp_from_email", smtpFromEmail, "smtp");
  };

  return (
    <div className="space-y-6">
      {/* SMTP Configuration Card */}
      <Card className="border-0 shadow-xl hover:shadow-[0_25px_50px_-12px_color-mix(in_srgb,var(--primary-hex)_30%,transparent)] transition-all duration-500">
        <CardHeader>
          <div className="flex items-center gap-3">
            <div className="h-12 w-12 rounded-xl bg-gradient-to-br from-[var(--primary-hex)] to-[var(--primary-second-hex)] flex items-center justify-center shadow-lg">
              <Mail className="h-6 w-6 text-black" />
            </div>
            <div>
              <CardTitle className="text-2xl font-bold bg-gradient-to-r from-[var(--primary-hex)] to-[var(--primary-second-hex)] bg-clip-text text-transparent">
                {t("admin.settings.smtp.title", "Email Configuration")}
              </CardTitle>
              <CardDescription className="text-lg text-[var(--primary-hex)]/70">
                {t(
                  "admin.settings.smtp.description",
                  "Configure SMTP settings for sending emails (OTP codes, order confirmations, etc.)"
                )}
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-8 space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* SMTP Host */}
            <div className="space-y-3">
              <Label
                htmlFor="smtp-host"
                className="text-lg font-semibold flex items-center gap-2"
              >
                <div className="h-2 w-2 rounded-full bg-[var(--primary-hex)]"></div>
                {t("admin.settings.smtp.host", "SMTP Host")}
              </Label>
              <Input
                id="smtp-host"
                value={smtpHost}
                onChange={(e) => setSmtpHost(e.target.value)}
                placeholder={t(
                  "admin.settings.smtp.hostPlaceholder",
                  "smtp.gmail.com"
                )}
                className="h-12 ring-2 ring-[var(--primary-hex)]/20 focus:ring-[var(--primary-hex)] focus:border-[var(--primary-hex)] transition-all duration-300"
                data-testid="input-smtp-host"
              />
            </div>

            {/* SMTP Port */}
            <div className="space-y-3">
              <Label
                htmlFor="smtp-port"
                className="text-lg font-semibold flex items-center gap-2"
              >
                <div className="h-2 w-2 rounded-full bg-[var(--primary-hex)]"></div>
                {t("admin.settings.smtp.port", "SMTP Port")}
              </Label>
              <Input
                id="smtp-port"
                type="number"
                value={smtpPort}
                onChange={(e) => setSmtpPort(e.target.value)}
                placeholder={t("admin.settings.smtp.portPlaceholder", "587")}
                className="h-12 ring-2 ring-[var(--primary-hex)]/20 focus:ring-[var(--primary-hex)] focus:border-[var(--primary-hex)] transition-all duration-300"
                data-testid="input-smtp-port"
              />
            </div>
          </div>

          {/* SMTP Username */}
          <div className="space-y-3">
            <Label
              htmlFor="smtp-user"
              className="text-lg font-semibold flex items-center gap-2"
            >
              <div className="h-2 w-2 rounded-full bg-[var(--primary-hex)]"></div>
              {t("admin.settings.smtp.username", "SMTP Username")}
            </Label>
            <Input
              id="smtp-user"
              value={smtpUser}
              onChange={(e) => setSmtpUser(e.target.value)}
              placeholder={t(
                "admin.settings.smtp.usernamePlaceholder",
                "your-email@gmail.com"
              )}
              className="h-12 ring-2 ring-[var(--primary-hex)]/20 focus:ring-[var(--primary-hex)] focus:border-[var(--primary-hex)] transition-all duration-300"
              data-testid="input-smtp-user"
            />
          </div>

          {/* SMTP From Email */}
          <div className="space-y-3">
            <Label
              htmlFor="smtp-from"
              className="text-lg font-semibold flex items-center gap-2"
            >
              <div className="h-2 w-2 rounded-full bg-[var(--primary-hex)]"></div>
              {t("admin.settings.smtp.fromEmail", "SMTP From Email")}
            </Label>
            <Input
              id="smtp-from"
              value={smtpFromEmail}
              onChange={(e) => setSmtpFromEmail(e.target.value)}
              placeholder={t(
                "admin.settings.smtp.fromEmailPlaceholder",
                "noreply@yourdomain.com"
              )}
              className="h-12 ring-2 ring-[var(--primary-hex)]/20 focus:ring-[var(--primary-hex)] focus:border-[var(--primary-hex)] transition-all duration-300"
              data-testid="input-smtp-from"
            />
            <p className="text-sm font-medium px-3 py-2 bg-[var(--primary-light-hex)]/20 rounded-lg border border-[var(--primary-hex)]/20 flex items-center gap-2">
              <Info className="h-4 w-4 text-[var(--primary-hex)]" />
              {t(
                "admin.settings.smtp.fromEmailHelp",
                "This email will appear as the sender when sending OTP or notifications."
              )}
            </p>
          </div>

          {/* SMTP Password */}
          <div className="space-y-3">
            <Label
              htmlFor="smtp-pass"
              className="text-lg font-semibold flex items-center gap-2"
            >
              <div className="h-2 w-2 rounded-full bg-[var(--primary-hex)]"></div>
              {t("admin.settings.smtp.password", "SMTP Password")}
            </Label>
            <Input
              id="smtp-pass"
              type="password"
              value={smtpPass}
              onChange={(e) => setSmtpPass(e.target.value)}
              placeholder={t(
                "admin.settings.smtp.passwordPlaceholder",
                "Your app password"
              )}
              className="h-12 ring-2 ring-[var(--primary-hex)]/20 focus:ring-[var(--primary-hex)] focus:border-[var(--primary-hex)] transition-all duration-300"
              data-testid="input-smtp-pass"
            />
            <p className="text-sm font-medium px-3 py-2 bg-[var(--primary-light-hex)]/20 rounded-lg border border-[var(--primary-hex)]/20 flex items-center gap-2">
              <Shield className="h-4 w-4 text-[var(--primary-hex)]" />
              {t(
                "admin.settings.smtp.passwordHelp",
                "For Gmail, use an App Password. For other providers, use your SMTP password."
              )}
            </p>
          </div>

          <Button
            onClick={handleSaveSmtp}
            disabled={updateSettingMutation.isPending}
            className="gap-2 h-12 px-8 text-lg bg-gradient-to-r from-[var(--primary-hex)] to-[var(--primary-second-hex)] hover:from-[var(--primary-dark-hex)] hover:to-[var(--primary-hex)] shadow-lg hover:shadow-glow transition-all duration-300"
            data-testid="button-save-smtp"
          >
            {updateSettingMutation.isPending ? (
              <>
                <Loader2 className="h-5 w-5 animate-spin" />
                {t("admin.settings.smtp.saving", "Saving...")}
              </>
            ) : (
              <>
                <Save className="h-5 w-5" />
                {t(
                  "admin.settings.smtp.saveSmtpSettings",
                  "Save SMTP Settings"
                )}
              </>
            )}
          </Button>
        </CardContent>
