"use strict";

import { Router, type Request, type Response } from "express";
import { storage } from "../../storage";
import { asyncHandler } from "../../lib/asyncHandler";
import { NotFoundError } from "../../lib/errors";
import { requireAdmin } from "../../lib/middleware";
import { logger } from "../../lib/logger";
import * as ApiResponse from "../../utils/response";

const router = Router();

router.get(
  "/",
  requireAdmin,
  asyncHandler(async (req: Request, res: Response) => {
    const page = Number(req.query.page) || 1;
    const limit = Number(req.query.limit) || 10;
    const search = req.query.search as string | undefined;
    const kycStatus = req.query.kycStatus as string | undefined;

    const customers = await storage.getUsersWithPagination(
      page,
      limit,
      search,
      kycStatus
    );

    return ApiResponse.success(
      res,
      "Customers fetched successfully",
      customers
    );
  })
);



router.get(
  "/:id",
  requireAdmin,
  asyncHandler(async (req: Request, res: Response) => {
    const user = await storage.getUserWithDetails(req.params.id);
    if (!user) {
      return ApiResponse.notFound(res, "Customer not found");
    }
    return ApiResponse.success(res, "Customer fetched successfully", user);
  })
);

router.patch(
  "/:id",
  requireAdmin,
  asyncHandler(async (req: Request, res: Response) => {
    const { name, email, phone, address, kycStatus } = req.body;
    const user = await storage.updateUser(req.params.id, {
      name,
      email,
      phone,
      address,
      kycStatus,
    });

    if (!user) {
      return ApiResponse.notFound(res, "Customer not found");
    }

    logger.info("Customer updated by admin", {
      customerId: req.params.id,
      adminId: req.session.adminId,
    });

    return ApiResponse.success(res, "Customer updated successfully", user);
  })
);

router.get(
  "/:id/orders",
  requireAdmin,
  asyncHandler(async (req: Request, res: Response) => {
    const orders = await storage.getOrdersByUser(req.params.id);
    return ApiResponse.success(res, "Customer orders fetched successfully", orders);
  })
);

router.get(
  "/:id/activity",
  requireAdmin,
  asyncHandler(async (req: Request, res: Response) => {
    const activities = await storage.getActivityLogsByUser(req.params.id);
    return ApiResponse.success(res, "Customer activity fetched successfully", activities);
  })
);

export default router;

server/middleware/auth.ts.content:
import { Request, Response, NextFunction } from "express";
import { verifyToken } from "server/utils/auth";
import * as ApiResponse from "../utils/response";
import { storage } from "../storage";


declare global {
  namespace Express {
    interface Request {
      userId?: string;
      role?: string;
    }
  }
}

export const requireAuth = (req: any, res: Response, next: Function) => {
  if (req.session?.userId) {
    req.userId = req.session.userId;
    req.role = req.session.role;
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return ApiResponse.unauthorized(res, "Unauthorized");
  }

  try {
    const token = authHeader.split(" ")[1];
    const decoded: any = verifyToken(token);

    req.userId = decoded.id;
    req.role = decoded.role;
    next();
  } catch {
    return ApiResponse.unauthorized(res, "Invalid token");
  }
};

export const requireAdminOLD = (req: Request, res: Response, next: Function) => {
  if (!req.session.adminId) {
    return ApiResponse.unauthorized(res, "Unauthorized");
  }
  next();
};


export const requireAdmin = async (
  req: Request,
  res: Response,
  next: Function
) => {
  try {
    const adminId = req.session.adminId;

    if (!adminId) {
      return ApiResponse.unauthorized(res, "Admin authentication required");
    }

    const admin = await storage.getAdminById(adminId);

    if (!admin) {
      return ApiResponse.unauthorized(res, "Admin not found");
    }

    // 🔥 THIS LINE FIXES EVERYTHING
    (req as any).user = admin;

    next();
  } catch (error) {
    console.error("requireAdmin error:", error);
    return ApiResponse.serverError(res, "Admin auth failed");
  }
};


export const optionalAdminAuth = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {

  // console.log("req.session", req.session)

  // 1️⃣ Session-based auth (same as requireAdmin)
  if (req.session?.adminId) {
    const admin = await storage.getAdminById(req.session.adminId);
    req.adminId = req.session.adminId;
    req.email = admin.email;
    return next();
  }

  // 2️⃣ Token-based auth (optional)
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return next(); // ✅ Public route – no auth required
  }

  try {
    const token = authHeader.split(" ")[1];
    if (!token) return next();

    const decoded: any = verifyToken(token);

    // console.log("Decoded token:", decoded);

    req.adminId = decoded.id;
    req.email = decoded.email;

    return next();
  } catch (err) {
    // ❌ Token was sent but invalid
    return ApiResponse.unauthorized(res, "Invalid token");
  }
};

server/socket/index.ts.content:
import { Server as SocketIOServer } from "socket.io";
import type { Server as HttpServer } from "http";
import { registerSocketEvents } from "./events";

let io: SocketIOServer | null = null;

export function initSocket(server: HttpServer) {
  if (io) return io; // prevent re-init

  io = new SocketIOServer(server, {
    cors: {
      origin: "*", // TODO: restrict in prod
      methods: ["GET", "POST"],
    },
  });

  console.log("🔌 Socket.IO initialized");

  io.on("connection", (socket) => {
    console.log("⚡ Socket connected:", socket.id);
    registerSocketEvents(io!, socket);

    socket.on("disconnect", () => {
      console.log("❌ Socket disconnected:", socket.id);
    });
  });

  return io;
}

export function getIO(): SocketIOServer {
  if (!io) {
    throw new Error("Socket.io not initialized");
  }
  return io;
}

