                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => deleteCurrencyMutation.mutate(currency.id)}
                      disabled={deleteCurrencyMutation.isPending}
                      data-testid={`button-delete-${currency.code}`}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  )}
                </div>
              </div>
            ));
          })()}
        </div>
      </CardContent>
    </Card>
  );
}

