      </Switch>
    </AccountLayout>
  );
}

client/src/pages/admin/AdminBlog.tsx.content:
import { useEffect, useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { queryClient, apiRequest } from '@/lib/queryClient';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { useToast } from '@/hooks/use-toast';
import { Plus, Pencil, Trash2, Eye, Send } from 'lucide-react';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import type { BlogPost } from '@shared/schema';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Link from '@tiptap/extension-link';
import Image from '@tiptap/extension-image';
import { Bold, Italic, List, ListOrdered } from 'lucide-react';
import { Helmet } from 'react-helmet-async';

export default function AdminBlog() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingPost, setEditingPost] = useState<BlogPost | null>(null);
  const [formData, setFormData] = useState({
    title: '',
    slug: '',
    excerpt: '',
    content: '',
    featuredImage: '',
    published: false,
    metaDescription: '',
    metaKeywords: '',
  });

  const { data, isLoading } = useQuery<{
    posts: (BlogPost & { author: any })[];
    pagination: any;
  }>({
    queryKey: ['/api/admin/blog'],
  });



  /* ================= TipTap Editor ================= */
  const editor = useEditor({
    extensions: [
      StarterKit,
      Link.configure({ openOnClick: false }),
      Image,
    ],
    onUpdate: ({ editor }) => {
      setFormData((prev) => ({
        ...prev,
        content: editor.getHTML(),
      }));
    },
  });


  // const createMutation = useMutation({
  //   mutationFn: (data: any) => apiRequest('POST','/api/admin/blog',  data),
  //   onSuccess: () => {
  //     queryClient.invalidateQueries({ queryKey: ['/api/admin/blog'] });
  //     toast({ title: "Blog post created" });
  //     handleCloseDialog();
  //   },
  //   onError: (error) => {
  //     console.log(error);
  //     toast({ title: "Failed to create blog post", variant: "destructive" });
  //   },
  // });

  const createMutation = useMutation({
    mutationFn: (formData: FormData) => apiRequest('POST', '/api/admin/blog', formData),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/blog'] });
      toast({ title: 'Blog post created' });
      handleCloseDialog();
    },
    onError: (error) => {
      console.log(error);
      toast({
        title: 'Failed to create blog post',
        variant: 'destructive',
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: any }) =>
      apiRequest('PUT', `/api/admin/blog/${id}`, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/blog'] });
      toast({ title: 'Blog post updated' });
      handleCloseDialog();
    },
    onError: () => {
      toast({ title: 'Failed to update blog post', variant: 'destructive' });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => apiRequest(`/api/admin/blog/${id}`, 'DELETE'),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/blog'] });
      toast({ title: 'Blog post deleted' });
    },
    onError: () => {
      toast({ title: 'Failed to delete blog post', variant: 'destructive' });
    },
  });

  // const publishMutation = useMutation({
  //   mutationFn: (id: string) => apiRequest(`/api/admin/blog/${id}/publish`, 'POST'),
  //   onSuccess: () => {
  //     queryClient.invalidateQueries({ queryKey: ['/api/admin/blog'] });
  //     toast({ title: "Blog post published" });
  //   },
  //   onError: () => {
  //     toast({ title: "Failed to publish blog post", variant: "destructive" });
  //   },
  // });

  const publishMutation = useMutation({
    mutationFn: (id: string) => apiRequest('POST', `/api/admin/blog/${id}/publish`),

    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/blog'] });
      toast({ title: 'Blog post published' });
    },

    onError: () => {
      toast({ title: 'Failed to publish blog post', variant: 'destructive' });
    },
  });

  const handleOpenDialog = (post?: BlogPost) => {
    if (post) {
      setEditingPost(post);
      setFormData({
        title: post.title,
        slug: post.slug,
        excerpt: post.excerpt,
        content: post.content,
        featuredImage: post.featuredImage || '',
        published: post.published,
        metaDescription: post.metaDescription || '',
        metaKeywords: post.metaKeywords?.join(', ') || '',
      });
    } else {
      setEditingPost(null);
      setFormData({
        title: '',
        slug: '',
        excerpt: '',
        content: '',
        featuredImage: '',
        published: false,
        metaDescription: '',
        metaKeywords: '',
      });
    }
    setIsDialogOpen(true);
  };

  useEffect(() => {
    if (isDialogOpen && editor) {
      editor.commands.setContent(formData.content || '');
    }
  }, [isDialogOpen, editor]);


  const handleCloseDialog = () => {
    setIsDialogOpen(false);
    setEditingPost(null);
    editor?.commands.clearContent();
  };


  // const handleSubmit = (e: React.FormEvent) => {
  //   e.preventDefault();

  //   const data = {
  //     ...formData,
  //     metaKeywords: formData.metaKeywords.split(",").map((k) => k.trim()).filter(Boolean),
  //   };

  //   if (editingPost) {
  //     updateMutation.mutate({ id: editingPost.id, data });
  //   } else {
  //     createMutation.mutate(data);
  //   }
  // };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const form = new FormData();

    form.append('title', formData.title);
    form.append('slug', formData.slug);
    form.append('excerpt', formData.excerpt);
    form.append('content', formData.content);
    form.append('published', String(formData.published));
    form.append('metaDescription', formData.metaDescription);
    form.append(
      'metaKeywords',
      JSON.stringify(
        formData.metaKeywords.split(',').map(k => k.trim()).filter(Boolean)
      )
    );

    if (formData.featuredImage) {
      form.append('featuredImage', formData.featuredImage); // <-- File object
    }

    createMutation.mutate(form);
  };

  const generateSlug = () => {
    const slug = formData.title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    setFormData({ ...formData, slug });
  };

  return (
    <>
      <Helmet>
        <title>Blog Management</title>
      </Helmet>

      <div>
        <div className="flex flex-col md:flex-row gap-3 items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold text-foreground" data-testid="text-admin-blog-title">
              Blog Management
            </h1>
            <p className="text-muted-foreground">Create and manage blog posts</p>
          </div>
          <Button onClick={() => handleOpenDialog()} data-testid="button-create-blog-post">
            <Plus className="h-4 w-4 mr-2" />
            New Post
          </Button>
        </div>

        <Card>
          <CardContent className="p-0">
            {isLoading ? (
              <div className="p-8 text-center">Loading...</div>
            ) : data && data.posts.length > 0 ? (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Title</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Author</TableHead>
                    <TableHead>Published</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.posts.map((post) => (
                    <TableRow key={post.id} data-testid={`row-blog-post-${post.id}`}>
                      <TableCell className="font-medium">{post.title}</TableCell>
                      <TableCell>
                        {post.published ? (
                          <span className="text-green-600">Published</span>
                        ) : (
                          <span className="text-yellow-600">Draft</span>
                        )}
                      </TableCell>
                      <TableCell>{post.author?.name || 'Unknown'}</TableCell>
                      <TableCell>
                        {post.publishedAt ? new Date(post.publishedAt).toLocaleDateString() : '-'}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          {!post.published && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => publishMutation.mutate(post.id)}
                              data-testid={`button-publish-${post.id}`}
                            >
                              <Send className="h-4 w-4 mr-1" />
                              Publish
                            </Button>
                          )}
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => window.open(`/blog/${post.slug}`, '_blank')}
                            data-testid={`button-view-${post.id}`}
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleOpenDialog(post)}
                            data-testid={`button-edit-${post.id}`}
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => {
                              if (confirm('Are you sure you want to delete this post?')) {
                                deleteMutation.mutate(post.id);
                              }
                            }}
                            data-testid={`button-delete-${post.id}`}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            ) : (
