      pending: 'secondary',
      approved: 'default',
      suspended: 'destructive',
      completed: 'default',
      paid: 'default',
      overdue: 'destructive',
    };
    return <Badge variant={variants[status] || 'outline'}>{status}</Badge>;
  };

