                <CardContent>
                  <div className="text-3xl font-bold">${analytics?.totalRevenue || '0.00'}</div>
                  <p className="text-sm text-muted-foreground mt-2">From enterprise orders</p>
                </CardContent>
              </Card>

              <Card>
