server/services/sync/sync-scheduler.ts.content:
import { airaloSyncService } from "../airalo/airalo-sync";
import { storage } from "../../storage";
import { providerAutoSyncService } from "./providerAutoSyncService";

const LAST_SYNC_SETTING_KEY = "last_airalo_sync_timestamp";

/**
 * Automatic sync scheduler for Airalo packages
 * Syncs every hour to keep package data up-to-date
 */
export class SyncScheduler {
  private syncInterval: NodeJS.Timeout | null = null;
  private isSyncing = false;
  private readonly SYNC_INTERVAL_MS = 60 * 60 * 1000; // 1 hour in milliseconds

  /**
   * Start the hourly sync scheduler
   */
  async start() {
    console.log("🕐 Starting hourly Airalo sync scheduler...");

    // Check database for last sync time
    const lastSyncTime = await this.getLastSyncTime();
    const now = Date.now();
    const timeSinceLastSync = lastSyncTime ? now - lastSyncTime : Infinity;

    if (timeSinceLastSync >= this.SYNC_INTERVAL_MS) {
      // More than 60 minutes since last sync (or no sync yet) - run now
      console.log("⏰ Running initial sync on startup...");
      this.runSync();
    } else {
      const minutesRemaining = Math.ceil((this.SYNC_INTERVAL_MS - timeSinceLastSync) / 1000 / 60);
      console.log(`⏭️  Skipping initial sync - last sync was ${Math.floor(timeSinceLastSync / 1000 / 60)} minutes ago`);
      console.log(`   Next sync will run in ${minutesRemaining} minutes`);
    }

    // Schedule hourly syncs
    this.syncInterval = setInterval(() => {
      this.runSync();
    }, this.SYNC_INTERVAL_MS);

    console.log(`✅ Sync scheduler started - will sync every ${this.SYNC_INTERVAL_MS / 1000 / 60} minutes`);
  }

  /**
   * Stop the sync scheduler
   */
  stop() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
      this.syncInterval = null;
      console.log("🛑 Sync scheduler stopped");
    }
  }

  /**
   * Run a single sync operation
   */
  private async runSync() {
    if (this.isSyncing) {
      console.log("⏭️ Skipping sync - previous sync still in progress");
      return;
    }

    this.isSyncing = true;
    const startTime = Date.now();

    try {
      console.log(`\n🔄 Starting scheduled provider sync at ${new Date().toISOString()}`);

      // Use improved auto-sync service
      const result = await providerAutoSyncService.syncAll();

      const duration = ((Date.now() - startTime) / 1000).toFixed(2);
      console.log(`\n✅ Scheduled sync completed in ${duration}s`);

      result.providers.forEach(p => {
        console.log(`\n📡 Provider: ${p.provider}`);
        console.log(`   ✔ Success: ${p.success}`);
        console.log(`   📦 Synced: ${p.packagesSynced} | Updated: ${p.packagesUpdated} | Removed: ${p.packagesRemoved}`);
        if (p.errorMessage) {
          console.log(`   ⚠️ Error: ${p.errorMessage}`);
        }
      });

      await this.saveLastSyncTime(Date.now());
    } catch (error: any) {
      console.error(`❌ Scheduled sync failed:`, error.message);
    } finally {
      this.isSyncing = false;
    }
  }


  /**
   * Get last sync time from database
   */
  private async getLastSyncTime(): Promise<number | null> {
    try {
      const setting = await storage.getSettingByKey(LAST_SYNC_SETTING_KEY);
      if (setting && setting.value) {
        const timestamp = parseInt(setting.value);
        return isNaN(timestamp) ? null : timestamp;
      }
    } catch (error) {
      console.warn("Failed to get last sync time from database:", error);
    }
    return null;
  }

  /**
   * Save last sync time to database
   */
  private async saveLastSyncTime(timestamp: number): Promise<void> {
    try {
      await storage.setSetting({
        key: LAST_SYNC_SETTING_KEY,
        value: timestamp.toString(),
        category: "system",
      });
    } catch (error) {
      console.warn("Failed to save last sync time to database:", error);
    }
  }

  /**
   * Trigger a manual sync immediately
   */
  async triggerManualSync() {
    console.log("🔧 Manual sync triggered");
    await this.runSync();
  }
}

// Export singleton instance
export const syncScheduler = new SyncScheduler();

client/src/pages/admin/MasterCountries.t.content:
import { useState, useEffect, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { MapPin, Search, Edit2, Image, Flag, RefreshCw, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import ReactCountryFlag from "react-country-flag";

interface Destination {
  id: string;
  name: string;
  slug: string;
  countryCode: string;
  airaloId: string | null;
  flagEmoji: string | null;
  image: string | null;
  isTerritory: boolean;
  parentCountryCode: string | null;
  active: boolean;
  createdAt: string;
  updatedAt: string;
  packageCounts: {
    airalo: number;
    esimAccess: number;
    esimGo: number;
    total: number;
  };
}

interface CountriesResponse {
  success: boolean;
  data: {
    destinations: Destination[];
    stats: {
      total: number;
      countries: number;
      territories: number;
    };
  };
}

export default function MasterCountries() {
  const { toast } = useToast();
  const [searchInput, setSearchInput] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [editingDestination, setEditingDestination] = useState<Destination | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchInput);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchInput]);

  const { data: countriesData, isLoading } = useQuery<CountriesResponse>({
    queryKey: ["/api/admin/master-countries", { search: debouncedSearch, type: typeFilter }],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (debouncedSearch) params.append("search", debouncedSearch);
      if (typeFilter !== "all") params.append("type", typeFilter);
      const res = await fetch(`/api/admin/master-countries?${params.toString()}`, {
        credentials: "include",
      });
      if (!res.ok) throw new Error("Failed to fetch countries");
      return res.json();
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: any }) => {
      const res = await apiRequest("PATCH", `/api/admin/master-countries/${id}`, data);
      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Success", description: "Country updated successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/master-countries"] });
      setEditingDestination(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update country",
        variant: "destructive",
      });
    },
  });

  const syncMutation = useMutation({
    mutationFn: async () => {
      const res = await apiRequest("POST", "/api/admin/master-countries/sync", {});
      return res.json();
    },
    onSuccess: (data: any) => {
      toast({ 
        title: "Sync Complete", 
        description: `Created ${data.data?.destinationsCreated || 0} countries, updated ${data.data?.destinationsUpdated || 0}` 
      });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/master-countries"] });
    },
    onError: (error: any) => {
      toast({
        title: "Sync Failed",
        description: error.message || "Failed to sync countries",
        variant: "destructive",
      });
    },
  });

  const uploadMutation = useMutation({
    mutationFn: async ({ id, file }: { id: string; file: File }) => {
      const formData = new FormData();
      formData.append("image", file);

      const res = await fetch(`/api/admin/master-countries/${id}/upload-image`, {
        method: "POST",
        credentials: "include",
        body: formData,
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.message || "Upload failed");
      }

      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Success", description: "Image uploaded successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/master-countries"] });
      handleCloseDialog();
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to upload image",
        variant: "destructive",
      });
    },
  });

  const destinations = countriesData?.data?.destinations || [];
  const stats = countriesData?.data?.stats || { total: 0, countries: 0, territories: 0 };
  const totalPackages = destinations.reduce((sum, d) => sum + d.packageCounts.total, 0);

  const handleEditClick = (dest: Destination) => {
    setEditingDestination(dest);
    setSelectedFile(null);
    setPreviewUrl(dest.image || null);
  };

  const handleCloseDialog = () => {
    setEditingDestination(null);
    setSelectedFile(null);
    setPreviewUrl(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
    }
  };

  const handleUploadImage = () => {
    if (editingDestination && selectedFile) {
      uploadMutation.mutate({ id: editingDestination.id, file: selectedFile });
    }
  };

  const handleToggleActive = (dest: Destination) => {
    updateMutation.mutate({ id: dest.id, data: { active: !dest.active } });
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
            <MapPin className="h-6 w-6" />
            Countries & Territories
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">
            Manage destination countries and territories
          </p>
        </div>
        <Button
          onClick={() => syncMutation.mutate()}
          disabled={syncMutation.isPending}
          data-testid="button-sync-countries"
        >
          <RefreshCw className={`h-4 w-4 mr-2 ${syncMutation.isPending ? 'animate-spin' : ''}`} />
          {syncMutation.isPending ? "Syncing..." : "Sync Countries"}
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500">
              Total Destinations
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500">
              Countries
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.countries}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500">
              Territories
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.territories}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-500">
              Total Packages
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalPackages.toLocaleString()}</div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <CardTitle>All Countries</CardTitle>
            <div className="flex flex-col sm:flex-row gap-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <Input
                  placeholder="Search countries..."
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  className="pl-9 w-full sm:w-[200px]"
                  data-testid="input-search-countries"
                />
              </div>
              <Select value={typeFilter} onValueChange={setTypeFilter}>
                <SelectTrigger className="w-full sm:w-[150px]" data-testid="select-type">
                  <SelectValue placeholder="All Types" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="country">Countries</SelectItem>
                  <SelectItem value="territory">Territories</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex items-center justify-center py-8">
              <MapPin className="h-6 w-6 animate-spin text-slate-400" />
            </div>
          ) : destinations.length === 0 ? (
            <div className="text-center py-8 text-slate-500">
              <MapPin className="h-12 w-12 mx-auto mb-4 text-slate-300" />
              <p>No countries found.</p>
            </div>
          ) : (
            <div className="rounded-md border overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Flag</TableHead>
                    <TableHead>Icon</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Code</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Packages</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {destinations.map((dest) => (
                    <TableRow key={dest.id}>
                      <TableCell>
                        <ReactCountryFlag
                          countryCode={dest.countryCode}
                          svg
                          style={{ width: "24px", height: "18px" }}
                          title={dest.name}
                        />
                      </TableCell>
                      <TableCell>
                        {dest.image ? (
                          <img
                            src={dest.image}
                            alt={dest.name}
                            className="w-10 h-10 rounded object-cover"
                          />
                        ) : (
                          <div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-800 flex items-center justify-center">
                            <Flag className="h-5 w-5 text-slate-400" />
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        <span className="font-medium">{dest.name}</span>
                      </TableCell>
                      <TableCell>
                        <code className="text-xs bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded">
                          {dest.countryCode}
                        </code>
                      </TableCell>
                      <TableCell>
                        {dest.isTerritory ? (
                          <Badge variant="secondary" className="bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200">
                            Territory
                          </Badge>
                        ) : (
                          <Badge variant="secondary" className="bg-teal-100 text-teal-800 dark:bg-teal-900 dark:text-teal-200">
                            Country
                          </Badge>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col gap-1 text-xs">
                          <span className="font-medium">
                            {dest.packageCounts.total} total
                          </span>
                          <span className="text-slate-500">
                            A:{dest.packageCounts.airalo} E:{dest.packageCounts.esimAccess} G:{dest.packageCounts.esimGo}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Switch
                          checked={dest.active}
                          onCheckedChange={() => handleToggleActive(dest)}
                          data-testid={`switch-active-${dest.id}`}
                        />
                      </TableCell>
                      <TableCell>
                        <Button
                          size="icon"
                          variant="ghost"
                          onClick={() => handleEditClick(dest)}
                          data-testid={`button-edit-${dest.id}`}
                        >
                          <Edit2 className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={!!editingDestination} onOpenChange={handleCloseDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Country Image</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="flex flex-col items-center gap-4">
              {previewUrl ? (
                <img
                  src={previewUrl}
                  alt="Preview"
                  className="w-32 h-32 rounded object-cover border"
                />
              ) : (
                <div className="w-32 h-32 rounded bg-slate-100 dark:bg-slate-800 flex items-center justify-center border">
                  <Image className="h-12 w-12 text-slate-400" />
                </div>
              )}
              <div className="w-full">
                <Label htmlFor="image-file">Upload Image</Label>
                <div className="flex gap-2 mt-2">
                  <Input
                    ref={fileInputRef}
                    id="image-file"
                    type="file"
                    accept="image/*"
                    onChange={handleFileSelect}
                    className="flex-1"
                    data-testid="input-country-image-file"
                  />
                </div>
                <p className="text-xs text-slate-500 mt-2">
                  Accepted formats: JPG, PNG, GIF, WebP, SVG (max 5MB)
                </p>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={handleCloseDialog}>
              Cancel
            </Button>
            <Button
              onClick={handleUploadImage}
              disabled={uploadMutation.isPending || !selectedFile}
              data-testid="button-upload-country-image"
            >
              <Upload className="h-4 w-4 mr-2" />
              {uploadMutation.isPending ? "Uploading..." : "Upload"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

server/utils/upload.ts.content:
import multer from "multer";
import fs from "fs";
import path from "path";

export function createMultiUploader(folderName: string, fields: { name: string; maxCount: number }[]) {
  const uploadPath = path.join(process.cwd(), "uploads", folderName);

  // Create folder if not exists
  if (!fs.existsSync(uploadPath)) {
    fs.mkdirSync(uploadPath, { recursive: true });
  }

  const storage = multer.diskStorage({
    destination: (req, file, cb) => {
      cb(null, uploadPath);
    },
    filename: (req, file, cb) => {
      const ext = path.extname(file.originalname);
      const uniqueName = `${Date.now()}-${Math.random().toString(36).substring(2)}${ext}`;
      cb(null, uniqueName);
    },
  });

  const upload = multer({
    storage,
    limits: { fileSize: 10 * 1024 * 1024 }, // 10 MB
  });

  return upload.fields(fields);
}

server/services/esim-access/topup-sync.t.content:
"use strict";

import { db } from "../../db";
import { eq } from "drizzle-orm";
import {
  esimAccessTopups,
  esimAccessPackages,
  type Provider,
  type InsertEsimAccessTopup,
} from "@shared/schema";
import { makeEsimAccessRequest, formatDataAmount } from "./api";
import crypto from "crypto";

interface EsimAccessTopupListResponse {
  success: boolean;
  obj: {
    packageList: Array<{
      packageCode: string;
      slug: string;
      name: string;
      price: number;
      currencyCode: string;
      volume: number;
      duration: number;
      durationUnit: string;
      dataType?: number;
      location?: string;
      locationNetworkList?: Array<{
        locationLogo?: string;
        operatorList?: Array<{ operatorName?: string }>;
      }>;
    }>;
  };
}

function generateDataHash(data: Record<string, any>): string {
  const normalized = JSON.stringify(data, Object.keys(data).sort());
  return crypto.createHash("md5").update(normalized).digest("hex");
}

/**
 * Sync eSIM Access topup packages.
 * 
 * This function fetches ALL topup packages in a single API call using { type: "TOPUP" },
 * matching the approach used for base packages. This is much more efficient than
 * making individual API calls per base package.
 */
export async function syncEsimAccessTopups(
  provider: Provider,
  accessCode: string,
  secretKey: string
): Promise<{
  success: boolean;
  topupsSynced: number;
  topupsUpdated: number;
  topupsSkipped: number;
  errorMessage?: string;
}> {
  try {
    console.log("[eSIM Access Topup Sync] Fetching ALL topup packages in single API call...");

    // Fetch ALL topup packages in one call (same approach as base package sync)
    const response = await makeEsimAccessRequest<EsimAccessTopupListResponse>(
      "/api/v1/open/package/list",
      "POST",
      { type: "TOPUP" },
      accessCode,
      secretKey
    );

    if (!response.success || !response.obj?.packageList) {
      return {
        success: false,
        topupsSynced: 0,
        topupsUpdated: 0,
        topupsSkipped: 0,
        errorMessage: "Failed to fetch topup packages from API",
      };
    }

    const apiPackages = response.obj.packageList;
    console.log(`[eSIM Access Topup Sync] Received ${apiPackages.length} topup packages from API`);

    // Get existing topups and base packages for reference
    const existingTopups = await db.select().from(esimAccessTopups);
    const existingByEsimAccessId = new Map(existingTopups.map((t) => [t.esimAccessId, t]));

    // Get base packages to link topups to their parent
    const basePackages = await db.select().from(esimAccessPackages);
    const basePackageBySlug = new Map(basePackages.map((p) => [p.slug, p]));

    let topupsSynced = 0;
    let topupsUpdated = 0;
    let topupsSkipped = 0;

    for (const apiPkg of apiPackages) {
      const wholesalePrice = apiPkg.price / 10000;
      const operator = apiPkg.locationNetworkList?.[0]?.operatorList?.[0]?.operatorName || null;

      const rawOperatorImage = apiPkg.locationNetworkList?.[0]?.locationLogo || null;
      let operatorImage: string | null = null;
      if (rawOperatorImage) {
        operatorImage = rawOperatorImage.startsWith("http")
          ? rawOperatorImage
          : rawOperatorImage.startsWith("/img/")
          ? `https://static.redteago.com${rawOperatorImage}`
          : rawOperatorImage;
      }

      // Try to find a matching base package by slug pattern
      // Topup slugs often relate to base package slugs
      const basePackageSlug = apiPkg.slug;
      const basePkg = basePackageBySlug.get(basePackageSlug);

      // Determine package type from location
      const countryCodes = apiPkg.location
        ? apiPkg.location.split(",").map((c) => c.trim()).filter(Boolean)
        : [];
      const isGlobal = apiPkg.location?.startsWith("!GL") || false;
      const isRegional = !isGlobal && (countryCodes.length > 1 || apiPkg.location?.startsWith("!RG"));
      const type = isGlobal ? "global" : isRegional ? "regional" : "local";

      const topupData: InsertEsimAccessTopup = {
        providerId: provider.id,
        esimAccessId: apiPkg.packageCode,
        basePackageCode: apiPkg.slug,
        parentPackageId: basePkg?.id || null,
        destinationId: basePkg?.destinationId || null,
        regionId: basePkg?.regionId || null,
        slug: `topup-${apiPkg.slug || apiPkg.packageCode}`,
        title: apiPkg.name,
        dataAmount: formatDataAmount(apiPkg.volume),
        validity: apiPkg.duration,
        wholesalePrice: wholesalePrice.toString(),
        currency: apiPkg.currencyCode,
        type: type,
        operator,
        operatorImage,
        isUnlimited: apiPkg.dataType === 4,
        active: true,
      };

      const dataHash = generateDataHash({
        title: topupData.title,
        dataAmount: topupData.dataAmount,
        validity: topupData.validity,
        wholesalePrice: topupData.wholesalePrice,
      });

      const existing = existingByEsimAccessId.get(apiPkg.packageCode);

      if (existing) {
        if (existing.dataHash !== dataHash) {
          await db
            .update(esimAccessTopups)
            .set({ ...topupData, dataHash, updatedAt: new Date() })
            .where(eq(esimAccessTopups.id, existing.id));
          topupsUpdated++;
        } else {
          topupsSkipped++;
        }
      } else {
        await db.insert(esimAccessTopups).values({ ...topupData, dataHash });
        topupsSynced++;
      }
    }

    console.log(
      `[eSIM Access Topup Sync] Complete: ${topupsSynced} new, ${topupsUpdated} updated, ${topupsSkipped} unchanged`
    );

    return {
      success: true,
      topupsSynced,
      topupsUpdated,
      topupsSkipped,
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    console.error("[eSIM Access Topup Sync] Error:", errorMessage);

    return {
      success: false,
      topupsSynced: 0,
      topupsUpdated: 0,
      topupsSkipped: 0,
      errorMessage,
    };
  }
}

server/services/androidIap.service.ts.content:
import { CreateInAppProductJob } from "server/jobs/createInAppProduct.job";

export async function syncAndroidIapForBracket(bracket: {
    productId: string;
    setPrice: string | number;
    currency: string;
}) {
    try {
        const job = new CreateInAppProductJob({
            sku: bracket.productId,
            title: bracket.productId,
            description: "eSIM in 30 seconds",
            price: Number(bracket.setPrice),
            currency: bracket.currency,
        });

        await job.handle();

        // job.handle() already updates DB to active
        return { success: true };
    } catch (err: any) {
        // job.handle() already updates DB to error
        return { success: false, error: err.message };
    }
}

