server/routes/admin/PrivacyPolicy.ts.content:
import { Router } from "express";
import { eq, desc } from "drizzle-orm";
import { z } from "zod";
import { db } from "server/db";
import {
    privacyPolicies,
    insertPrivacyPolicySchema,
} from "@shared/schema";
import { requireAdmin } from "server/lib/middleware";

const router = Router();

/* ======================================================
   CREATE / UPDATE PRIVACY POLICY (ADMIN)
   POST /api/admin/privacy-policy
====================================================== */
router.post("/", async (req, res) => {
  try {
    // 🔎 Validate request body
    const validatedData = insertPrivacyPolicySchema.parse(req.body);

    // 1️⃣ Deactivate old policies
    await db
      .update(privacyPolicies)
      .set({
        isActive: false,
        updatedAt: new Date(),
      })
      .where(eq(privacyPolicies.isActive, true));

    // 2️⃣ Get latest version
    const [latestPolicy] = await db
      .select()
      .from(privacyPolicies)
      .orderBy(desc(privacyPolicies.version))
      .limit(1);

    const nextVersion = latestPolicy ? latestPolicy.version + 1 : 1;

    // 3️⃣ Insert new policy
    const [newPolicy] = await db
      .insert(privacyPolicies)
      .values({
        title: validatedData.title,
        content: validatedData.content,
        version: nextVersion,
        isActive: true,
      })
      .returning();

    return res.status(201).json({
      success: true,
      message: "Privacy Policy updated successfully",
      data: newPolicy,
    });
  } catch (error) {
    console.error("Error creating/updating Privacy Policy:", error);

    if (error instanceof z.ZodError) {
      return res.status(400).json({
        success: false,
        message: "Validation error",
        errors: error.errors,
      });
    }

    return res.status(500).json({
      success: false,
      message: "Failed to update Privacy Policy",
      error: error instanceof Error ? error.message : "Unknown error",
    });
  }
});

/* ======================================================
   GET ALL PRIVACY POLICY VERSIONS (ADMIN)
   GET /api/admin/privacy-policy
====================================================== */
router.get("/", async (_req, res) => {
  try {
    const policies = await db
      .select()
      .from(privacyPolicies)
      .orderBy(desc(privacyPolicies.version));

    return res.json({
      success: true,
      data: policies,
    });
  } catch (error) {
    console.error("Error fetching Privacy Policies:", error);

    return res.status(500).json({
      success: false,
      message: "Failed to fetch Privacy Policies",
    });
  }
});

export default router;

client/src/components/payments/RazorpayP.content:
interface Props {
  orderId: string;
  amount: number;
  currency: string;
  publicKey: string;
  email: string;
  guestAccessToken?: string;
}

export default function RazorpayPayment({
  orderId,
  amount,
  currency,
  publicKey,
  email,
  guestAccessToken, // ✅ FIX 1
}: Props) {
  const openRazorpay = () => {
    const options = {
      key: publicKey,
      amount,
      currency,
      order_id: orderId,
      name: "eSIM Connect",
      description: "Order Payment",
      prefill: { email },

      handler: async (response: any) => {
        console.log("✅ Razorpay success", response);

        const params = new URLSearchParams({
          providerType: "razorpay",
          orderId: response.razorpay_order_id,
          paymentId: response.razorpay_payment_id,
          signature: response.razorpay_signature,
          redirect_status: "succeeded",
        });

        // ✅ FIX 2 — only append for guest
        if (guestAccessToken) {
          params.append("guestAccessToken", guestAccessToken);
        }

        window.location.href =
          `${window.location.origin}/order/processing?${params.toString()}`;
      },
    };

    const rzp = new (window as any).Razorpay(options);
    rzp.open();
  };

  return (
    <button onClick={openRazorpay} className="btn-primary w-full">
      Pay with Razorpay
    </button>
  );
}

server/services/ordering/provider-select.content:
import { db } from "../../db";
import { providers, unifiedPackages } from "@shared/schema";
import { eq, and, ne } from "drizzle-orm";
import type { ProviderCandidate } from "./types";
import { marginCalculator } from "./margin-calculator";

export class ProviderSelector {
  async getEnabledProviders(): Promise<Array<{
    id: string;
    name: string;
    slug: string;
    failoverPriority: number;
    minMarginPercent: number;
  }>> {
    const enabledProviders = await db.query.providers.findMany({
      where: eq(providers.enabled, true),
    });

    return enabledProviders.map(p => ({
      id: p.id,
      name: p.name,
      slug: p.slug,
      failoverPriority: p.failoverPriority,
      minMarginPercent: parseFloat(p.minMarginPercent || "0"),
    }));
  }

  async findAlternativePackages(
    currentPackageId: string,
    currentProviderId: string,
    retailPrice: number
  ): Promise<ProviderCandidate[]> {
    const currentPackage = await db.query.unifiedPackages.findFirst({
      where: eq(unifiedPackages.id, currentPackageId),
    });

    if (!currentPackage) {
      return [];
    }

    const alternatives = await db.query.unifiedPackages.findMany({
      where: and(
        eq(unifiedPackages.destinationId, currentPackage.destinationId!),
        eq(unifiedPackages.dataAmount, currentPackage.dataAmount),
        eq(unifiedPackages.validity, currentPackage.validity),
        eq(unifiedPackages.isEnabled, true),
        ne(unifiedPackages.providerId, currentProviderId)
      ),
      with: {
        provider: true,
      },
    });

    const enabledProviders = await this.getEnabledProviders();
    const enabledProviderIds = new Set(enabledProviders.map(p => p.id));

    const candidates: ProviderCandidate[] = [];

    for (const pkg of alternatives) {
      if (!pkg.provider || !enabledProviderIds.has(pkg.providerId!)) {
        continue;
      }

      const provider = enabledProviders.find(p => p.id === pkg.providerId);
      if (!provider) continue;

      const wholesalePrice = parseFloat(pkg.wholesalePrice);
      const minMargin = await marginCalculator.getProviderMinMargin(pkg.providerId!);
      const marginCalc = marginCalculator.validateMargin(wholesalePrice, retailPrice, minMargin);

      if (!marginCalc.passed) {
        continue;
      }

      candidates.push({
        providerId: pkg.providerId!,
        providerName: pkg.provider.name,
        providerSlug: pkg.provider.slug,
        packageId: pkg.id,
        providerPackageId: pkg.providerPackageId!,
        wholesalePrice,
        priority: provider.failoverPriority,
        minMarginPercent: minMargin,
      });
    }

    return this.rankByPriority(candidates);
  }

  rankByPriority(candidates: ProviderCandidate[]): ProviderCandidate[] {
    return candidates.sort((a, b) => {
      if (a.priority !== b.priority) {
        return a.priority - b.priority;
      }
      return a.wholesalePrice - b.wholesalePrice;
    });
  }

  async isProviderEnabled(providerId: string): Promise<boolean> {
    const provider = await db.query.providers.findFirst({
      where: and(
        eq(providers.id, providerId),
        eq(providers.enabled, true)
      ),
    });
    return !!provider;
  }
}

export const providerSelector = new ProviderSelector();

