import { cn } from "@/lib/utils";
import {
  AnimatePresence,
  MotionValue,
  motion,
  useMotionValue,
  useSpring,
  useTransform,
} from "motion/react";
import { Link, useLocation } from "wouter";
import { useRef, useState } from "react";

export const FloatingDock = ({
  items,
  desktopClassName,
  mobileClassName,
}: {
  items: { title: string; icon: React.ReactNode; href: string }[];
  desktopClassName?: string;
  mobileClassName?: string;
}) => {
  return (
    <>
      <FloatingDockDesktop items={items} className={desktopClassName} />
      <FloatingDockMobile items={items} className={mobileClassName} />
    </>
  );
};

const FloatingDockMobile = ({
  items,
  className,
}: {
  items: { title: string; icon: React.ReactNode; href: string }[];
  className?: string;
}) => {
  const [location] = useLocation();

  return (
    <div className={cn("fixed inset-x-0 bottom-0 z-[9999] block md:hidden", className)}>
      <div 
        className="flex items-center justify-around mx-3 mb-3 rounded-2xl px-2 py-2 gap-0.5 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border border-neutral-200/50 dark:border-neutral-700/50 shadow-lg"
        style={{ paddingBottom: 'max(0.5rem, env(safe-area-inset-bottom))' }}
      >
        {items.map((item) => {
          const isActive = location === item.href || 
            (item.href !== "/" && location.startsWith(item.href));

          return (
            <Link
              key={item.title}
              href={item.href}
              className="flex flex-col items-center justify-center gap-0.5 px-1 py-1 min-w-0 flex-1"
              data-testid={`nav-mobile-${item.title.toLowerCase().replace(/\s+/g, '-')}`}
            >
              <div className={cn(
                "flex h-8 w-8 items-center justify-center rounded-full transition-all duration-200",
                isActive 
                  ? "bg-primary/15 dark:bg-primary/25" 
                  : "bg-transparent"
              )}>
                <div className={cn(
                  "h-4 w-4 transition-colors",
                  isActive 
                    ? "text-primary" 
                    : "text-neutral-500 dark:text-neutral-400"
                )}>
                  {item.icon}
                </div>
              </div>
              <span className={cn(
                "text-[9px] font-medium transition-colors whitespace-nowrap",
                isActive 
                  ? "text-primary" 
                  : "text-neutral-500 dark:text-neutral-400"
              )}>
                {item.title}
              </span>
            </Link>
          );
        })}
      </div>
    </div>
  );
};

const FloatingDockDesktop = ({
  items,
  className,
}: {
  items: { title: string; icon: React.ReactNode; href: string }[];
  className?: string;
}) => {
  const mouseX = useMotionValue(Infinity);
  return (
    <motion.div
      onMouseMove={(e) => mouseX.set(e.pageX)}
      onMouseLeave={() => mouseX.set(Infinity)}
      className={cn(
        "fixed bottom-6 left-1/2 -translate-x-1/2 z-[9999] hidden h-16 items-end gap-4 rounded-2xl px-4 pb-3 md:flex bg-white/90 dark:bg-neutral-900/90 backdrop-blur-xl border border-neutral-200/50 dark:border-neutral-700/50 shadow-lg",
        className
      )}
    >
      {items.map((item) => (
        <IconContainer mouseX={mouseX} key={item.title} {...item} />
      ))}
    </motion.div>
  );
};

function IconContainer({
  mouseX,
  title,
  icon,
  href,
}: {
  mouseX: MotionValue;
  title: string;
  icon: React.ReactNode;
  href: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [location] = useLocation();
  const isActive = location === href || (href !== "/" && location.startsWith(href));

  const distance = useTransform(mouseX, (val) => {
    const bounds = ref.current?.getBoundingClientRect() ?? { x: 0, width: 0 };
    return val - bounds.x - bounds.width / 2;
  });

  const widthTransform = useTransform(distance, [-150, 0, 150], [40, 70, 40]);
  const heightTransform = useTransform(distance, [-150, 0, 150], [40, 70, 40]);

  const widthTransformIcon = useTransform(distance, [-150, 0, 150], [20, 35, 20]);
  const heightTransformIcon = useTransform(
    distance,
    [-150, 0, 150],
    [20, 35, 20]
  );

  const width = useSpring(widthTransform, {
    mass: 0.1,
    stiffness: 150,
    damping: 12,
  });
  const height = useSpring(heightTransform, {
    mass: 0.1,
    stiffness: 150,
    damping: 12,
  });

  const widthIcon = useSpring(widthTransformIcon, {
    mass: 0.1,
    stiffness: 150,
    damping: 12,
  });
  const heightIcon = useSpring(heightTransformIcon, {
    mass: 0.1,
    stiffness: 150,
    damping: 12,
  });

  const [hovered, setHovered] = useState(false);

  return (
    <Link href={href} data-testid={`nav-desktop-${title.toLowerCase().replace(/\s+/g, '-')}`}>
      <motion.div
        ref={ref}
        style={{ width, height }}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        className={cn(
          "relative flex aspect-square items-center justify-center rounded-full transition-colors",
          isActive
            ? "bg-primary/15 dark:bg-primary/25"
            : "bg-neutral-100/80 dark:bg-neutral-800/80"
        )}
      >
        <AnimatePresence>
          {hovered && (
            <motion.div
              initial={{ opacity: 0, y: 10, x: "-50%" }}
              animate={{ opacity: 1, y: 0, x: "-50%" }}
              exit={{ opacity: 0, y: 2, x: "-50%" }}
              className="absolute -top-8 left-1/2 w-fit rounded-md bg-neutral-900 dark:bg-white px-2 py-0.5 text-xs whitespace-pre text-white dark:text-neutral-900 shadow-lg"
            >
              {title}
            </motion.div>
          )}
        </AnimatePresence>
        <motion.div
          style={{ width: widthIcon, height: heightIcon }}
          className={cn(
            "flex items-center justify-center",
            isActive 
              ? "[&>*]:text-primary" 
              : "[&>*]:text-neutral-600 dark:[&>*]:text-neutral-400"
          )}
        >
          {icon}
        </motion.div>
      </motion.div>
    </Link>
  );
}

client/src/components/admin/tabs/SocialM.content:
import React, { useState, useEffect, useMemo } from "react";
import {
  Save,
  Globe,
  Facebook,
  Instagram,
  Twitter,
  Linkedin,
  Youtube,
  Loader2,
  Info,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { useTranslation } from "@/contexts/TranslationContext";
import { useToast } from "@/hooks/use-toast";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { FaAndroid, FaAppStoreIos } from "react-icons/fa";

export function SocialMediaSettings() {
  const { t } = useTranslation();
  const { toast } = useToast();

  // Local state
  const [website, setWebsite] = useState("");
  const [facebook, setFacebook] = useState("");
  const [instagram, setInstagram] = useState("");
  const [twitter, setTwitter] = useState("");
  const [linkedin, setLinkedin] = useState("");
  const [youtube, setYoutube] = useState("");
  const [android, setAndroid] = useState("");
  const [ios, setIos] = useState("");

  // Fetch settings
  const { data: settingsResponse } = useQuery({
    queryKey: ["/api/admin/settings"],
  });

  // console.log("nsd sdfds", settingsResponse)
  // Convert array → object
  const settings = useMemo(() => {
    if (!settingsResponse) return {};
    return settingsResponse.reduce(
      (acc: Record<string, string>, s: any) => {
        acc[s.key] = s.value;
        return acc;
      },
      {}
    );
  }, [settingsResponse]);

  // console.log("sdfafasasdas", settings)

  // Load values
  useEffect(() => {
    if (!settings) return;

    setWebsite(settings.website_url || "");
    setFacebook(settings.social_facebook || "");
    setInstagram(settings.social_instagram || "");
    setTwitter(settings.social_twitter || "");
    setLinkedin(settings.social_linkedin || "");
    setYoutube(settings.social_youtube || "");
    setAndroid(settings.social_android || "");
    setIos(settings.social_ios || "");
  }, [settings]);

  // Mutation
  const updateSettingMutation = useMutation({
    mutationFn: async ({
      key,
      value,
      category,
    }: {
      key: string;
      value: string;
      category: string;
    }) =>
      apiRequest("PUT", `/api/admin/settings/${key}`, {
        value,
        category,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
      toast({
        title: t("admin.settings.success", "Success"),
        description: t(
          "admin.settings.settingsUpdatedSuccess",
          "Settings updated successfully"
        ),
      });
    },
    onError: (err: any) => {
      toast({
        title: t("admin.settings.error", "Error"),
        description:
          err.message ||
          t(
            "admin.settings.failedToUpdateSettings",
            "Failed to update settings"
          ),
        variant: "destructive",
      });
    },
  });

  const save = async (key: string, value: string) =>
    updateSettingMutation.mutateAsync({
      key,
      value,
      category: "social",
    });

  const handleSave = async () => {
    await save("website_url", website);
    await save("social_facebook", facebook);
    await save("social_instagram", instagram);
    await save("social_twitter", twitter);
    await save("social_linkedin", linkedin);
    await save("social_youtube", youtube);
    await save("social_android", android);
    await save("social_ios", ios);
  };

  return (
    <div className="space-y-6">
      <Card className="border-0 shadow-xl">
        <CardHeader>
          <div className="flex items-center gap-3">
            <div className="h-12 w-12 rounded-xl bg-gradient-to-br from-[var(--primary-hex)] to-[var(--primary-second-hex)] flex items-center justify-center shadow-lg">
              <Globe className="h-6 w-6 text-black" />
            </div>
            <div>
              <CardTitle className="text-2xl font-bold bg-gradient-to-r from-[var(--primary-hex)] to-[var(--primary-second-hex)] bg-clip-text text-transparent">
                {t("admin.settings.social.title", "Social Media Links")}
              </CardTitle>
              <CardDescription className="text-lg text-[var(--primary-hex)]/70">
                {t(
                  "admin.settings.social.description",
                  "Manage website and social media profile links"
                )}
              </CardDescription>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-8 space-y-6">
          {/* Website */}
          <Field
            icon={<Globe />}
            label="Website URL"
            value={website}
            onChange={setWebsite}
            placeholder="https://yourdomain.com"
          />

          <Field
            icon={<Facebook />}
            label="Facebook"
            value={facebook}
            onChange={setFacebook}
            placeholder="https://facebook.com/yourpage"
          />

          <Field
            icon={<Instagram />}
            label="Instagram"
            value={instagram}
            onChange={setInstagram}
            placeholder="https://instagram.com/yourprofile"
          />

          <Field
            icon={<Twitter />}
            label="Twitter / X"
            value={twitter}
            onChange={setTwitter}
            placeholder="https://x.com/yourprofile"
          />

          <Field
            icon={<Linkedin />}
            label="LinkedIn"
            value={linkedin}
            onChange={setLinkedin}
            placeholder="https://linkedin.com/company/yourcompany"
          />

          <Field
            icon={<Youtube />}
            label="YouTube"
            value={youtube}
            onChange={setYoutube}
            placeholder="https://youtube.com/@yourchannel"
          />

          <Field
            icon={<FaAndroid />}
            label="Android"
            value={android}
            onChange={setAndroid}
            placeholder="https://play.google.com/store/apps/details?id=com.yourapp"
          />

          <Field
            icon={<FaAppStoreIos />}
            label="IOS"
            value={ios}
            onChange={setIos}
            placeholder="https://apps.apple.com/app/yourapp"
          />

          <Button
            onClick={handleSave}
            disabled={updateSettingMutation.isPending}
            className="gap-2 h-12 px-8 text-lg bg-gradient-to-r from-[var(--primary-hex)] to-[var(--primary-second-hex)] shadow-lg"
          >
            {updateSettingMutation.isPending ? (
              <>
                <Loader2 className="h-5 w-5 animate-spin" />
                Saving...
              </>
            ) : (
              <>
                <Save className="h-5 w-5" />
                Save Social Links
              </>
            )}
          </Button>
        </CardContent>
      </Card>

      {/* Info */}
      <Card className="border-0 bg-gradient-to-br from-blue-50 to-transparent shadow-md">
        <CardContent className="pt-6 flex gap-3">
          <Info className="h-5 w-5 text-blue-600 mt-0.5" />
          <p className="text-sm text-blue-800">
            These links may be shown in the footer, contact page, or mobile app.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

/* ---------- Reusable Field ---------- */

function Field({
  icon,
  label,
  value,
  onChange,
  placeholder,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder: string;
}) {
  return (
    <div className="space-y-3">
      <Label className="text-lg font-semibold flex items-center gap-2">
        <span className="text-[var(--primary-hex)]">{icon}</span>
        {label}
      </Label>
      <Input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="h-12 ring-2 ring-[var(--primary-hex)]/20 focus:ring-[var(--primary-hex)]"
      />
    </div>
  );
}

server/services/sync/providerAutoSyncSer.content:
"use strict";

import { db } from "../../db";
import { providers } from "@shared/schema";
import { eq, or } from "drizzle-orm";

export class ProviderAutoSyncService {
    async syncAll() {
        // Fetch all providers that should be synced
        const providerList = await db.query.providers.findMany({
            where: or(
                eq(providers.slug, "airalo"),
                eq(providers.slug, "esim-access"),
                eq(providers.slug, "esim-go"),
                eq(providers.slug, "maya")
            ),
        });

        if (!providerList || providerList.length === 0) {
            return { success: false, message: "No providers found for auto sync" };
        }

        const { providerFactory } = await import("../../providers/provider-factory");
        const { unifiedPackagesSyncService } = await import("../sync/unified-packages-sync");

        const results = [];

        for (const provider of providerList) {
            if (!provider.enabled) {
                results.push({
                    provider: provider.slug,
                    success: false,
                    message: "Provider disabled, skipping",
                });
                continue;
            }

            try {
                // Load provider service
                const service = await providerFactory.getServiceById(provider.id);

                // Run sync
                const syncResult = await service.syncPackages();

                // Update last sync timestamp
                await db.update(providers)
                    .set({ lastSyncAt: new Date() })
                    .where(eq(providers.id, provider.id));

                // Sync unified packages
                if (syncResult.success) {
                    await unifiedPackagesSyncService.syncProviderPackages(provider.slug);
                }

                results.push({
                    provider: provider.slug,
                    success: syncResult.success,
                    packagesSynced: syncResult.packagesSynced,
                    packagesUpdated: syncResult.packagesUpdated,
                    packagesRemoved: syncResult.packagesRemoved,
                    errorMessage: syncResult.errorMessage || null,
                });

            } catch (err: any) {
                results.push({
                    provider: provider.slug,
                    success: false,
                    message: err.message,
                });
            }
        }

        // Clear service cache after all syncs
        providerFactory.clearCache();

        return {
            success: true,
            message: "Auto sync completed",
            providers: results,
        };
    }
}

export const providerAutoSyncService = new ProviderAutoSyncService();

