      await db.update(referralProgram)
        .set({
          totalReferrals: sql`${referralProgram.totalReferrals} + 1`,
          totalEarnings: sql`${referralProgram.totalEarnings} + ${rewardAmount}`,
          updatedAt: new Date(),
        })
        .where(eq(referralProgram.userId, referrerId));

