        success: true,
        creditsApplied: Number(discount.toFixed(2)),
        discount: Number(discount.toFixed(2)),
        finalTotal: Number(finalTotal.toFixed(2)),
        remainingBalance: Number((currentBalance - discount).toFixed(2))
