        documentType,
        filePath: req.file.path,
        fileName: req.file.originalname,
        fileSize: req.file.size,
        mimeType: req.file.mimetype,
        status: "pending",
      });

      await storage.updateUser(userId, { kycStatus: "submitted" });

      logger.info("KYC document uploaded", {
