        query = query.where(
          or(
            ilike(regions.name, `%${search}%`),
            ilike(regions.slug, `%${search}%`)
          )
        ) as typeof query;
      }

      const regionsData = await query.orderBy(regions.name);

      // Get package counts per region from all providers
      const airaloCountsResult = await db.execute(sql`
        SELECT region_id, COUNT(*)::int as count 
        FROM airalo_packages 
        WHERE region_id IS NOT NULL 
        GROUP BY region_id
      `);
      const airaloCounts = new Map((airaloCountsResult.rows as any[])?.map(r => [r.region_id, r.count]) || []);

      const esimAccessCountsResult = await db.execute(sql`
        SELECT region_id, COUNT(*)::int as count 
        FROM esim_access_packages 
        WHERE region_id IS NOT NULL 
        GROUP BY region_id
      `);
      const esimAccessCounts = new Map((esimAccessCountsResult.rows as any[])?.map(r => [r.region_id, r.count]) || []);

      const esimGoCountsResult = await db.execute(sql`
        SELECT region_id, COUNT(*)::int as count 
        FROM esim_go_packages 
        WHERE region_id IS NOT NULL 
        GROUP BY region_id
      `);
      const esimGoCounts = new Map((esimGoCountsResult.rows as any[])?.map(r => [r.region_id, r.count]) || []);

      const mayaCountsResult = await db.execute(sql`
        SELECT region_id, COUNT(*)::int as count 
        FROM maya_packages 
        WHERE region_id IS NOT NULL 
        GROUP BY region_id
      `);
      const mayaCounts = new Map((mayaCountsResult.rows as any[])?.map(r => [r.region_id, r.count]) || []);

      // Combine data with counts
      const regionsWithCounts = regionsData.map(region => ({
        ...region,
        packageCounts: {
          airalo: airaloCounts.get(region.id) || 0,
          esimAccess: esimAccessCounts.get(region.id) || 0,
          esimGo: esimGoCounts.get(region.id) || 0,
          maya: mayaCounts.get(region.id) || 0,
          total: (airaloCounts.get(region.id) || 0) + (esimAccessCounts.get(region.id) || 0) + (esimGoCounts.get(region.id) || 0) + (mayaCounts.get(region.id) || 0),
