      res.status(500).json({ success: false, message: error.message });
    }
  });

  // ==================== IMAGE UPLOAD ROUTES ====================

  // Upload region image
  app.post("/api/admin/master-regions/:id/upload-image", requireAdmin, async (req: Request, res: Response) => {
