                            </div>
                          )}
                          {order.package.region && (
                            <div className="flex items-center gap-2">
                              <Globe className="h-4 w-4 text-slate-400" />
                              <span className="text-sm font-medium text-slate-900 dark:text-white">
                                {order.package.region.name}
                              </span>
                            </div>
