                                        field.value === currency.id ? 'opacity-100' : 'opacity-0',
                                      )}
                                    />
                                    {currency.symbol} {currency.code} — {currency.name}
                                  </CommandItem>
                                ))}
                              </CommandList>
                            </Command>
                          </PopoverContent>
                        </Popover>

                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <div className="flex gap-3">
                    <Button
                      type="submit"
