            variant="outline"
            className="gap-2"
            data-testid="button-export-csv"
          >
            <Download className="h-4 w-4" />
            {t('admin.notifications.button.export', 'Export CSV')}
          </Button>
        </div>
      </div>

      {/* Statistics */}
