                <div>
                  <Label className="text-xs text-muted-foreground">
                    {t('admin.notifications.details.type', 'Type')}
                  </Label>
                  <div className="mt-1">
                    <Badge variant={getTypeInfo(selectedNotification.type).variant}>
                      {getTypeInfo(selectedNotification.type).label}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">
