              </Label>
              <Textarea
                id="modal-message"
                placeholder={t(
                  'admin.notifications.custom.messagePlaceholder',
                  'Enter your notification message...',
                )}
                rows={6}
                value={customMessage}
                onChange={(e) => setCustomMessage(e.target.value)}
                data-testid="textarea-modal-message"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="modal-recipient-type">
                {t('admin.notifications.custom.sendTo', 'Send To')}
              </Label>
              <Select
                value={recipientType}
                onValueChange={(value: 'all' | 'single') => setRecipientType(value)}
              >
                <SelectTrigger data-testid="select-modal-recipient-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">
                    {t('admin.notifications.custom.allCustomers', 'All Customers')}
                  </SelectItem>
                  <SelectItem value="single">
                    {t('admin.notifications.custom.singleCustomer', 'Single Customer')}
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            {recipientType === 'single' && (
              <div className="space-y-2">
                <Label>{t('admin.notifications.custom.selectCustomer', 'Select Customer')}</Label>

                <Popover open={open} onOpenChange={setOpen}>
                  <PopoverTrigger asChild>
                    <div
                      role="combobox"
                      className="border rounded-md h-10 px-3 flex items-center justify-between cursor-pointer"
                    >
                      <span>
                        {customers?.find((c) => c.id === recipientUserId)?.name ||
                          t('admin.notifications.custom.chooseCustomer', 'Choose a customer')}
                      </span>
                    </div>
                  </PopoverTrigger>

                  <PopoverContent className="p-0 w-[300px]">
                    <Command>
                      <CommandInput placeholder="Search customer..." onValueChange={setSearch} />
                      <CommandEmpty>No customer found.</CommandEmpty>

                      <CommandGroup>
                        {customers?.map((customer) => (
                          <CommandItem
                            key={customer.id}
                            value={`${customer.name} ${customer.email}`}
                            onSelect={() => {
                              setRecipientUserId(customer.id);
                              setOpen(false);
                            }}
                          >
                            {customer.name || customer.email} ({customer.email})
                            <Check
                              className={cn(
                                'ml-auto h-4 w-4',
                                customer.id === recipientUserId ? 'opacity-100' : 'opacity-0',
                              )}
                            />
                          </CommandItem>
                        ))}
                      </CommandGroup>
                    </Command>
                  </PopoverContent>
                </Popover>
              </div>
            )}

            <div className="space-y-3 pt-2 border-t">
              <Label className="text-sm font-medium">
                {t('admin.notifications.custom.deliveryMethods', 'Delivery Methods')}
              </Label>
              {/* <div className="flex items-center space-x-2">
                <Checkbox
                  id="send-email"
                  checked={sendEmail}
                  onCheckedChange={setSendEmail}
                  data-testid="checkbox-send-email"
                />
                <label
                  htmlFor="send-email"
                  className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer"
                >
                  {t('admin.notifications.custom.sendEmail', 'Send Email')}
                </label>
              </div> */}
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="send-in-app"
                  checked={sendInApp}
                  onCheckedChange={setSendInApp}
                  data-testid="checkbox-send-in-app"
                />
                <label
                  htmlFor="send-in-app"
                  className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer"
                >
                  {t('admin.notifications.custom.sendInApp', 'Send In-App Notification')}
                </label>
              </div>
              <p className="text-xs text-muted-foreground">
                {t(
                  'admin.notifications.custom.methodRequired',
                  'At least one delivery method must be selected',
                )}
              </p>
            </div>

            <div className="flex justify-end gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() => setShowCustomNotificationModal(false)}
                data-testid="button-cancel-notification"
              >
                {t('admin.notifications.custom.cancel', 'Cancel')}
              </Button>
              <Button
                onClick={() => sendCustomNotificationMutation.mutate()}
                disabled={
                  !customSubject ||
                  !customMessage ||
                  (!sendEmail && !sendInApp) ||
                  sendCustomNotificationMutation.isPending ||
                  (recipientType === 'single' && !recipientUserId)
                }
                className="gap-2"
                data-testid="button-send-modal-notification"
              >
                <Bell className="h-4 w-4" />
                {sendCustomNotificationMutation.isPending
                  ? t('admin.notifications.custom.sending', 'Sending...')
                  : t(
                    'admin.notifications.custom.sendButton',
                    `Send to ${recipientType === 'all' ? 'All Customers' : 'Customer'}`,
                    {
                      recipient:
                        recipientType === 'all'
                          ? t('admin.notifications.custom.allCustomers', 'All Customers')
                          : t('admin.notifications.custom.singleCustomer', 'Customer'),
                    },
                  )}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

server/jobs/appleStoreIap.job.ts.content:
import fs from "fs";
import path from "path";
import { generateAppleJWT } from "../config/appleJwt";
import { appleApi } from "server/utils/appleApi";

export class AppleStoreIapJob {
    constructor(
        private sku: string,
        private title: string,
        private description: string,
        private price: number,
        private currency = "USD",
        private country = "USA"
    ) {
        this.sku = this.sku.toLowerCase().replace(/-/g, "_");
    }

    async handle() {
        const appId = process.env.IOS_APP_ID!;
        const bundleId = process.env.IOS_BUNDLE_ID!;
        const keyId = process.env.IOS_KEY_ID!;
        const issuerId = process.env.IOS_ISSUER_ID!;

        const jwt = generateAppleJWT({ keyId, issuerId, bundleId });
        const api = appleApi(jwt);

        const existing = await this.checkExistingIAP(api, appId);

        if (existing) {
            await this.updateIAP(api, appId, existing.id);
        } else {
            await this.createIAP(api, appId);
        }
    }

    // 1️⃣ Check existing
    private async checkExistingIAP(api: any, appId: string) {
        const res = await api.get(`/v2/apps/${appId}/inAppPurchasesV2`, {
            params: { "filter[productId]": this.sku },
        });

        return res.data.data?.[0] || null;
    }

    // 2️⃣ Create IAP
    private async createIAP(api: any, appId: string) {
        console.log("Creating IAP", this.sku);
        const res = await api.post("/v2/inAppPurchases", {
            data: {
                type: "inAppPurchases",
                attributes: {
                    productId: this.sku,
                    name: this.title,
                    inAppPurchaseType: "CONSUMABLE",
                    reviewNote: this.reviewNote(),
                },
                relationships: {
                    app: { data: { type: "apps", id: appId } },
                },
            },
        });

        const iapId = res.data.data.id;

        await this.setTerritories(api, iapId);
        const price = await this.setPricing(api, iapId);
        await this.upsertLocalization(api, iapId, price);
        await this.uploadScreenshot(api, iapId);

        return iapId;
    }

    // 3️⃣ Update IAP
    private async updateIAP(api: any, appId: string, iapId: string) {
        await api.patch(`/v2/inAppPurchases/${iapId}`, {
            data: {
                id: iapId,
                type: "inAppPurchases",
                attributes: {
                    name: this.title,
                    reviewNote: this.reviewNote(),
                },
            },
        });

        const price = await this.setPricing(api, iapId);
        await this.upsertLocalization(api, iapId, price);
        await this.setTerritories(api, iapId);
        await this.uploadScreenshot(api, iapId);
    }

    // 4️⃣ Pricing
    private async setPricing(api: any, iapId: string) {
        const pp = await api.get(
            `/v2/inAppPurchases/${iapId}/pricePoints`,
            { params: { "filter[territory]": this.country, limit: 800 } }
        );

        const pricePoint = this.findBestPricePoint(pp.data.data);
        if (!pricePoint) throw new Error("No price point found");

        const tempId = `tmp-${Date.now()}`;

        await api.post("/v2/inAppPurchasePriceSchedules", {
            data: {
                type: "inAppPurchasePriceSchedules",
                relationships: {
                    inAppPurchase: { data: { type: "inAppPurchases", id: iapId } },
                    baseTerritory: { data: { type: "territories", id: this.country } },
                    manualPrices: { data: [{ type: "inAppPurchasePrices", id: tempId }] },
                },
            },
            included: [
                {
                    type: "inAppPurchasePrices",
                    id: tempId,
                    attributes: { startDate: new Date().toISOString().slice(0, 10) },
                    relationships: {
                        inAppPurchasePricePoint: {
                            data: { type: "inAppPurchasePricePoints", id: pricePoint.id },
                        },
                        territory: {
                            data: { type: "territories", id: this.country },
                        },
                    },
                },
            ],
        });

        return pricePoint.attributes.customerPrice;
    }

    // 5️⃣ Localization
    private async upsertLocalization(api: any, iapId: string, price: string) {
        const res = await api.get(
            `/v2/inAppPurchases/${iapId}/inAppPurchaseLocalizations`
        );

        const existing = res.data.data?.[0];

        const payload = {
            data: {
                type: "inAppPurchaseLocalizations",
                attributes: {
                    name: `eSIM Pack (${this.currency} ${price})`,
                    description: `Buy eSIM / Top-Up ${this.currency} ${price}`,
                    locale: "en-US",
                },
                relationships: {
                    inAppPurchaseV2: {
                        data: { type: "inAppPurchases", id: iapId },
                    },
                },
            },
        };

        if (existing) {
            await api.patch(
                `/v2/inAppPurchaseLocalizations/${existing.id}`,
                { data: { ...payload.data, id: existing.id } }
            );
        } else {
            await api.post("/v2/inAppPurchaseLocalizations", payload);
        }
    }

    // 6️⃣ Territories
    private async setTerritories(api: any, iapId: string) {
        const t = await api.get("/v2/territories", { params: { limit: 200 } });

        await api.post("/v2/inAppPurchaseAvailabilities", {
            data: {
                type: "inAppPurchaseAvailabilities",
                attributes: { availableInNewTerritories: true },
                relationships: {
                    inAppPurchase: {
                        data: { type: "inAppPurchases", id: iapId },
                    },
                    availableTerritories: {
                        data: t.data.data.map((x: any) => ({
                            type: "territories",
                            id: x.id,
                        })),
                    },
                },
            },
        });
    }

    // 7️⃣ Screenshot
    private async uploadScreenshot(api: any, iapId: string) {
        const img = path.join(
            process.cwd(),
            "storage/review_screenshots",
            `${this.sku}.png`
        );

        if (!fs.existsSync(img)) return;

        const stat = fs.statSync(img);

        const reserve = await api.post(
            "/v2/inAppPurchaseAppStoreReviewScreenshots",
            {
                data: {
                    type: "inAppPurchaseAppStoreReviewScreenshots",
                    attributes: {
                        fileName: path.basename(img),
                        fileSize: stat.size,
                    },
                    relationships: {
                        inAppPurchaseV2: {
                            data: { type: "inAppPurchases", id: iapId },
                        },
                    },
                },
            }
        );

        const op = reserve.data.data.attributes.uploadOperations[0];

        await fetch(op.url, {
            method: "PUT",
            headers: { "Content-Type": "image/png" },
            body: fs.readFileSync(img),
        });

        await api.patch(
            `/v2/inAppPurchaseAppStoreReviewScreenshots/${reserve.data.data.id}`,
            { data: { id: reserve.data.data.id, type: "inAppPurchaseAppStoreReviewScreenshots", attributes: { uploaded: true } } }
        );
    }

    private findBestPricePoint(points: any[]) {
        return points
            .filter(p => Number(p.attributes.customerPrice) >= this.price)
            .sort(
                (a, b) =>
                    Number(a.attributes.customerPrice) -
                    Number(b.attributes.customerPrice)
            )[0];
    }

    private reviewNote() {
        return `Consumable eSIM purchase.\n\nTest:\n1. Open app\n2. Select package\n3. Purchase\n4. eSIM delivered`;
    }
}

server/services/sync/region-sync.ts.content:
"use strict";

/**
 * Region Sync Service
 * 
 * Extracts and syncs regions from provider API responses.
 * Regions are multi-country package groupings (e.g., "Europe", "Asia Pacific").
 */

import { db } from "../../db";
import { regions, unifiedPackages, providers } from "@shared/schema";
import { eq, sql, isNull, and } from "drizzle-orm";
import { storage } from "../../storage";
import { airaloAPI } from "../airalo/airalo-sdk";
import type { AiraloCountryData, AiraloOperator } from "../airalo/types";

interface RegionSyncResult {
  success: boolean;
  regionsCreated: number;
  regionsUpdated: number;
  errors: string[];
}

/**
 * Determine if an Airalo entry is a region (multi-country) vs a single country
 * Regions typically have:
 * - Empty or missing country_code
 * - Multiple coverages in their operators
 * - Slugs like "europe", "asia", "global", etc.
 */
function isRegionalEntry(entry: AiraloCountryData): boolean {
  // If no country_code, it's likely a region
  if (!entry.country_code || entry.country_code === '') {
    return true;
  }

  // Check if the slug matches common regional patterns
  const regionalSlugs = [
    'europe', 'asia', 'africa', 'americas', 'oceania', 'middle-east',
    'caribbean', 'global', 'world', 'latin-america', 'south-america',
    'north-america', 'central-america', 'southeast-asia', 'south-asia',
    'east-asia', 'west-africa', 'east-africa', 'central-africa',
    'southern-africa', 'north-africa', 'gulf', 'scandinavia', 'balkans',
    'european-union', 'apac', 'emea', 'latam'
  ];

  const slugLower = entry.slug.toLowerCase();
  if (regionalSlugs.some(r => slugLower.includes(r))) {
    return true;
  }

  // Check operators' coverages - if any operator covers multiple countries, it's regional
  for (const operator of entry.operators || []) {
    if (operator.coverages && operator.coverages.length > 1) {
      return true;
    }
  }

  return false;
}

/**
 * Extract coverage country codes from an Airalo operator
 */
function extractCoverageCodes(operators: AiraloOperator[]): string[] {
  const countryCodes = new Set<string>();

  for (const operator of operators || []) {
    for (const coverage of operator.coverages || []) {
      if (coverage.code) {
        countryCodes.add(coverage.code.toUpperCase());
      }
    }
  }

  return Array.from(countryCodes);
}

/**
 * Sync regions from Airalo dedicated regions endpoint
 */
export async function syncRegionsFromAiraloRegionsAPI(): Promise<RegionSyncResult> {
  console.log("🔄 Syncing regions from Airalo regions API...");
  const errors: string[] = [];
  let regionsCreated = 0;
  let regionsUpdated = 0;

  try {
    const response = await airaloAPI.getRegions();

    if (!response.data || !Array.isArray(response.data)) {
      console.log("  No regions data from Airalo regions API, trying packages fallback...");
      return syncRegionsFromAiraloPackages();
    }

    const regionsData = response.data as any[];
    const existingRegions = await storage.getAllRegions();
    const regionsBySlug = new Map(existingRegions.map(r => [r.slug, r]));

    console.log(`  Found ${regionsData.length} regions from Airalo regions API`);

    for (const region of regionsData) {
      if (!region.slug || !region.title) continue;

      const coverageCountries = region.countries?.map((c: any) => c.country_code?.toUpperCase()).filter(Boolean) || [];

      const existingRegion = regionsBySlug.get(region.slug);

      if (existingRegion) {
        await db
          .update(regions)
          .set({
            name: region.title,
            image: region.image?.url || existingRegion.image,
            airaloId: region.slug,
            countries: coverageCountries.length > 0 ? coverageCountries : existingRegion.countries,
            updatedAt: new Date(),
          })
          .where(eq(regions.id, existingRegion.id));
        regionsUpdated++;
      } else {
        await storage.createRegion({
          slug: region.slug,
          name: region.title,
          image: region.image?.url,
          airaloId: region.slug,
          countries: coverageCountries,
        });
        regionsCreated++;
      }
    }

    console.log(`✅ Airalo regions API sync complete: ${regionsCreated} created, ${regionsUpdated} updated`);

    return {
      success: true,
      regionsCreated,
      regionsUpdated,
      errors,
    };
  } catch (error: any) {
    console.error("❌ Airalo regions API sync failed:", error.message);
    errors.push(error.message);
    return {
      success: false,
      regionsCreated,
      regionsUpdated,
      errors,
    };
  }
}

/**
 * Sync regions from Airalo packages API (fallback)
 */
export async function syncRegionsFromAiraloPackages(): Promise<RegionSyncResult> {
  console.log("🔄 Syncing regions from Airalo packages API...");
  const errors: string[] = [];
  let regionsCreated = 0;
  let regionsUpdated = 0;

  try {
    const response = await airaloAPI.getPackages({ limit: 1000 });

    if (!response.data || !Array.isArray(response.data)) {
      return {
        success: false,
        regionsCreated: 0,
        regionsUpdated: 0,
        errors: ["No data received from Airalo API"],
      };
    }

    const entriesData = response.data as AiraloCountryData[];
    const existingRegions = await storage.getAllRegions();
    const regionsBySlug = new Map(existingRegions.map(r => [r.slug, r]));

    // Filter to only regional entries
    const regionalEntries = entriesData.filter(isRegionalEntry);
    console.log(`  Found ${regionalEntries.length} regional entries from Airalo`);

    for (const entry of regionalEntries) {
      const coverageCountries = extractCoverageCodes(entry.operators);

      const existingRegion = regionsBySlug.get(entry.slug);

      if (existingRegion) {
        // Update existing region
        await db
          .update(regions)
          .set({
            name: entry.title,
            image: entry.image?.url || existingRegion.image,
            airaloId: entry.slug,
            countries: coverageCountries,
            updatedAt: new Date(),
          })
          .where(eq(regions.id, existingRegion.id));
        regionsUpdated++;
      } else {
        // Create new region
        await storage.createRegion({
          slug: entry.slug,
          name: entry.title,
          image: entry.image?.url,
          airaloId: entry.slug,
          countries: coverageCountries,
        });
        regionsCreated++;
      }
    }

    console.log(`✅ Region sync complete: ${regionsCreated} created, ${regionsUpdated} updated`);

    return {
      success: true,
      regionsCreated,
      regionsUpdated,
      errors,
    };
  } catch (error: any) {
    console.error("❌ Region sync failed:", error.message);
    errors.push(error.message);
    return {
      success: false,
      regionsCreated,
      regionsUpdated,
      errors,
    };
  }
}

/**
 * Extract unique regions from existing unified packages
 * This is a fallback method when provider APIs don't expose region endpoints
 */
export async function syncRegionsFromUnifiedPackages(): Promise<RegionSyncResult> {
  console.log("🔄 Syncing regions from unified packages...");
  const errors: string[] = [];
  let regionsCreated = 0;
  let regionsUpdated = 0;

  try {
    // Get all regional packages that have type='regional' but no regionId
    const regionalPackages = await db.query.unifiedPackages.findMany({
      where: (up, { eq }) => eq(up.type, 'regional'),
    });

    console.log(`  Found ${regionalPackages.length} regional packages`);

    // Group packages by their countryName (which for regional packages is the region name)
    const regionMap = new Map<string, {
      name: string;
      slug: string;
      coverage: string[];
    }>();

    for (const pkg of regionalPackages) {
      if (!pkg.countryName) continue;

      const regionSlug = pkg.slug?.split('-')[0] || pkg.countryName.toLowerCase().replace(/\s+/g, '-');

      if (!regionMap.has(regionSlug)) {
        regionMap.set(regionSlug, {
          name: pkg.countryName,
          slug: regionSlug,
          coverage: [],
        });
      }

      // Add coverage countries
      const regionData = regionMap.get(regionSlug)!;
      if (pkg.coverage && Array.isArray(pkg.coverage)) {
        for (const code of pkg.coverage) {
          if (!regionData.coverage.includes(code)) {
            regionData.coverage.push(code);
          }
        }
      }
    }

    console.log(`  Extracted ${regionMap.size} unique regions`);

    const existingRegions = await storage.getAllRegions();
    const regionsBySlug = new Map(existingRegions.map(r => [r.slug, r]));

    for (const [slug, data] of Array.from(regionMap.entries())) {
      const existingRegion = regionsBySlug.get(slug);

      if (existingRegion) {
        // Update existing region with coverage
        await db
          .update(regions)
          .set({
            countries: data.coverage,
            updatedAt: new Date(),
          })
          .where(eq(regions.id, existingRegion.id));
        regionsUpdated++;
      } else {
        // Create new region
        await storage.createRegion({
          slug: data.slug,
          name: data.name,
          countries: data.coverage,
        });
        regionsCreated++;
      }
    }

    console.log(`✅ Region sync from packages complete: ${regionsCreated} created, ${regionsUpdated} updated`);

    return {
      success: true,
      regionsCreated,
      regionsUpdated,
      errors,
    };
  } catch (error: any) {
    console.error("❌ Region sync from packages failed:", error.message);
    errors.push(error.message);
    return {
      success: false,
      regionsCreated,
      regionsUpdated,
      errors,
    };
  }
}

/**
 * Update regional packages with correct regionId references
 */
export async function linkPackagesToRegions(): Promise<{ success: boolean; packagesLinked: number }> {
  console.log("🔗 Linking regional packages to regions...");

  try {
    const allRegions = await storage.getAllRegions();
    const regionsBySlug = new Map(allRegions.map(r => [r.slug, r]));
    const regionsByName = new Map(allRegions.map(r => [r.name.toLowerCase(), r]));

    // Get regional packages without regionId
    const unlinkedPackages = await db.query.unifiedPackages.findMany({
      where: (up, { eq, isNull, and }) => and(
        eq(up.type, 'regional'),
        isNull(up.regionId)
      ),
    });

    console.log(`  Found ${unlinkedPackages.length} unlinked regional packages`);

    let packagesLinked = 0;

    for (const pkg of unlinkedPackages) {
      let region = null;

      // Try to match by countryName (which is the region name for regional packages)
      if (pkg.countryName) {
        region = regionsByName.get(pkg.countryName.toLowerCase());
      }

      // Try to match by slug prefix
      if (!region && pkg.slug) {
        const slugParts = pkg.slug.split('-');
        for (let i = 1; i <= slugParts.length; i++) {
          const potentialSlug = slugParts.slice(0, i).join('-');
          region = regionsBySlug.get(potentialSlug);
          if (region) break;
        }
      }

      if (region) {
        await db
          .update(unifiedPackages)
          .set({
            regionId: region.id,
            updatedAt: new Date(),
          })
          .where(eq(unifiedPackages.id, pkg.id));
        packagesLinked++;
      }
    }

    console.log(`✅ Linked ${packagesLinked} packages to regions`);

    return {
      success: true,
      packagesLinked,
    };
  } catch (error: any) {
    console.error("❌ Failed to link packages to regions:", error.message);
    return {
      success: false,
      packagesLinked: 0,
    };
  }
}

/**
 * Run full region sync pipeline
 */
export async function runFullRegionSync(): Promise<{
  success: boolean;
  regionsCreated: number;
  regionsUpdated: number;
  packagesLinked: number;
  errors: string[];
}> {
  console.log("🔄 Running full region sync pipeline...");
  const errors: string[] = [];

  // Step 1: Try to sync from Airalo regions API
  // const airaloResult = await syncRegionsFromAiraloRegionsAPI();
  // if (!airaloResult.success) {
  //   errors.push(...airaloResult.errors);
  // }

  // Step 2: Also try from Airalo packages for additional regions
  const airaloPackagesResult = await syncRegionsFromAiraloPackages();
  if (!airaloPackagesResult.success) {
    errors.push(...airaloPackagesResult.errors);
  }

  // Step 3: Fallback - extract regions from existing unified packages
  const packageResult = await syncRegionsFromUnifiedPackages();
  if (!packageResult.success) {
    errors.push(...packageResult.errors);
  }

  // Step 4: Link packages to regions
  const linkResult = await linkPackagesToRegions();

  const totalCreated = airaloPackagesResult.regionsCreated + packageResult.regionsCreated;
  const totalUpdated = airaloPackagesResult.regionsUpdated + packageResult.regionsUpdated;

  console.log(`✅ Full region sync complete: ${totalCreated} created, ${totalUpdated} updated, ${linkResult.packagesLinked} packages linked`);

  return {
    success: errors.length === 0,
    regionsCreated: totalCreated,
    regionsUpdated: totalUpdated,
    packagesLinked: linkResult.packagesLinked,
    errors,
  };
}

export const regionSyncService = {
  // syncFromAiralo: syncRegionsFromAiraloRegionsAPI, // Backwards compatible alias
  syncFromAiraloRegionsAPI: syncRegionsFromAiraloRegionsAPI,
  syncFromAiraloPackages: syncRegionsFromAiraloPackages,
  syncFromPackages: syncRegionsFromUnifiedPackages,
  linkPackages: linkPackagesToRegions,
  runFullSync: runFullRegionSync,
};

