              <h4 className="text-2xl font-bold text-slate-900 dark:text-white mt-2">100%</h4>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-2">{t('admin.analytics.allPackagesAvailable', 'All packages available')}</p>
            </div>
          </div>
        </div>
      </Card>
    </div>
  );
}

