import { Bell } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useQuery } from '@tanstack/react-query';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { formatDistanceToNow } from 'date-fns';
import { Link } from 'wouter';
import { useToast } from '@/hooks/use-toast';
import { JSXElementConstructor, Key, ReactElement, ReactNode, ReactPortal, useState } from 'react';

interface Notification {
  id: string;
  userId: string;
  type: string;
  title: string;
  message: string;
  read: boolean;
  metadata: Record<string, any> | null;
  createdAt: string;
}

export function NotificationBell() {
  const { toast } = useToast();
  const [open, setOpen] = useState(false);

  // Fetch notifications with auto-refresh every 30 seconds
  const { data, isLoading } = useQuery<{
    notifications: Notification[];
    unreadCount: number;
  }>({
    queryKey: ['/api/notifications'],
    refetchInterval: 30000, // 30 seconds
  });

  const notifications = data?.notifications || [];
  const unreadCount = notifications?.filter((n: { read: any }) => !n.read).length || 0;

  // Get recent 5 notifications
  const recentNotifications = notifications.slice(0, 5);

  const handleMarkAsRead = async (notificationId: string) => {
    try {
      await apiRequest('PATCH', `/api/notifications/${notificationId}/read`, {});
      await queryClient.invalidateQueries({ queryKey: ['/api/notifications'] });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to mark notification as read',
        variant: 'destructive',
      });
    }
  };

  const handleMarkAllAsRead = async () => {
    try {
      await apiRequest('PATCH', '/api/notifications/read-all', {});
      await queryClient.invalidateQueries({ queryKey: ['/api/notifications'] });
      toast({
        title: 'Success',
        description: 'All notifications marked as read',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to mark all notifications as read',
        variant: 'destructive',
      });
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="icon" className="relative" data-testid="button-notifications">
          <Bell className="h-5 w-5 text-foreground" />
          {unreadCount > 0 && (
            <span
              className="
              absolute 
              -top-1 
              -right-1
              h-4 
              min-w-4 
              px-1 
              text-[10px] 
              flex 
              items-center 
              justify-center 
              rounded-full 
              bg-destructive 
              text-white 
              font-medium
            "
              data-testid="badge-unread-count"
            >
              {unreadCount}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-80 p-0" align="end" data-testid="popover-notifications">
        <div className="flex items-center justify-between p-4 border-b">
          <h3 className="font-semibold text-base" data-testid="text-notifications-title">
            Notifications
          </h3>
          {unreadCount > 0 && (
            <Button
              variant="ghost"
              size="sm"
              onClick={handleMarkAllAsRead}
              data-testid="button-mark-all-read"
            >
              Mark all as read
            </Button>
          )}
        </div>

        <ScrollArea className="h-[400px]">
          {isLoading ? (
            <div className="p-4 text-center text-sm text-muted-foreground">
              Loading notifications...
            </div>
          ) : recentNotifications.length === 0 ? (
            <div className="p-8 text-center">
              <Bell className="h-12 w-12 mx-auto mb-3 text-muted-foreground" />
              <p className="text-sm text-muted-foreground" data-testid="text-no-notifications">
                No notifications yet
              </p>
            </div>
          ) : (
            <div className="divide-y">
              {recentNotifications.map(
                (notification: {
                  id: Key | null | undefined;
                  read: any;
                  title:
                    | string
                    | number
                    | boolean
                    | ReactElement<any, string | JSXElementConstructor<any>>
                    | Iterable<ReactNode>
                    | ReactPortal
                    | null
                    | undefined;
                  message:
                    | string
                    | number
                    | boolean
                    | ReactElement<any, string | JSXElementConstructor<any>>
                    | Iterable<ReactNode>
                    | ReactPortal
                    | null
                    | undefined;
                  createdAt: string | number | Date;
                }) => (
                  <div
                    key={notification.id}
                    className={`p-4 hover-elevate cursor-pointer transition-colors ${
                      !notification.read ? 'bg-muted/50' : ''
                    }`}
                    onClick={() => {
                      if (!notification.read) {
                        handleMarkAsRead(notification.id);
                      }
                    }}
                    data-testid={`notification-item-${notification.id}`}
                  >
                    <div className="flex items-start justify-between gap-2 mb-1">
                      <h4
                        className={`text-sm font-medium ${
                          !notification.read ? 'font-semibold' : ''
                        }`}
                        data-testid={`notification-title-${notification.id}`}
                      >
                        {notification.title}
                      </h4>
                      {!notification.read && (
                        <div
                          className="h-2 w-2 rounded-full bg-primary flex-shrink-0 mt-1"
                          data-testid={`notification-unread-indicator-${notification.id}`}
                        />
                      )}
                    </div>
                    <p
                      className="text-sm text-muted-foreground mb-2 line-clamp-2"
                      data-testid={`notification-message-${notification.id}`}
                    >
                      {notification.message}
                    </p>
                    <p
                      className="text-xs text-muted-foreground"
                      data-testid={`notification-time-${notification.id}`}
                    >
                      {formatDistanceToNow(new Date(notification.createdAt), {
                        addSuffix: true,
                      })}
                    </p>
                  </div>
                ),
              )}
            </div>
          )}
        </ScrollArea>

        {recentNotifications.length > 0 && (
          <div className="p-3 border-t">
            <Link href="/notifications">
              <Button
                variant="ghost"
                className="w-full"
                onClick={() => setOpen(false)}
                data-testid="button-view-all-notifications"
              >
                View all notifications
              </Button>
            </Link>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

client/src/components/modals/SearchModal.content:
"use client";

import { useState } from "react";
import { Link, useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import { Search, Globe, ChevronRight, Check, Sparkles } from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useCurrency } from "@/contexts/CurrencyContext";

// Types
interface DestinationWithPricing {
  id: number;
  name: string;
  slug: string;
  countryCode: string;
  minPrice: string;
  packageCount?: number;
  isPopular?: boolean;
}

interface RegionWithPricing {
  id: number;
  name: string;
  slug: string;
  minPrice: string;
  packageCount?: number;
  countries?: string[];
}

interface SearchModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function SearchModalHero({ open, onOpenChange }: SearchModalProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [searchType, setSearchType] = useState<"country" | "region">("country");
  const [, setLocation] = useLocation();
  const { currency } = useCurrency();

  const { data: destinationsWithPricing, isLoading: destinationsLoading } =
    useQuery<DestinationWithPricing[]>({
      queryKey: ["/api/destinations/with-pricing", { currency }],
    });

  const { data: regionsWithPricing, isLoading: regionsLoading } = useQuery<
    RegionWithPricing[]
  >({
    queryKey: ["/api/regions/with-pricing", { currency }],
  });

  const popularDestinations =
    destinationsWithPricing?.filter((d) => d.isPopular).slice(0, 6) || [];

  const defaultPopularDestinations = [
    { name: "United States", countryCode: "us", slug: "united-states" },
    { name: "United Kingdom", countryCode: "gb", slug: "united-kingdom" },
    { name: "UAE", countryCode: "ae", slug: "united-arab-emirates" },
    { name: "Japan", countryCode: "jp", slug: "japan" },
    { name: "Thailand", countryCode: "th", slug: "thailand" },
    { name: "France", countryCode: "fr", slug: "france" },
  ];

  const displayPopular =
    popularDestinations.length > 0
      ? popularDestinations.map((d) => ({
          name: d.name,
          countryCode: d.countryCode,
          slug: d.slug,
          minPrice: d.minPrice,
        }))
      : defaultPopularDestinations.map((d) => ({
          ...d,
          minPrice: "0",
        }));

  const defaultPopularRegions = [
    { id: 1, name: "Europe", slug: "europe", minPrice: "0" },
    { id: 2, name: "Asia", slug: "asia", minPrice: "0" },
    { id: 3, name: "Americas", slug: "americas", minPrice: "0" },
  ];

  const displayPopularRegions =
    regionsWithPricing && regionsWithPricing.length > 0
      ? regionsWithPricing.slice(0, 3)
      : defaultPopularRegions;

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      setLocation(`/search?q=${encodeURIComponent(searchQuery)}`);
      onOpenChange(false);
    }
  };

  const getFilteredResults = () => {
    if (searchQuery.length === 0) return [];

    if (searchType === "country") {
      return (
        destinationsWithPricing?.filter(
          (d) =>
            d.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            d.countryCode.toLowerCase().includes(searchQuery.toLowerCase())
        ) || []
      ).slice(0, 10);
    } else {
      return (
        regionsWithPricing?.filter((r) =>
          r.name.toLowerCase().includes(searchQuery.toLowerCase())
        ) || []
      ).slice(0, 10);
    }
  };

  // Get all countries for listing
  const getAllCountries = () => {
    return destinationsWithPricing || [];
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[480px] max-h-[90vh] overflow-hidden p-0 gap-0">
        <div className="relative">
          {/* Header */}
          <DialogHeader className="px-6 pt-6 pb-4 border-b">
            <DialogTitle className="text-xl font-bold flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-primary" />
              Search Destinations
            </DialogTitle>
            <DialogDescription className="text-sm">
              200+ countries & regions available
            </DialogDescription>
          </DialogHeader>

          {/* Content */}
          <div className="max-h-[calc(90vh-120px)] overflow-y-auto custom-scrollbar">
            <div className="p-6 space-y-5">
              {/* Toggle Buttons */}
              <div className="flex gap-2 p-1 bg-muted/50 rounded-full w-fit mx-auto">
                <button
                  onClick={() => {
                    setSearchType("country");
                    setSearchQuery("");
                  }}
                  className={`flex items-center gap-2 text-xs font-medium transition-all px-4 py-2 rounded-full ${
                    searchType === "country"
                      ? "bg-primary text-primary-foreground shadow-md"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  <div
                    className={`w-3.5 h-3.5 rounded-full border-2 flex items-center justify-center ${
                      searchType === "country"
                        ? "border-primary-foreground bg-primary-foreground"
                        : "border-muted-foreground"
                    }`}
                  >
                    {searchType === "country" && (
                      <Check className="h-2 w-2 text-primary" />
                    )}
                  </div>
                  Countries
                </button>
                <button
                  onClick={() => {
                    setSearchType("region");
                    setSearchQuery("");
                  }}
                  className={`flex items-center gap-2 text-xs font-medium transition-all px-4 py-2 rounded-full ${
                    searchType === "region"
                      ? "bg-primary text-primary-foreground shadow-md"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  <div
                    className={`w-3.5 h-3.5 rounded-full border-2 flex items-center justify-center ${
                      searchType === "region"
                        ? "border-primary-foreground bg-primary-foreground"
                        : "border-muted-foreground"
                    }`}
                  >
                    {searchType === "region" && (
                      <Check className="h-2 w-2 text-primary" />
                    )}
                  </div>
                  Regions
                </button>
              </div>

              {/* Search Input */}
              <form onSubmit={handleSearch}>
                <div className="relative group">
                  <div className="absolute -inset-0.5 bg-gradient-to-r from-primary/20 to-primary/10 rounded-2xl blur opacity-40 group-hover:opacity-60 transition-opacity"></div>
                  <div className="relative">
                    <Input
                      type="text"
                      placeholder={
                        searchType === "country"
                          ? "Search countries..."
                          : "Search regions..."
                      }
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
