server/services/esim-go/orders.ts.content:
"use strict";

import { makeEsimGoRequest, formatDataAmount } from "./api";
import type {
  ProviderOrderRequest,
  ProviderOrderResponse,
  ProviderOrderStatus,
  ProviderUsageData,
  ProviderTopupPackage,
  ProviderTopupRequest,
  ProviderTopupResponse,
  ProviderRefundRequest,
  ProviderRefundResponse,
  ProviderCancelRequest,
  ProviderCancelResponse,
} from "../../providers/provider-interface";
import type {
  EsimGoOrderResponse,
  EsimGoOrderDetailsResponse,
  EsimGoEsimResponse,
  EsimGoBundleResponse,
  EsimGoTopupResponse,
} from "./types";

export async function createEsimGoOrder(
  request: ProviderOrderRequest,
  apiKey: string
): Promise<ProviderOrderResponse> {
  try {
    console.log('Creating eSIM Go order with request:', request);
    const response = await makeEsimGoRequest<EsimGoOrderResponse>(
      '/orders',
      'POST',
      {
        type: 'transaction',
        assign: false,
        order: [
          {
            type: "bundle",
            item: request.packageId,
            quantity: request.quantity || 1,
            allowReassign: true,
            iccids: [''],
          }
        ],
      },
      apiKey
    );

    console.log('EsimGo create order response:', response);

    if (response.iccids && response.iccids.length > 0) {
      const esim = response.iccids[0];
      const qrCode = `LPA:1$${esim.smdpAddress}$${esim.matchingId}`;

      return {
        success: true,
        providerOrderId: response.reference,
        requestId: response.reference,
        status: 'completed',
        iccid: esim.iccid,
        qrCode,
        smdpAddress: esim.smdpAddress,
        activationCode: esim.matchingId,
      };
    }

    return {
      success: true,
      providerOrderId: response.reference,
      requestId: response.reference,
      status: 'processing',
      processingTime: 10,
    };
  } catch (error) {
    return {
      success: false,
      status: 'failed',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

export async function getEsimGoOrderStatus(
  providerOrderId: string,
  apiKey: string
): Promise<ProviderOrderStatus> {
  try {
    const response = await makeEsimGoRequest<EsimGoOrderDetailsResponse>(
      `/orders/${providerOrderId}`,
      'GET',
      undefined,
      apiKey
    );

    const order = response.order;
    const status = order.status === 'completed' ? 'completed' :
      order.status === 'processing' || order.status === 'pending' ? 'processing' :
        order.status === 'failed' ? 'failed' : 'pending';

    const esim = order.esims[0];

    return {
      providerOrderId: order.id,
      status,
      iccid: esim?.iccid,
      qrCode: esim?.qr_code,
      smdpAddress: esim?.sm_dp_address,
      activationCode: esim?.activation_code,
    };
  } catch (error) {
    return {
      providerOrderId,
      status: 'failed',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

export async function getEsimGoUsageData(
  iccid: string,
  apiKey: string
): Promise<ProviderUsageData> {
  try {
    const response = await makeEsimGoRequest<EsimGoEsimResponse>(
      `/esims/${iccid}`,
      'GET',
      undefined,
      apiKey
    );

    const esim = response.esim;
    const percentageUsed = esim.data.limit_in_bytes > 0
      ? (esim.data.used_in_bytes / esim.data.limit_in_bytes) * 100
      : 0;

    return {
      iccid: esim.iccid,
      dataUsed: esim.data.used_in_bytes,
      dataTotal: esim.data.limit_in_bytes,
      dataRemaining: esim.data.remaining_in_bytes,
      percentageUsed: Math.round(percentageUsed * 100) / 100,
      expiresAt: new Date(esim.validity.expires_at),
      status: esim.status === 'active' ? 'active' : 'inactive',
    };
  } catch (error) {
    throw new Error(`Failed to get usage data: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

export async function getEsimGoTopupPackages(
  iccidOrPackageId: string,
  apiKey: string
): Promise<ProviderTopupPackage[]> {
  try {
    if (iccidOrPackageId.length > 15) {
      const response = await makeEsimGoRequest<EsimGoEsimResponse>(
        `/esims/${iccidOrPackageId}`,
        'GET',
        undefined,
        apiKey
      );

      if (response.esim.supported_topups) {
        return response.esim.supported_topups.map(topup => ({
          providerPackageId: topup.bundle_id,
          title: topup.name,
          dataAmount: formatDataAmount(topup.data_limit_in_bytes),
          validity: topup.validity.duration_in_days,
          wholesalePrice: topup.price.amount / 100,
          currency: topup.price.currency_code,
        }));
      }
      return [];
    } else {
      const response = await makeEsimGoRequest<EsimGoBundleResponse>(
        `/bundles/${iccidOrPackageId}`,
        'GET',
        undefined,
        apiKey
      );

      const topupPackages: ProviderTopupPackage[] = [];
      for (const topupId of response.bundle.supported_topups) {
        const topupBundle = await makeEsimGoRequest<EsimGoBundleResponse>(
          `/bundles/${topupId}`,
          'GET',
          undefined,
          apiKey
        );

        topupPackages.push({
          providerPackageId: topupBundle.bundle.id,
          title: topupBundle.bundle.name,
          dataAmount: formatDataAmount(topupBundle.bundle.data_limit_in_bytes),
          validity: topupBundle.bundle.validity.duration_in_days,
          wholesalePrice: topupBundle.bundle.price.amount / 100,
          currency: topupBundle.bundle.price.currency_code,
        });
      }

      return topupPackages;
    }
  } catch (error) {
    return [];
  }
}

export async function purchaseEsimGoTopup(
  request: ProviderTopupRequest,
  apiKey: string
): Promise<ProviderTopupResponse> {
  try {
    const response = await makeEsimGoRequest<EsimGoTopupResponse>(
      '/topups',
      'POST',
      {
        iccid: request.iccid,
        bundle_id: request.packageId,
      },
      apiKey
    );

    return {
      success: true,
      providerTopupId: response.topup.id,
      requestId: response.topup.id,
      status: response.topup.status === 'completed' ? 'completed' : 'processing',
    };
  } catch (error) {
    return {
      success: false,
      status: 'failed',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

export async function requestEsimGoRefund(
  request: ProviderRefundRequest,
  apiKey: string
): Promise<ProviderRefundResponse> {
  try {
    const esimResponse = await makeEsimGoRequest<EsimGoEsimResponse>(
      `/esims/${request.iccid}`,
      'GET',
      undefined,
      apiKey
    );

    const usageId = esimResponse.esim.current_usage?.id;
    if (!usageId) {
      return {
        success: false,
        approved: false,
        status: "rejected",
        errorMessage: "No active usage found for this eSIM - cannot refund",
      };
    }

    if (esimResponse.esim.status === 'active' && esimResponse.esim.data?.used_in_bytes > 0) {
      return {
        success: false,
        approved: false,
        status: "rejected",
        errorMessage: "eSIM has been activated and used - cannot refund",
      };
    }

    const SIXTY_DAYS_MS = 60 * 24 * 60 * 60 * 1000;
    const orderCreatedAt = request.orderCreatedAt ? new Date(request.orderCreatedAt) : null;
    if (orderCreatedAt) {
      const daysSinceOrder = Date.now() - orderCreatedAt.getTime();
      if (daysSinceOrder > SIXTY_DAYS_MS) {
        return {
          success: false,
          approved: false,
          status: "rejected",
          errorMessage: "Refund window expired - eSIM Go only allows refunds within 60 days of purchase",
        };
      }
    }

    const response = await makeEsimGoRequest<{ success: boolean; message?: string }>(
      '/inventory/refund',
      'POST',
      {
        usageId: usageId,
        quantity: 1,
      },
      apiKey
    );

    return {
      success: true,
      approved: true,
      status: "approved",
      message: response.message || "Refund processed successfully",
    };
  } catch (error) {
    return {
      success: false,
      approved: false,
      status: "rejected",
      errorMessage: error instanceof Error ? error.message : "Refund request failed",
    };
  }
}

export async function cancelEsimGoOrder(
  request: ProviderCancelRequest,
  apiKey: string
): Promise<ProviderCancelResponse> {
  return {
    success: false,
    status: "not_supported",
    errorMessage: "eSIM Go does not support order cancellation - use refund instead",
  };
}

server/routes/customer.ts.content:
"use strict";

import { Router, type Request, type Response } from "express";
import multer from "multer";
import path from "path";
import fs from "fs";
import { storage } from "../storage";
import { asyncHandler } from "../lib/asyncHandler";
import { ValidationError, NotFoundError } from "../lib/errors";
import { requireAuth } from "../lib/middleware";
import { profileImageUpload } from "../middleware/image-upload";
import { logger } from "../lib/logger";
import * as ApiResponse from "../utils/response";

const router = Router();

const uploadDir = path.join(process.cwd(), "uploads", "kyc");
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const upload = multer({
  storage: multer.diskStorage({
    destination: uploadDir,
    filename: (req, file, cb) => {
      const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
      cb(null, uniqueSuffix + path.extname(file.originalname));
    },
  }),
  limits: { fileSize: 10 * 1024 * 1024 },
});




router.post(
  "/kyc/upload",
  requireAuth,
  upload.single("document"),
  asyncHandler(async (req: Request, res: Response) => {
    if (!req.file) {
      throw new ValidationError("No file uploaded", "document");
    }

    const { documentType } = req.body;
    if (!documentType) {
      throw new ValidationError("Document type is required", "documentType");
    }

    // 👇 Use req.userId instead of req.session.userId
    const userId = req.userId!;

    console.log("Uploading KYC document for userId:", userId, req);

    const document = await storage.createKycDocument({
      userId,
      documentType,
      filePath: req.file.path,
      fileName: req.file.originalname,
      fileSize: req.file.size,
      mimeType: req.file.mimetype,
      status: "pending",
    });

    await storage.updateUser(userId, { kycStatus: "submitted" });

    // logger.info("KYC document uploaded", {
    //   userId,
    //   documentType,
    // });

    return ApiResponse.created(res, "KYC document uploaded successfully", { document });
  })
);



router.get(
  "/kyc/documents",
  requireAuth,
  asyncHandler(async (req: Request, res: Response) => {
    const documents = await storage.getKycDocumentsByUser(req.session.userId!);
    return ApiResponse.success(res, "KYC documents fetched successfully", documents);
  })
);

router.get("/profile", requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = req.userId!;
    const user = await storage.getUser(userId);
    if (!user) {
      return ApiResponse.notFound(res, "User not found");
    }
    return ApiResponse.success(res, "Profile fetched successfully", user);
  } catch (error: any) {
    return ApiResponse.serverError(res, error.message);
  }
});


router.put(
  "/profile",
  requireAuth,
  profileImageUpload.single("profileImage"),
  async (req: Request, res: Response) => {
    try {
      const { name, phone, address, currency, destination } = req.body;
      const userId = req.userId!;

      const updateData: any = {
        name,
        phone,
        address,
        currency,
        destination,
      };

      // 👇 profile image aaye to update karo
      if (req.file) {
        const user = await storage.getUser(userId);

        // 🔥 old image delete
        if (user?.imagePath && fs.existsSync(user.imagePath)) {
          fs.unlinkSync(user.imagePath);
        }

        // ✅ DB field = imagePath
        updateData.imagePath = `uploads/profiles/${req.file.filename}`;
      }

      const updatedUser = await storage.updateUser(userId, updateData);

      const { logActivity, ActivityActions } = await import("../middleware/activity-logger");
      await logActivity(
        req,
        ActivityActions.PROFILE_UPDATED,
        "user",
        userId,
        { profileImageUpdated: !!req.file }
      );

      return ApiResponse.success(res, "Profile updated successfully", updatedUser);
    } catch (error: any) {
      return ApiResponse.serverError(res, error.message);
    }
  }
);



router.patch("/notification-preferences", requireAuth, async (req: Request, res: Response) => {
  try {
    const { notifyLowData, notifyExpiring } = req.body;

    if (typeof notifyLowData !== 'boolean' && typeof notifyExpiring !== 'boolean') {
      return ApiResponse.badRequest(res, "At least one notification preference must be provided");
    }

    const updateData: any = {};
    if (typeof notifyLowData === 'boolean') {
      updateData.notifyLowData = notifyLowData;
    }
    if (typeof notifyExpiring === 'boolean') {
      updateData.notifyExpiring = notifyExpiring;
    }

    const user = await storage.updateUser(req.session.userId!, updateData);

    const { logActivity, ActivityActions } = await import("../middleware/activity-logger");
    await logActivity(req, ActivityActions.PROFILE_UPDATED, 'user', req.session.userId!, {
      notificationPreferences: updateData
    });

    return ApiResponse.success(res, "Notification preferences updated successfully", user);
  } catch (error: any) {
    return ApiResponse.serverError(res, error.message);
  }
});

router.get("/orders", requireAuth, async (req: Request, res: Response) => {
  try {
    const orders = await storage.getOrdersByUser(req.session.userId!);
    return ApiResponse.success(res, "Orders fetched successfully", orders);
  } catch (error: any) {
    return ApiResponse.serverError(res, error.message);
  }
});


router.get("/my-esims-usages", requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = req.userId;
    if (!userId) {
      return ApiResponse.unauthorized(res, "Unauthorized");
    }

    // 1. Get all active eSIM orders for user
    const orders = await storage.getOrdersByStatus(userId, "completed");

    if (!orders || orders.length === 0) {
      return ApiResponse.notFound(res, "No eSIMs found");
    }

    const { providerFactory } = await import("../providers/provider-factory");

    // 2. Fetch usage for each eSIM
    const usageResults = await Promise.all(
      orders.map(async (order) => {
        try {
          if (!order.iccid) {
            return {
              orderId: order.id,
              iccid: null,
              status: "no_iccid",
            };
          }

          const providerService = await providerFactory.getServiceById(order.providerId);
          const usage = await providerService.getUsageData(order.iccid);

          return {
            orderId: order.id,
            iccid: order.iccid,
            providerId: order.providerId,
            usage,
          };
        } catch (err: any) {
          return {
            orderId: order.id,
            iccid: order.iccid,
            providerId: order.providerId,
            error: err.message,
          };
        }
      })
    );

    return ApiResponse.success(
      res,
      "eSIM usage fetched successfully",
      usageResults
    );
  } catch (error: any) {
    console.error("Error fetching eSIM usages:", error);
    return ApiResponse.serverError(res, error.message);
  }
});


router.get("/topups", requireAuth, async (req: Request, res: Response) => {
  try {
    const topups = await storage.getTopupsByUser(req.session.userId!);
    return ApiResponse.success(res, "Topups fetched successfully", topups);
  } catch (error: any) {
    return ApiResponse.serverError(res, error.message);
  }
});

router.get("/activity", requireAuth, async (req: Request, res: Response) => {
  try {
    const logs = await storage.getActivityLogsByUser(req.session.userId!);
    return ApiResponse.success(res, "Activity logs fetched successfully", logs);
  } catch (error: any) {
    return ApiResponse.serverError(res, error.message);
  }
});

router.get("/esims", requireAuth, async (req: Request, res: Response) => {
  try {
    if (!req.session.userId) {
      return ApiResponse.unauthorized(res, "Unauthorized");
    }

    const orders = await storage.getOrdersByUser(req.session.userId);
    const esims = orders.filter(order => order.iccid && order.status === "completed");

    return ApiResponse.success(res, "eSIMs fetched successfully", esims);
  } catch (error: any) {
    console.error("Error fetching customer eSIMs:", error);
    return ApiResponse.serverError(res, error.message);
  }
});

export default router;

