import axios from "axios";

export const appleApi = (jwt: string) => {
    const api = axios.create({
        baseURL: "https://api.appstoreconnect.apple.com",
        headers: {
            Authorization: `Bearer ${jwt}`,
            "Content-Type": "application/json",
        },
    });

    // 🔍 Request logger
    api.interceptors.request.use(req => {
        console.log("🍎 APPLE REQUEST");
        console.log("➡️", req.method?.toUpperCase(), req.url);
        console.log("📤", JSON.stringify(req.data, null, 2));
        return req;
    });

    // 🔥 Response + error logger
    api.interceptors.response.use(
        res => {
            console.log("✅ APPLE RESPONSE", res.status);
            console.log("📥", JSON.stringify(res.data, null, 2));
            return res;
        },
        err => {
            console.error("❌ APPLE ERROR");
            console.error("Status:", err.response?.status);
            console.error(
                "Body:",
                JSON.stringify(err.response?.data, null, 2)
            );
            throw err;
        }
    );

    return api;
};

server/services/packages/composite-score.content:
/**
 * Composite Scoring System
 * 
 * Combines multiple scoring factors:
 * - Price score (normalized 0-100)
 * - AI quality score
 * - Provider reliability score
 * - Coverage score
 * 
 * Configurable weights stored in platform_settings
 */

import { db } from "../../db";
import { platformSettings, providers } from "@shared/schema";
import { eq } from "drizzle-orm";
import { packageAnalyzer, type PackageData } from "../ai/package-analyzer";

export interface ScoringWeights {
  priceWeight: number;
  qualityWeight: number;
  providerWeight: number;
}

export interface CompositeScore {
  packageId: string;
  finalScore: number;
  priceScore: number;
  qualityScore: number;
  providerScore: number;
  weights: ScoringWeights;
  breakdown: {
    priceContribution: number;
    qualityContribution: number;
    providerContribution: number;
  };
  reasoning?: string;
  aiEnhanced: boolean;
}

export interface PackageWithScore extends PackageData {
  compositeScore: CompositeScore;
}

const DEFAULT_WEIGHTS: ScoringWeights = {
  priceWeight: 50,
  qualityWeight: 30,
  providerWeight: 20,
};

const PROVIDER_SCORES: Record<string, number> = {
  airalo: 90,
  "esim-access": 85,
  "esim-go": 82,
  maya: 78,
};

export class CompositeScorer {
  private weightsCache: ScoringWeights | null = null;
  private weightsCacheExpiry: Date | null = null;
  private providerScores: Map<string, number> = new Map();

  /**
   * Get scoring weights from platform settings
   */
  async getWeights(): Promise<ScoringWeights> {
    if (this.weightsCache && this.weightsCacheExpiry && new Date() < this.weightsCacheExpiry) {
      return this.weightsCache;
    }

    try {
      const settings = await db.query.platformSettings.findMany({
        where: (ps, { inArray }) => inArray(ps.key, [
          "ai_price_weight",
          "ai_quality_weight", 
          "ai_provider_weight"
        ]),
      });

      const weights: ScoringWeights = { ...DEFAULT_WEIGHTS };

      for (const setting of settings) {
        const value = parseInt(setting.value, 10);
        if (!isNaN(value) && value >= 0 && value <= 100) {
          switch (setting.key) {
            case "ai_price_weight":
              weights.priceWeight = value;
              break;
            case "ai_quality_weight":
              weights.qualityWeight = value;
              break;
            case "ai_provider_weight":
              weights.providerWeight = value;
              break;
          }
        }
      }

      const total = weights.priceWeight + weights.qualityWeight + weights.providerWeight;
      if (total !== 100) {
        const factor = 100 / total;
        weights.priceWeight = Math.round(weights.priceWeight * factor);
        weights.qualityWeight = Math.round(weights.qualityWeight * factor);
        weights.providerWeight = 100 - weights.priceWeight - weights.qualityWeight;
      }

      this.weightsCache = weights;
      this.weightsCacheExpiry = new Date(Date.now() + 5 * 60 * 1000);

      return weights;
    } catch (error) {
      console.warn("[Composite Scorer] Failed to load weights, using defaults:", error);
      return DEFAULT_WEIGHTS;
    }
  }

  /**
   * Get provider reliability score
   */
  async getProviderScore(providerId: string): Promise<number> {
    if (this.providerScores.has(providerId)) {
      return this.providerScores.get(providerId)!;
    }

    const baseScore = PROVIDER_SCORES[providerId] || 75;

    try {
      const provider = await db.query.providers.findFirst({
        where: eq(providers.id, providerId),
      });

      if (provider && provider.enabled) {
        this.providerScores.set(providerId, baseScore);
        return baseScore;
      }
    } catch (error) {
      console.warn("[Composite Scorer] Failed to get provider:", error);
    }

    this.providerScores.set(providerId, baseScore);
    return baseScore;
  }

  /**
   * Calculate price score (inverse - lower price = higher score)
   */
  calculatePriceScore(price: number, minPrice: number, maxPrice: number): number {
    if (minPrice === maxPrice) return 100;

    const range = maxPrice - minPrice;
    const normalized = (maxPrice - price) / range;

    return Math.round(normalized * 100);
  }

  /**
   * Score a single package
   */
  async scorePackage(
    pkg: PackageData,
    priceRange: { min: number; max: number },
    useAI: boolean = true
  ): Promise<CompositeScore> {
    const weights = await this.getWeights();
    const price = parseFloat(pkg.retailPrice);

    const priceScore = this.calculatePriceScore(price, priceRange.min, priceRange.max);

    let qualityScore = 75;
    let reasoning: string | undefined;
    let aiEnhanced = false;

    if (useAI) {
      try {
        const analysis = await packageAnalyzer.analyzePackage(pkg, true);
        qualityScore = analysis.valueScore;
        reasoning = analysis.reasoning;
        aiEnhanced = true;
      } catch (error) {
        console.warn("[Composite Scorer] AI analysis failed, using base quality score");
        const baseScores = packageAnalyzer.calculateBaseScores(pkg);
        qualityScore = baseScores.valueScore;
      }
    } else {
      const baseScores = packageAnalyzer.calculateBaseScores(pkg);
      qualityScore = baseScores.valueScore;
    }

    const providerScore = await this.getProviderScore(pkg.providerId);

    const priceContribution = (priceScore * weights.priceWeight) / 100;
    const qualityContribution = (qualityScore * weights.qualityWeight) / 100;
    const providerContribution = (providerScore * weights.providerWeight) / 100;

    const finalScore = Math.round(priceContribution + qualityContribution + providerContribution);

    return {
      packageId: pkg.id,
      finalScore,
      priceScore,
      qualityScore,
      providerScore,
      weights,
      breakdown: {
        priceContribution: Math.round(priceContribution),
        qualityContribution: Math.round(qualityContribution),
        providerContribution: Math.round(providerContribution),
      },
      reasoning,
      aiEnhanced,
    };
  }

  /**
   * Score multiple packages and find the best one
   */
  async scorePackages(
    packages: PackageData[],
    useAI: boolean = true
  ): Promise<PackageWithScore[]> {
    if (packages.length === 0) return [];

    const prices = packages.map(p => parseFloat(p.retailPrice));
    const priceRange = {
      min: Math.min(...prices),
      max: Math.max(...prices),
    };

    const scored = await Promise.all(
      packages.map(async (pkg) => ({
        ...pkg,
        compositeScore: await this.scorePackage(pkg, priceRange, useAI),
      }))
    );

    scored.sort((a, b) => b.compositeScore.finalScore - a.compositeScore.finalScore);

    return scored;
  }

  /**
   * Find the best package from a group
   */
  async findBestPackage(
    packages: PackageData[],
    useAI: boolean = true
  ): Promise<{ best: PackageWithScore; all: PackageWithScore[] } | null> {
    if (packages.length === 0) return null;

    const scored = await this.scorePackages(packages, useAI);

    return {
      best: scored[0],
      all: scored,
    };
  }

  /**
   * Clear caches
   */
  clearCache(): void {
    this.weightsCache = null;
    this.weightsCacheExpiry = null;
    this.providerScores.clear();
  }
}

export const compositeScorer = new CompositeScorer();

server/routes/unifiedPackages.ts.content:
"use strict";

import { Router, type Request, type Response } from "express";
import { storage } from "../storage";
import { db } from "../db";
import { asyncHandler } from "../lib/asyncHandler";
import { NotFoundError } from "../lib/errors";
import { unifiedPackages, platformSettings, providers, destinations, regions } from "@shared/schema";
import { eq, and, ilike, asc, desc, sql, or, isNotNull, gt, ne } from "drizzle-orm";
import * as ApiResponse from "../utils/response";

const router = Router();


router.get("/:id", async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const requestedCurrency = (req.query.currency as string) || "USD";

    // =========================
    // FETCH PACKAGE
    // =========================
    const pkg = await db.query.unifiedPackages.findFirst({
      where: and(
        eq(unifiedPackages.id, id),
        eq(unifiedPackages.isEnabled, true)
      ),
      with: {
        provider: true,
        destination: true,
        region: true,
      },
    });

    if (!pkg) {
      return ApiResponse.notFound(res, "Package not found");
    }

    // =========================
    // PRICE & CURRENCY FORMAT
    // =========================
    const currencies = await storage.getCurrencies();
    const provider = pkg.provider || null;

    const fromCurrency = currencies.find(c => c.code === "USD");
    const toCurrency = currencies.find(c => c.code === requestedCurrency);

    const wholesalePrice = parseFloat(pkg.wholesalePrice);
    const providerMargin = parseFloat(provider?.pricingMargin || "0");

    let retailPrice = wholesalePrice * (1 + providerMargin / 100);

    if (requestedCurrency !== "USD" && fromCurrency && toCurrency) {
      const fromRate = parseFloat(fromCurrency.conversionRate);
      const toRate = parseFloat(toCurrency.conversionRate);
      retailPrice = (retailPrice / fromRate) * toRate;
    }

    // =========================
    // FORMAT RESPONSE (SAME SHAPE)
    // =========================
    const formattedPackage = {
      id: pkg.id,
      slug: pkg.slug,
      title: pkg.title,

      dataAmount: pkg.dataAmount,
      dataMb: pkg.dataMb,

      validity: pkg.validity,
      validityDays: pkg.validityDays,

      price: retailPrice.toFixed(2),
      currency: requestedCurrency,
      wholesalePrice: wholesalePrice,
      type: pkg.type,

      isUnlimited: pkg.isUnlimited,
      isBestPrice: pkg.isBestPrice,
      isPopular: pkg.isPopular,
      isRecommended: pkg.isRecommended,
      isBestValue: pkg.isBestValue,
      isEnabled: pkg.isEnabled,

      providerId: pkg.providerId,
      providerName: provider?.name || "Unknown",
      providerSlug: provider?.slug || "unknown",

      operator: pkg.operator,
      operatorImage: pkg.operatorImage,
      coverage: pkg.coverage,

      packageGroupKey: pkg.packageGroupKey,
      countryCode: pkg.countryCode,
      countryName: pkg.countryName,

      regionId: pkg.regionId,
      region: pkg.region,

      voiceMinutes: pkg.voiceMinutes,
      smsCount: pkg.smsCount,
    };

    return ApiResponse.success(res, "Package fetched successfully", formattedPackage);

  } catch (error: any) {
    return ApiResponse.serverError(res, error.message);
  }
});



router.get("/", async (req: Request, res: Response) => {
  try {
    res.set("Cache-Control", "public, max-age=300");

    const requestedCurrency = (req.query.currency as string) || "USD";

    // =========================
    // PAGINATION
    // =========================
    const page = Math.max(parseInt(req.query.page as string) || 1, 1);
    const limit = Math.min(parseInt(req.query.limit as string) || 10, 100);
    const offset = (page - 1) * limit;

    // =========================
    // FILTERS
    // =========================
    const sort = req.query.sort as string | null;
    const filterUnlimited = req.query.isUnlimited === "true";
    const filterBestPrice = req.query.isBestPrice === "true";
    const filterPopular = req.query.isPopular === "true";
    const filterDataPack = req.query.dataPack === "true";
    const filterVoicePack = req.query.voicePack === "true";
    const filterSmsPack = req.query.smsPack === "true";
    const filterVoiceAndDataPack = req.query.voiceAndDataPack === "true";
    const filterVoiceAndSmsPack = req.query.voiceAndSmsPack === "true";
    const filterDataAndSmsPack = req.query.dataAndSmsPack === "true";
    const filterVoiceAndDataAndSmsPack = req.query.voiceAndDataAndSmsPack === "true";
    const search = (req.query.search as string)?.trim();
    const bestPriceParam = req.query.isBestPrice as string | null;
    const type = req.query.type

    // console.log(req.query);

    // =========================
    // BUILD WHERE CLAUSE
    // =========================
    const whereClauses: any[] = [eq(unifiedPackages.isEnabled, true)];

    if (filterUnlimited) whereClauses.push(eq(unifiedPackages.isUnlimited, true));
    if (filterBestPrice) whereClauses.push(eq(unifiedPackages.isBestPrice, true));
    if (filterPopular) whereClauses.push(eq(unifiedPackages.isPopular, true));

    if (filterDataPack) {
      whereClauses.push(
        and(
          eq(unifiedPackages.voiceMinutes, 0),
          eq(unifiedPackages.smsCount, 0)
        )
      );
    }

    if (filterVoicePack) {
      whereClauses.push(
        and(
          eq(unifiedPackages.dataMb, 0),
          eq(unifiedPackages.smsCount, 0)
        )
      );
    }

    if (filterSmsPack) {
      whereClauses.push(
        and(
          eq(unifiedPackages.voiceMinutes, 0),
          eq(unifiedPackages.dataMb, 0)
        )
      );
    }

    if (filterVoiceAndDataPack) {
      whereClauses.push(
        and(
          eq(unifiedPackages.smsCount, 0)
        )
      );
    }

    if (filterVoiceAndSmsPack) {
      whereClauses.push(
        and(
          eq(unifiedPackages.dataMb, 0)
        )
      );
    }

    if (filterDataAndSmsPack) {
      whereClauses.push(
        and(
          eq(unifiedPackages.voiceMinutes, 0)
        )
      );
    }

    if (filterVoiceAndDataAndSmsPack) {
      whereClauses.push(
        and(
          ne(unifiedPackages.voiceMinutes, 0),
          ne(unifiedPackages.dataMb, 0),
          ne(unifiedPackages.smsCount, 0)
        )
      );
    }


    if (type) {
      whereClauses.push(eq(unifiedPackages.type, type));
    }

    if (bestPriceParam === "true") {
      whereClauses.push(eq(unifiedPackages.isBestPrice, true));
    } else if (bestPriceParam === "false") {
      whereClauses.push(eq(unifiedPackages.isBestPrice, false));
    }

    if (search) {
      const searchTerm = `%${search.toLowerCase()}%`;
      const isNumericId = !isNaN(Number(search));

      whereClauses.push(
        or(
          // ✅ Search by package ID
          isNumericId
            ? eq(unifiedPackages.id, Number(search))
            : sql`CAST(${unifiedPackages.id} AS TEXT) ILIKE ${searchTerm}`,

          // Existing text search
          sql`LOWER(${unifiedPackages.slug}) ILIKE ${searchTerm}`,
          sql`LOWER(${unifiedPackages.title}) ILIKE ${searchTerm}`,
          sql`LOWER(${destinations.name}) ILIKE ${searchTerm}`,
          sql`LOWER(${regions.name}) ILIKE ${searchTerm}`,
          sql`LOWER(${providers.name}) ILIKE ${searchTerm}`
        )
      );
    }



    const whereCondition =
      whereClauses.length > 1 ? and(...whereClauses) : whereClauses[0];

    // =========================
    // SORTING
    // =========================
    let orderBy: any[];

    if (sort === "priceLowToHigh") {
      orderBy = [asc(unifiedPackages.retailPrice)];
    } else if (sort === "priceHighToLow") {
      orderBy = [desc(unifiedPackages.retailPrice)];
    } else {
      orderBy = [
        desc(unifiedPackages.isPopular),
        desc(unifiedPackages.isBestValue),
        desc(unifiedPackages.isUnlimited),
        desc(unifiedPackages.isRecommended),
        asc(unifiedPackages.retailPrice),
      ];
    }

    // =========================
    // TOTAL COUNT (FOR PAGINATION)
    // =========================
    const [{ count }] = await db
      .select({ count: sql<number>`count(*)` })
      .from(unifiedPackages)
      .where(whereCondition);

    const total = Number(count);
    const totalPages = Math.ceil(total / limit);

    // =========================
    // FETCH DATA
    // =========================
    const unifiedPackagesData = await db
      .select({
        pkg: unifiedPackages,
        provider: providers,
        destination: destinations,
        region: regions,
      })
      .from(unifiedPackages)
      .leftJoin(providers, eq(unifiedPackages.providerId, providers.id))
      .leftJoin(destinations, eq(unifiedPackages.destinationId, destinations.id))
      .leftJoin(regions, eq(unifiedPackages.regionId, regions.id))
      .where(whereCondition)
      .orderBy(...orderBy)
      .limit(limit)
      .offset(offset);

    if (!unifiedPackagesData.length) {
      return ApiResponse.success(res, "No packages found", {
        data: [],
        pagination: {
          total,
          totalPages,
          currentPage: page,
          limit,
        },
      });
    }

    // =========================
    // CURRENCY CONVERSION
    // =========================
    const currencies = await storage.getCurrencies();
    const fromCurrency = currencies.find(c => c.code === "USD");
    const toCurrency = currencies.find(c => c.code === requestedCurrency);

    const formattedPackages = unifiedPackagesData
      .filter(row => row.provider?.enabled)
      .map(row => {
        const { pkg, provider, destination, region } = row;

        const wholesale = parseFloat(pkg.wholesalePrice);
        const margin = parseFloat(provider?.pricingMargin || "0");

        let retailPrice = wholesale * (1 + margin / 100);

        if (requestedCurrency !== "USD" && fromCurrency && toCurrency) {
          retailPrice =
            (retailPrice / parseFloat(fromCurrency.conversionRate)) *
            parseFloat(toCurrency.conversionRate);
        }

        return {
          ...pkg,
          price: retailPrice.toFixed(2),
          currency: requestedCurrency,

          provider: provider
            ? {
              id: provider.id,
              name: provider.name,
              slug: provider.slug,
            }
            : null,

          destination: destination
            ? {
              id: destination.id,
              name: destination.name,
              slug: destination.slug,
              countryCode: destination.countryCode,
              flagEmoji: destination.flagEmoji,
              image: destination.image
            }
            : null,

          region: region
            ? {
              id: region.id,
              name: region.name,
              slug: region.slug,
              countries: region.countries,
              image: region.image
            }
            : null,
        };
      });

    // =========================
    // RESPONSE
    // =========================
    return ApiResponse.success(res, "Unified packages fetched successfully", {
      data: formattedPackages,
      pagination: {
        total,
        totalPages,
        currentPage: page,
        limit,
      },
    });
  } catch (error: any) {
    console.error("🔥 SERVER ERROR", error);
    return ApiResponse.serverError(res, error.message);
  }
});



