    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const discountAmount = parseFloat(data.unitPrice) * (parseFloat(data.discountPercent) / 100) * data.quantity;
  const subtotal = parseFloat(data.unitPrice) * data.quantity;

  const template = {
    subject: `New Bulk eSIM Quote for ${data.companyName}`,
