  app.post('/api/referrals/redeem-to-gift-card', requireAuth, async (req, res) => {
    const userId = req.userId;
    const { code, amount, currency, message, theme } = req.body;

    try {
      // Validate input
      if (!amount || amount <= 0) {
        return res.status(400).json({ error: 'Invalid amount' });
